static int
	IS_WORD_ID(LANGUAGE *LEXICON, int32_t WORD_ID)
{
	return (
		WORD_ID >= 0 &&
		WORD_ID < LEXICON->COUNT &&
		isalnum((uint8_t)LEXICON->STRINGS[WORD_ID][0])
	);
}

static int
	IS_CONTENT_WORD(ENGINE_STATE *ENGINE, int32_t WORD_ID)
{
	return (
		IS_WORD_ID(ENGINE->LOADED_BRAIN.LEXICON, WORD_ID) &&
		ENGINE->LOADED_BRAIN.LEXICON->USE_COUNTS[WORD_ID] <
			ENGINE->STOP_WORD_THRESHOLD
	);
}

static float
	INVERSE_FREQUENCY(ENGINE_STATE *ENGINE, int32_t WORD_ID)
{
	return (
		(float)log(
			(ENGINE->TOTAL_WORD_COUNT + 1.0) /
			(ENGINE->LOADED_BRAIN.LEXICON->USE_COUNTS[WORD_ID] + 1.0)
		)
	);
}

static int
	TEXT_TO_WORD_IDS(
		ENGINE_STATE *ENGINE, const char *INPUT_TEXT, int32_t *OUTPUT,
		int OUTPUT_SIZE, int LEARN_WORDS
	)
{
	SPLIT_WORD	*SPLIT_RESULT = malloc(1024 * sizeof(SPLIT_WORD));
	int			WORD_COUNT = SPLIT_WORDS(INPUT_TEXT, SPLIT_RESULT, 1024);
	int			ID_COUNT = 0;
	int			WORD_INDEX;

	for (
		WORD_INDEX = 0;
		WORD_INDEX < WORD_COUNT && ID_COUNT < OUTPUT_SIZE;
		WORD_INDEX++
	)
	{
		int32_t	WORD_ID;

		if (LEARN_WORDS)
			WORD_ID = LANGUAGE_ADD(
				ENGINE->LOADED_BRAIN.LEXICON,
				SPLIT_RESULT[WORD_INDEX].WORD_TEXT,
				SPLIT_RESULT[WORD_INDEX].IS_CAPITALIZED
			);
		else
			WORD_ID = LANGUAGE_FIND(
				ENGINE->LOADED_BRAIN.LEXICON, SPLIT_RESULT[WORD_INDEX].WORD_TEXT
			);

		if (WORD_ID < 0)
			WORD_ID = LANGUAGE_ADD(
				ENGINE->LOADED_BRAIN.LEXICON,
				SPLIT_RESULT[WORD_INDEX].WORD_TEXT,
				SPLIT_RESULT[WORD_INDEX].IS_CAPITALIZED
			);

		OUTPUT[ID_COUNT++] = WORD_ID;
	}

	free(SPLIT_RESULT);

	return (ID_COUNT);
}

static int
	WORD_IDS_TO_TOKENS(
		LANGUAGE *LEXICON, const int32_t *WORD_IDS, int ID_COUNT,
		int32_t *OUTPUT, int OUTPUT_SIZE
	)
{
	int	TOKEN_COUNT = 0;
	int	ID_INDEX;

	for (
		ID_INDEX = 0;
		ID_INDEX < ID_COUNT && TOKEN_COUNT < OUTPUT_SIZE;
		ID_INDEX++
	)
	{
		int32_t	WORD_ID = WORD_IDS[ID_INDEX];

		if (WORD_ID < 0 || WORD_ID >= LEXICON->COUNT)
			continue ;

		if (LEXICON->LEXEME_TO_TOKEN[WORD_ID] >= 0)
		{
			OUTPUT[TOKEN_COUNT++] = LEXICON->LEXEME_TO_TOKEN[WORD_ID];
			continue ;
		}

		SPLIT_WORD	SPELLED_WORD;

		snprintf(
			SPELLED_WORD.WORD_TEXT, sizeof SPELLED_WORD.WORD_TEXT, "%s",
			LEXICON->STRINGS[WORD_ID]
		);
		SPELLED_WORD.IS_CAPITALIZED = 0;
		TOKEN_COUNT += ENCODE_WORDS(
			LEXICON, &SPELLED_WORD, 1, OUTPUT + TOKEN_COUNT,
			OUTPUT_SIZE - TOKEN_COUNT, 0
		);
	}

	return (TOKEN_COUNT);
}

static int
	TOKENS_TO_WORD_IDS(
		ENGINE_STATE *ENGINE, const int32_t *TOKENS, int TOKEN_COUNT,
		int32_t *OUTPUT, int OUTPUT_SIZE
	)
{
	char		WORD_BUFFER[4096];
	int			ID_COUNT = 0;
	int			TOKEN_INDEX = 0;
	LANGUAGE	*LEXICON = ENGINE->LOADED_BRAIN.LEXICON;

	while (TOKEN_INDEX < TOKEN_COUNT && ID_COUNT < OUTPUT_SIZE)
	{
		int32_t	TOKEN = TOKENS[TOKEN_INDEX];

		if (TOKEN >= TOKEN_FIRST_WORD)
		{
			OUTPUT[ID_COUNT++] = LEXICON->TOKEN_TO_LEXEME[TOKEN];
			TOKEN_INDEX++;
			continue ;
		}

		if (TOKEN >= TOKEN_FIRST_CHARACTER && TOKEN < TOKEN_FIRST_WORD)
		{
			int	SPELL_END = TOKEN_INDEX + 1;

			while (
				SPELL_END < TOKEN_COUNT &&
				TOKENS[SPELL_END] >= TOKEN_FIRST_CHARACTER + CHARACTER_COUNT &&
				TOKENS[SPELL_END] < TOKEN_FIRST_WORD
			)
				SPELL_END++;

			DECODE_TOKENS(
				LEXICON, TOKENS + TOKEN_INDEX, SPELL_END - TOKEN_INDEX,
				WORD_BUFFER, sizeof WORD_BUFFER, NULL, 0
			);

			char	*CURSOR;

			for (CURSOR = WORD_BUFFER; *CURSOR; CURSOR++)
				*CURSOR = (char)tolower(*CURSOR);

			OUTPUT[ID_COUNT++] = LANGUAGE_ADD(LEXICON, WORD_BUFFER, 0);
			TOKEN_INDEX = SPELL_END;
			continue ;
		}

		TOKEN_INDEX++;
	}

	return (ID_COUNT);
}

static void
	WORD_IDS_TO_TEXT(
		ENGINE_STATE *ENGINE, const int32_t *WORD_IDS, int ID_COUNT,
		char *OUTPUT, int OUTPUT_SIZE
	)
{
	int32_t	*TOKENS = malloc(4096 * 4);
	int		TOKEN_COUNT = WORD_IDS_TO_TOKENS(
		ENGINE->LOADED_BRAIN.LEXICON, WORD_IDS, ID_COUNT, TOKENS, 4096
	);

	DECODE_TOKENS(
		ENGINE->LOADED_BRAIN.LEXICON, TOKENS, TOKEN_COUNT, OUTPUT, OUTPUT_SIZE,
		ENGINE->NAMES, ENGINE->NAME_COUNT
	);
	free(TOKENS);
}

static void
	ADD_KNOWN_NAME(ENGINE_STATE *ENGINE, const char *NAME_TEXT)
{
	if (!NAME_TEXT || !*NAME_TEXT || ENGINE->NAME_COUNT >= 16)
		return ;

	int	NAME_INDEX;

	for (NAME_INDEX = 0; NAME_INDEX < ENGINE->NAME_COUNT; NAME_INDEX++)
		if (!strcmp(ENGINE->NAMES[NAME_INDEX], NAME_TEXT))
			return ;

	snprintf(ENGINE->NAME_BUFFERS[ENGINE->NAME_COUNT], 64, "%s", NAME_TEXT);

	char	*CURSOR;

	for (CURSOR = ENGINE->NAME_BUFFERS[ENGINE->NAME_COUNT]; *CURSOR; CURSOR++)
		*CURSOR = (char)tolower(*CURSOR);

	ENGINE->NAMES[ENGINE->NAME_COUNT] =
		ENGINE->NAME_BUFFERS[ENGINE->NAME_COUNT];
	ENGINE->NAME_COUNT++;
}

static void
	COLLECT_NAMES_FROM(ENGINE_STATE *ENGINE, MEMORY_FILE *MEMORY_SOURCE)
{
	LANGUAGE	*LEXICON = ENGINE->LOADED_BRAIN.LEXICON;
	int32_t		NAME_ID = LANGUAGE_FIND(LEXICON, "name");
	int32_t		IS_ID = LANGUAGE_FIND(LEXICON, "is");
	int			RECORD_INDEX;

	for (RECORD_INDEX = 0; RECORD_INDEX < MEMORY_SOURCE->COUNT; RECORD_INDEX++)
	{
		MEMORY_RECORD	*RECORD = &MEMORY_SOURCE->RECORDS[RECORD_INDEX];
		uint32_t		POSITION;

		for (POSITION = 0; POSITION + 2 < RECORD->ID_COUNT; POSITION++)
			if (
				RECORD->IDS[POSITION] == NAME_ID &&
				RECORD->IDS[POSITION + 1] == IS_ID &&
				IS_WORD_ID(LEXICON, RECORD->IDS[POSITION + 2])
			)
				ADD_KNOWN_NAME(
					ENGINE, LEXICON->STRINGS[RECORD->IDS[POSITION + 2]]
				);
	}
}

