/* one of Lucy's own sentences: mind/language/sayings.txt has the last word
 * on how it is said, DEFAULT is how it is said without the file; {1} to {4}
 * in either are FIRST to FOURTH */
static const char
	*SAYING_LIST(
		ENGINE_STATE *ENGINE, const char *KEY, const char *DEFAULT,
		char *OUTPUT, int OUTPUT_SIZE, const char *const *DETAILS,
		int DETAIL_COUNT
	)
{
	char	FILLED[4096];

	if (!ENGINE->SAYINGS_OPENED)
	{
		SAYINGS_OPEN(&ENGINE->SAYINGS, SAYINGS_PATH);
		ENGINE->SAYINGS_OPENED = 1;
	}

	SAYINGS_SAY(
		&ENGINE->SAYINGS, KEY, DEFAULT, DETAILS, DETAIL_COUNT, FILLED,
		sizeof FILLED
	);
	snprintf(OUTPUT, (size_t)OUTPUT_SIZE, "%s", FILLED);

	return (OUTPUT);
}

static const char
	*SAYING(
		ENGINE_STATE *ENGINE, const char *KEY, const char *DEFAULT,
		char *OUTPUT, int OUTPUT_SIZE, const char *FIRST, const char *SECOND,
		const char *THIRD, const char *FOURTH
	)
{
	const char	*DETAILS[4];

	DETAILS[0] = FIRST;
	DETAILS[1] = SECOND;
	DETAILS[2] = THIRD;
	DETAILS[3] = FOURTH;

	return (SAYING_LIST(ENGINE, KEY, DEFAULT, OUTPUT, OUTPUT_SIZE, DETAILS, 4));
}

/* the same for a skill: "package hint" with the package's name */
static int
	SKILL_SAYING(
		void *ENGINE, const char *KEY, const char *DEFAULT, const char *FIRST,
		const char *SECOND, char *OUTPUT, int OUTPUT_SIZE
	)
{
	ENGINE_STATE	*STATE = ENGINE;
	const char		*DETAILS[2];
	char			FILLED[4096];
	int				FOUND;

	DETAILS[0] = FIRST;
	DETAILS[1] = SECOND;

	if (!STATE->SAYINGS_OPENED)
	{
		SAYINGS_OPEN(&STATE->SAYINGS, SAYINGS_PATH);
		STATE->SAYINGS_OPENED = 1;
	}

	FOUND = SAYINGS_SAY(
		&STATE->SAYINGS, KEY, DEFAULT, DETAILS, 2, FILLED, sizeof FILLED
	);

	if (OUTPUT && OUTPUT_SIZE > 0)
		snprintf(OUTPUT, (size_t)OUTPUT_SIZE, "%s", FILLED);

	return (FOUND);
}

/* a skill changed something in the files folder: it can be undone */
static void
	SKILL_LOGS_CHANGE(
		void *ENGINE, const char *VERB, const char *FROM, const char *TO
	)
{
	LOG_UNDO((ENGINE_STATE *)ENGINE, VERB, FROM, TO);
}

/* what the memory packages know, for a skill: "cat", "legs" -> "4" */
static int
	SKILL_KNOWS(
		void *ENGINE, const char *THING, const char *PROPERTY, char *VALUE,
		int VALUE_SIZE
	)
{
	ENGINE_STATE	*STATE = ENGINE;

	return (
		STATE->PACKAGES_OPENED &&
		PACKAGES_KNOW(&STATE->PACKAGES, THING, PROPERTY, VALUE, VALUE_SIZE)
	);
}

static int
	SKILL_THINGS_WITH(
		void *ENGINE, const char *PROPERTY, const char *VALUE, char *OUTPUT,
		int OUTPUT_SIZE
	)
{
	ENGINE_STATE	*STATE = ENGINE;

	if (!STATE->PACKAGES_OPENED)
	{
		if (OUTPUT && OUTPUT_SIZE)
			OUTPUT[0] = 0;

		return (0);
	}

	return (
		PACKAGES_THINGS_WITH(
			&STATE->PACKAGES, PROPERTY, VALUE, OUTPUT, OUTPUT_SIZE
		)
	);
}

static int
	SKILL_PACKAGE_FOR(
		void *ENGINE, const char *WORD, char *OUTPUT, int OUTPUT_SIZE
	)
{
	ENGINE_STATE	*STATE = ENGINE;

	return (
		STATE->PACKAGES_OPENED &&
		PACKAGES_PACKAGE_FOR(&STATE->PACKAGES, WORD, OUTPUT, OUTPUT_SIZE)
	);
}

/* the user's messages before this one, oldest first */
static int
	SKILL_RECENT(void *ENGINE, char *OUTPUT, int OUTPUT_SIZE)
{
	ENGINE_STATE	*STATE = ENGINE;
	int				LENGTH = 0;
	int				INDEX;

	if (OUTPUT_SIZE)
		OUTPUT[0] = 0;

	for (
		INDEX = 0;
		INDEX < STATE->RECENT_USER_COUNT && LENGTH < OUTPUT_SIZE - 1;
		INDEX++
	)
		LENGTH += snprintf(
			OUTPUT + LENGTH, OUTPUT_SIZE - LENGTH, "%s\n",
			STATE->RECENT_USER[INDEX]
		);

	return (STATE->RECENT_USER_COUNT);
}

/* someone taught something about WORD ("A zebra is a striped horse") */
static int
	SKILL_HEARD_OF(void *ENGINE, const char *WORD)
{
	ENGINE_STATE	*STATE = ENGINE;

	return (STATE->TAUGHT && TAUGHT_HAS_WORD(STATE->TAUGHT, WORD));
}

/* the skills in the skills folder, with what they may know about the chat */
static void
	OPEN_SKILLS(ENGINE_STATE *ENGINE)
{
	if (ENGINE->SKILLS_OPENED)
		return ;

	SKILLS_OPEN(&ENGINE->SKILLS, SKILLS_DIRECTORY);
	ENGINE->SKILLS.HOST.FILES_FOLDER = "files";
	ENGINE->SKILLS.HOST.MIND_FOLDER = MIND_DIRECTORY;
	ENGINE->SKILLS.HOST.USER_NAME = ENGINE->USER_NAME;
	ENGINE->SKILLS.HOST.ASSISTANT_NAME = ENGINE->ASSISTANT_NAME;
	ENGINE->SKILLS.HOST.ENGINE = ENGINE;
	ENGINE->SKILLS.HOST.LOG_CHANGE = SKILL_LOGS_CHANGE;
	ENGINE->SKILLS.HOST.KNOW = SKILL_KNOWS;
	ENGINE->SKILLS.HOST.THINGS_WITH = SKILL_THINGS_WITH;
	ENGINE->SKILLS.HOST.PACKAGE_FOR = SKILL_PACKAGE_FOR;
	ENGINE->SKILLS.HOST.RECENT = SKILL_RECENT;
	ENGINE->SKILLS.HOST.HEARD_OF = SKILL_HEARD_OF;
	ENGINE->SKILLS.HOST.SAY = SKILL_SAYING;
	ENGINE->SKILLS_OPENED = 1;
}

static int
	OPEN_ENGINE(ENGINE_STATE *ENGINE)
{
	if (BRAIN_OPEN(&ENGINE->LOADED_BRAIN, 1, ENGINE->LEARNING_ON ? 1 : -1))
		return (-1);

	ENGINE->LOADED_BRAIN.NEURAL_WEB->GROWTH_STATE.ENABLED = 0;

	if (ENGINE->LEARNING_ON && !ENGINE->LOADED_BRAIN.NEURAL_WEB->HALF_PRECISION)
	{
		int	NEURONS_BEFORE = ENGINE->LOADED_BRAIN.NEURAL_WEB->NEURON_COUNT;

		LEARN_PERSONAL(ENGINE->LOADED_BRAIN.NEURAL_WEB, 64, 0);

		if (ENGINE->LOADED_BRAIN.NEURAL_WEB->NEURON_COUNT != NEURONS_BEFORE)
			ENGINE->BRAIN_DIRTY = 1;

		LEARN_FREEZE(ENGINE->LOADED_BRAIN.NEURAL_WEB, 1);
	}

	LANGUAGE	*LEXICON = ENGINE->LOADED_BRAIN.LEXICON;

	if (ENGINE->LOADED_BRAIN.NEURAL_WEB->HALF_PRECISION)
		ENGINE->TOKEN_DO = LANGUAGE_TOKEN(LEXICON, SPECIAL_DO);
	else
		ENGINE->TOKEN_DO =
			BRAIN_SPECIAL_TOKEN(&ENGINE->LOADED_BRAIN, SPECIAL_DO);

	if (ENGINE->LOADED_BRAIN.NEURAL_WEB->HALF_PRECISION)
		ENGINE->TOKEN_RESULT = LANGUAGE_TOKEN(LEXICON, SPECIAL_RESULT);
	else
		ENGINE->TOKEN_RESULT =
			BRAIN_SPECIAL_TOKEN(&ENGINE->LOADED_BRAIN, SPECIAL_RESULT);

	if (ENGINE->LOADED_BRAIN.NEURAL_WEB->HALF_PRECISION)
		ENGINE->TOKEN_MORE = LANGUAGE_TOKEN(LEXICON, SPECIAL_MORE);
	else
		ENGINE->TOKEN_MORE =
			BRAIN_SPECIAL_TOKEN(&ENGINE->LOADED_BRAIN, SPECIAL_MORE);

	uint32_t	*SORTED_COUNTS = malloc(LEXICON->COUNT * 4);

	ENGINE->TOTAL_WORD_COUNT = 0;

	int32_t	WORD_INDEX;

	for (WORD_INDEX = 0; WORD_INDEX < LEXICON->COUNT; WORD_INDEX++)
	{
		SORTED_COUNTS[WORD_INDEX] = LEXICON->USE_COUNTS[WORD_INDEX];
		ENGINE->TOTAL_WORD_COUNT += LEXICON->USE_COUNTS[WORD_INDEX];
	}

	int	POSITION;

	if (150 < LEXICON->COUNT)
		POSITION = 150;
	else
		POSITION = LEXICON->COUNT - 1;

	int	INDEX;

	for (INDEX = 0; INDEX <= POSITION; INDEX++)
	{
		int		BEST_INDEX = INDEX;
		int32_t	CANDIDATE_INDEX;

		for (
			CANDIDATE_INDEX = INDEX + 1;
			CANDIDATE_INDEX < LEXICON->COUNT;
			CANDIDATE_INDEX++
		)
			if (SORTED_COUNTS[CANDIDATE_INDEX] > SORTED_COUNTS[BEST_INDEX])
				BEST_INDEX = CANDIDATE_INDEX;

		uint32_t	TEMPORARY = SORTED_COUNTS[INDEX];

		SORTED_COUNTS[INDEX] = SORTED_COUNTS[BEST_INDEX];
		SORTED_COUNTS[BEST_INDEX] = TEMPORARY;
	}

	ENGINE->STOP_WORD_THRESHOLD = SORTED_COUNTS[POSITION];
	free(SORTED_COUNTS);
	MEMORY_FILE_LOAD(&ENGINE->FACTS, GLOBAL_DIRECTORY "/facts.db");
	MEMORY_FILE_LOAD(&ENGINE->SELF_FACTS, GLOBAL_DIRECTORY "/self.db");

	{
		long	FILE_LENGTH;
		char	*SELF_TEXT = READ_WHOLE_FILE(SELF_PATH, &FILE_LENGTH);

		if (SELF_TEXT)
		{
			char	*LINE_START = SELF_TEXT;

			{
				const char	*NAME_START = strstr(SELF_TEXT, "My name is ");

				if (NAME_START)
				{
					NAME_START += 11;

					int	POSITION = 0;

					while (
						NAME_START[POSITION] &&
						NAME_START[POSITION] != '.' &&
						NAME_START[POSITION] != '\n' &&
						NAME_START[POSITION] != '\r' &&
						POSITION < 30
					)
					{
						ENGINE->ASSISTANT_NAME[POSITION] = NAME_START[POSITION];
						POSITION++;
					}

					ENGINE->ASSISTANT_NAME[POSITION] = 0;

					char	WANTED_LINE[64];

					snprintf(
						WANTED_LINE, sizeof WANTED_LINE, "my name is %s",
						ENGINE->ASSISTANT_NAME
					);
					LOWERCASE_STRING(WANTED_LINE);

					int	INDEX;

					for (INDEX = 0; INDEX < ENGINE->SELF_FACTS.COUNT; INDEX++)
					{
						char	RECORD_TEXT[600];

						WORD_IDS_TO_TEXT(
							ENGINE, ENGINE->SELF_FACTS.RECORDS[INDEX].IDS,
							(int)ENGINE->SELF_FACTS.RECORDS[INDEX].ID_COUNT,
							RECORD_TEXT, sizeof RECORD_TEXT
						);
						LOWERCASE_STRING(RECORD_TEXT);

						if (
							!strncmp(RECORD_TEXT, "my name is ", 11) &&
							strncmp(
								RECORD_TEXT, WANTED_LINE, strlen(WANTED_LINE)
							)
						)
						{
							free(ENGINE->SELF_FACTS.RECORDS[INDEX].IDS);
							ENGINE->SELF_FACTS.RECORDS[INDEX] =
								ENGINE->SELF_FACTS
									.RECORDS[ENGINE->SELF_FACTS.COUNT - 1];
							ENGINE->SELF_FACTS.COUNT--;
							ENGINE->SELF_FACTS.IS_DIRTY = 1;
							INDEX--;
						}
					}
				}
			}

			while (*LINE_START)
			{
				char	*LINE_END = strchr(LINE_START, '\n');

				if (LINE_END)
					*LINE_END = 0;

				int32_t	LINE_IDS[256];
				int		LINE_ID_COUNT =
					TEXT_TO_WORD_IDS(ENGINE, LINE_START, LINE_IDS, 256, 1);

				if (
					LINE_ID_COUNT &&
					FIND_MEMORY_RECORD(
						&ENGINE->SELF_FACTS, LINE_IDS, LINE_ID_COUNT
					) < 0
				)
					MEMORY_FILE_ADD(
						&ENGINE->SELF_FACTS, MEMORY_KIND_SELF, LINE_IDS,
						LINE_ID_COUNT, 0
					);

				if (!LINE_END)
					break ;

				LINE_START = LINE_END + 1;
			}

			free(SELF_TEXT);
			MEMORY_FILE_SAVE(&ENGINE->SELF_FACTS);
		}
	}

	snprintf(
		ENGINE->CHAT_DIRECTORY, sizeof ENGINE->CHAT_DIRECTORY,
		LOCALS_DIRECTORY "/chat_%s", ENGINE->CHAT_NAME
	);

	char	MEMORY_PATH[600];

	MAKE_DIRECTORY_PATH(ENGINE->CHAT_DIRECTORY);
	CHAT_FILE_PATH(ENGINE, MEMORY_PATH, "notes.db");
	MEMORY_FILE_LOAD(&ENGINE->NOTES, MEMORY_PATH);

	/* what this person told about themselves is theirs, in every chat:
	 * mind/memory/persons/NAME/facts.db */
	PERSON_PATH(ENGINE->USER_NAME, "", MEMORY_PATH, sizeof MEMORY_PATH);
	MAKE_DIRECTORY_PATH(MEMORY_PATH);
	PERSON_PATH(ENGINE->USER_NAME, "facts.db", MEMORY_PATH, sizeof MEMORY_PATH);

	if (FILE_EXISTS(MEMORY_PATH))
		MEMORY_FILE_LOAD(&ENGINE->PEOPLE, MEMORY_PATH);
	else
	{
		MEMORY_FILE_LOAD(&ENGINE->PEOPLE, MEMORY_PATH);
		GATHER_PERSON_FACTS(ENGINE, ENGINE->USER_NAME);

		if (ENGINE->PEOPLE.COUNT)
			ENGINE->PEOPLE.IS_DIRTY = 1;
	}

	snprintf(
		ENGINE->PEOPLE.PATH, sizeof ENGINE->PEOPLE.PATH, "%s", MEMORY_PATH
	);
	CHAT_FILE_PATH(ENGINE, ENGINE->THOUGHT_PATH, "thought.db");
	THOUGHT_LOAD(&ENGINE->WORKING_MEMORY, ENGINE->THOUGHT_PATH);
	ENGINE->WORKING_MEMORY.IN_MIND_COUNT = 0;
	ENGINE->WORKING_MEMORY.RECALLED_FILE =
		ENGINE->WORKING_MEMORY.RECALLED_RECORD = -1;
	ADD_KNOWN_NAME(ENGINE, ENGINE->USER_NAME);
	COLLECT_NAMES_FROM(ENGINE, &ENGINE->SELF_FACTS);
	COLLECT_NAMES_FROM(ENGINE, &ENGINE->PEOPLE);
	LOAD_TOPICS(ENGINE);
	LOAD_TAUGHT(ENGINE);
	OPEN_SKILLS(ENGINE);
	CALCULATOR_LOAD(GLOBAL_DIRECTORY "/formulas.txt");
	REFLEX_LOAD(&ENGINE->REFLEXES, GLOBAL_DIRECTORY "/reflexes.txt");

	if (!ENGINE->REFLEXES.FIND_FUNCTION)
		REFLEX_COMPILE(&ENGINE->REFLEXES);

	ENGINE->LAST_REFLEX = ENGINE->LAST_OBSERVED_REFLEX = -1;

	char	GOAL_PATH[600];

	CHAT_FILE_PATH(ENGINE, GOAL_PATH, "goal.txt");

	long	READ_LENGTH;
	char	*GOAL_TEXT = READ_WHOLE_FILE(GOAL_PATH, &READ_LENGTH);

	ENGINE->GOAL_LENGTH = 0;

	if (GOAL_TEXT)
	{
		ENGINE->GOAL_LENGTH = TEXT_TO_WORD_IDS(
			ENGINE, GOAL_TEXT, ENGINE->GOAL_IDS, WORKING_MEMORY_IDS, 1
		);
		free(GOAL_TEXT);
	}

	if (!ENGINE->KNOWN_CASINGS)
		ENGINE->KNOWN_CASINGS = malloc(4096 * sizeof *ENGINE->KNOWN_CASINGS);

	ENGINE->KNOWN_CASING_COUNT = 0;

	char	*CASE_TEXT =
		READ_WHOLE_FILE(GLOBAL_DIRECTORY "/case.txt", &READ_LENGTH);

	if (CASE_TEXT)
	{
		char	*LINE_START = CASE_TEXT;

		while (*LINE_START && ENGINE->KNOWN_CASING_COUNT < 4096)
		{
			char	*LINE_END = strchr(LINE_START, '\n');

			if (LINE_END)
				*LINE_END = 0;

			size_t	LINE_LENGTH = strlen(LINE_START);

			while (LINE_LENGTH && LINE_START[LINE_LENGTH - 1] == '\r')
				LINE_START[--LINE_LENGTH] = 0;

			if (LINE_LENGTH && LINE_LENGTH < 48)
				snprintf(
					ENGINE->KNOWN_CASINGS[ENGINE->KNOWN_CASING_COUNT++], 48,
					"%s", LINE_START
				);

			if (!LINE_END)
				break ;

			LINE_START = LINE_END + 1;
		}

		free(CASE_TEXT);
	}

	return (0);
}

static uint64_t
	VOCABULARY_TAG(ENGINE_STATE *ENGINE)
{
	uint64_t	HASH_VALUE = (unsigned long long)1469598103934665603;
	int32_t		TOKEN_INDEX;

	for (
		TOKEN_INDEX = 0;
		TOKEN_INDEX < ENGINE->LOADED_BRAIN.LEXICON->TOKEN_COUNT;
		TOKEN_INDEX++
	)
	{
		HASH_VALUE ^= (uint64_t)(uint32_t
		)ENGINE->LOADED_BRAIN.LEXICON->TOKEN_TO_LEXEME[TOKEN_INDEX];
		HASH_VALUE *= (unsigned long long)1099511628211;
	}

	return (HASH_VALUE ^ (uint64_t)ENGINE->LOADED_BRAIN.LEXICON->TOKEN_COUNT);
}

static int32_t
	FLIP_PERSON_WORD(ENGINE_STATE *ENGINE, int32_t WORD_ID, int32_t PREVIOUS_ID)
{
	static const char	*FIRST_PERSON[16] = {
		"i", "my", "me", "mine", "myself", "i'm", "im", "i've", "i'll", "i'd",
		"our", "ours", "we", "us", "we're", "ourselves"
	};
	static const char	*SECOND_PERSON[16] = {
		"you", "your", "you", "yours", "yourself", "you're", "you're", "you've",
		"you'll", "you'd", "your", "yours", "you", "you", "you're", "yourselves"
	};
	LANGUAGE			*LEXICON = ENGINE->LOADED_BRAIN.LEXICON;
	const char			*WORD_TEXT = LEXICON->STRINGS[WORD_ID];
	const char			*REPLACEMENT = NULL;
	int					PRONOUN_INDEX;

	for (PRONOUN_INDEX = 0; PRONOUN_INDEX < 16; PRONOUN_INDEX++)
		if (!strcmp(WORD_TEXT, FIRST_PERSON[PRONOUN_INDEX]))
			REPLACEMENT = SECOND_PERSON[PRONOUN_INDEX];

	if (
		PREVIOUS_ID >= 0 &&
		(
			!strcmp(LEXICON->STRINGS[PREVIOUS_ID], "i") ||
			!strcmp(LEXICON->STRINGS[PREVIOUS_ID], "we")
		)
	)
	{
		if (!strcmp(WORD_TEXT, "am"))
			REPLACEMENT = "are";

		if (!strcmp(WORD_TEXT, "was"))
			REPLACEMENT = "were";
	}

	if (!REPLACEMENT)
		return (WORD_ID);

	int32_t	FLIPPED_ID = LANGUAGE_FIND(LEXICON, REPLACEMENT);

	if (FLIPPED_ID >= 0)
		return (FLIPPED_ID);

	return (WORD_ID);
}

static int
	NEIGHBOR_TOKENS(
		ENGINE_STATE *ENGINE, const int32_t *ORIGINAL_IDS, int ID_COUNT,
		int32_t *TOKENS, uint8_t *KEEP_MASK, int TOKEN_LIMIT
	)
{
	int		TOKEN_COUNT = 0;
	int32_t	FLIPPED_IDS[256];

	if (ID_COUNT > 256)
		ID_COUNT = 256;

	int	ID_INDEX;

	for (ID_INDEX = 0; ID_INDEX < ID_COUNT; ID_INDEX++)
		FLIPPED_IDS[ID_INDEX] = FLIP_PERSON_WORD(
			ENGINE, ORIGINAL_IDS[ID_INDEX],
			ID_INDEX ? ORIGINAL_IDS[ID_INDEX - 1] : -1
		);

	TOKENS[TOKEN_COUNT] = TOKEN_CODE_TURN;
	KEEP_MASK[TOKEN_COUNT++] = 0;

	for (
		ID_INDEX = 0;
		ID_INDEX < ID_COUNT && TOKEN_COUNT < TOKEN_LIMIT - 8;
		ID_INDEX++
	)
	{
		int32_t	WORD_TOKENS[64];
		int		WORD_TOKEN_COUNT = WORD_IDS_TO_TOKENS(
			ENGINE->LOADED_BRAIN.LEXICON, &FLIPPED_IDS[ID_INDEX], 1,
			WORD_TOKENS, 64
		);
		int		KEEP = IS_CONTENT_WORD(ENGINE, FLIPPED_IDS[ID_INDEX]);
		int		WORD_TOKEN_INDEX;

		for (
			WORD_TOKEN_INDEX = 0;
			WORD_TOKEN_INDEX < WORD_TOKEN_COUNT && TOKEN_COUNT < TOKEN_LIMIT;
			WORD_TOKEN_INDEX++
		)
		{
			TOKENS[TOKEN_COUNT] = WORD_TOKENS[WORD_TOKEN_INDEX];
			KEEP_MASK[TOKEN_COUNT++] = (uint8_t)KEEP;
		}
	}

	return (TOKEN_COUNT);
}

static void
	STORE_NEIGHBOR(
		ENGINE_STATE *ENGINE, const int32_t *WORD_IDS, int ID_COUNT,
		int SAVE_LINE_TEXT
	)
{
	if (
		!ENGINE->NEIGHBORS_ON ||
		ENGINE->LOADED_BRAIN.NEURAL_WEB->CONFIGURATION.MAXIMUM_LENGTH < 8
	)
		return ;

	int32_t	TOKENS[512];
	uint8_t	KEEP_MASK[512];
	int		TOKEN_COUNT = NEIGHBOR_TOKENS(
		ENGINE, WORD_IDS, ID_COUNT, TOKENS, KEEP_MASK,
		ENGINE->LOADED_BRAIN.NEURAL_WEB->CONFIGURATION.MAXIMUM_LENGTH < 512
			? ENGINE->LOADED_BRAIN.NEURAL_WEB->CONFIGURATION.MAXIMUM_LENGTH
			: 512
	);
	int		ANY_KEPT = 0;
	int		TOKEN_INDEX;

	for (TOKEN_INDEX = 0; TOKEN_INDEX < TOKEN_COUNT; TOKEN_INDEX++)
		ANY_KEPT |= KEEP_MASK[TOKEN_INDEX];

	if (!ANY_KEPT)
		return ;

	ENGINE->NEIGHBOR_INDEX.VOCABULARY_TAG = VOCABULARY_TAG(ENGINE);
	NEAREST_NEIGHBOR_ADD(
		&ENGINE->NEIGHBOR_INDEX, ENGINE->LOADED_BRAIN.NEURAL_WEB, TOKENS,
		TOKEN_COUNT, KEEP_MASK
	);
	ENGINE->PREFIX_CACHE_VALID = 0;

	if (SAVE_LINE_TEXT)
	{
		char	LINE_TEXT[2048];

		WORD_IDS_TO_TEXT(
			ENGINE, WORD_IDS, ID_COUNT, LINE_TEXT, sizeof LINE_TEXT
		);

		FILE	*STREAM = fopen(GLOBAL_DIRECTORY "/instant.txt", "ab");

		if (STREAM)
		{
			fprintf(STREAM, "%s\n", LINE_TEXT);
			fclose(STREAM);
		}
	}
}

static void
	OPEN_NEIGHBOR_INDEX(ENGINE_STATE *ENGINE)
{
	NEAREST_NEIGHBOR_INITIALIZE(
		&ENGINE->NEIGHBOR_INDEX,
		ENGINE->LOADED_BRAIN.NEURAL_WEB->CONFIGURATION.DIMENSION, 2000
	);

	if (!ENGINE->NEIGHBORS_ON)
		return ;

	uint64_t	VOCABULARY_HASH = VOCABULARY_TAG(ENGINE);

	if (
		NEAREST_NEIGHBOR_LOAD(
			&ENGINE->NEIGHBOR_INDEX, ENGINE->LOADED_BRAIN.NEURAL_WEB,
			GLOBAL_DIRECTORY "/instant.bin", VOCABULARY_HASH
		) == 0
	)
		return ;

	NEAREST_NEIGHBOR_CLEAR(&ENGINE->NEIGHBOR_INDEX);

	long	FILE_LENGTH;
	char	*FILE_TEXT =
		READ_WHOLE_FILE(GLOBAL_DIRECTORY "/instant.txt", &FILE_LENGTH);

	if (!FILE_TEXT)
		return ;

	char	*LINE_START = FILE_TEXT;

	while (*LINE_START)
	{
		char	*LINE_END = strchr(LINE_START, '\n');

		if (LINE_END)
			*LINE_END = 0;

		int32_t	LINE_IDS[256];
		int		LINE_ID_COUNT =
			TEXT_TO_WORD_IDS(ENGINE, LINE_START, LINE_IDS, 256, 0);

		if (LINE_ID_COUNT)
			STORE_NEIGHBOR(ENGINE, LINE_IDS, LINE_ID_COUNT, 0);

		if (!LINE_END)
			break ;

		LINE_START = LINE_END + 1;
	}

	free(FILE_TEXT);
	ENGINE->NEIGHBOR_INDEX.VOCABULARY_TAG = VOCABULARY_HASH;
}

static void
	SAVE_ENGINE(ENGINE_STATE *ENGINE, int SAVE_BRAIN)
{
	MEMORY_FILE_SAVE(&ENGINE->FACTS);
	MEMORY_FILE_SAVE(&ENGINE->SELF_FACTS);
	MEMORY_FILE_SAVE(&ENGINE->NOTES);
	MEMORY_FILE_SAVE(&ENGINE->PEOPLE);
	THOUGHT_SAVE(&ENGINE->WORKING_MEMORY, ENGINE->THOUGHT_PATH);

	int	TOPIC_INDEX;

	for (TOPIC_INDEX = 0; TOPIC_INDEX < ENGINE->TOPIC_COUNT; TOPIC_INDEX++)
		if (ENGINE->TOPICS[TOPIC_INDEX].IS_DIRTY)
			SAVE_TOPIC(ENGINE, TOPIC_INDEX);

	MAKE_DIRECTORY_PATH(GLOBAL_DIRECTORY);
	CALCULATOR_SAVE(GLOBAL_DIRECTORY "/formulas.txt");

	if (ENGINE->REFLEXES_ON)
		REFLEX_SAVE(&ENGINE->REFLEXES, GLOBAL_DIRECTORY "/reflexes.txt");

	if (ENGINE->GOAL_DIRTY)
	{
		char	GOAL_PATH[600];
		char	GOAL_TEXT[4096];

		CHAT_FILE_PATH(ENGINE, GOAL_PATH, "goal.txt");

		if (!ENGINE->GOAL_LENGTH)
			remove(GOAL_PATH);
		else
		{
			WORD_IDS_TO_TEXT(
				ENGINE, ENGINE->GOAL_IDS, ENGINE->GOAL_LENGTH, GOAL_TEXT,
				sizeof GOAL_TEXT
			);

			FILE	*STREAM = fopen(GOAL_PATH, "wb");

			if (STREAM)
			{
				fprintf(STREAM, "%s\n", GOAL_TEXT);
				fclose(STREAM);
			}
		}

		ENGINE->GOAL_DIRTY = 0;
	}

	if (
		ENGINE->SENSE_STATE &&
		!ENGINE->SENSE_EVALUATION &&
		strcmp(ENGINE->CHAT_NAME, "selftest")
	)
	{
		char	PROFILE_PATH[600];

		PERSON_PATH(ENGINE->USER_NAME, "", PROFILE_PATH, sizeof PROFILE_PATH);
		MAKE_DIRECTORY_PATH(PROFILE_PATH);
		PERSON_PATH(
			ENGINE->USER_NAME, "profile.txt", PROFILE_PATH, sizeof PROFILE_PATH
		);
		SENSE_SAVE_PROFILE(ENGINE->SENSE_STATE, PROFILE_PATH);
	}

	if (ENGINE->KNOWN_CASINGS_DIRTY)
	{
		FILE	*STREAM = fopen(GLOBAL_DIRECTORY "/case.txt", "wb");

		if (STREAM)
		{
			int	CASE_INDEX;

			for (
				CASE_INDEX = 0;
				CASE_INDEX < ENGINE->KNOWN_CASING_COUNT;
				CASE_INDEX++
			)
				fprintf(STREAM, "%s\n", ENGINE->KNOWN_CASINGS[CASE_INDEX]);

			fclose(STREAM);
		}

		ENGINE->KNOWN_CASINGS_DIRTY = 0;
	}

	if (ENGINE->LOADED_BRAIN.LEXICON->IS_DIRTY)
		LANGUAGE_SAVE(ENGINE->LOADED_BRAIN.LEXICON, LANGUAGE_PATH);

	if (SAVE_BRAIN && ENGINE->BRAIN_DIRTY)
	{
		BRAIN_SAVE(
			&ENGINE->LOADED_BRAIN, GLOBAL_WEB_PATH, GLOBAL_VOCABULARY_PATH, 0
		);
		ENGINE->BRAIN_DIRTY = 0;
		ENGINE->TURNS_SINCE_SAVE = 0;
	}

	if (
		ENGINE->NEIGHBORS_ON &&
		ENGINE->LEARNING_ON &&
		ENGINE->NEIGHBOR_INDEX.MESSAGE_COUNT
	)
	{
		if (
			ENGINE->NEIGHBOR_INDEX.TRAINING_STEP !=
				ENGINE->LOADED_BRAIN.NEURAL_WEB->STEP
		)
			NEAREST_NEIGHBOR_REBUILD(
				&ENGINE->NEIGHBOR_INDEX, ENGINE->LOADED_BRAIN.NEURAL_WEB
			);

		ENGINE->PREFIX_CACHE_VALID = 0;
		NEAREST_NEIGHBOR_SAVE(
			&ENGINE->NEIGHBOR_INDEX, GLOBAL_DIRECTORY "/instant.bin"
		);
	}
}

static int32_t
	STRIP_POSSESSIVE(ENGINE_STATE *ENGINE, int32_t WORD_ID)
{
	const char	*WORD_TEXT = ENGINE->LOADED_BRAIN.LEXICON->STRINGS[WORD_ID];
	size_t		WORD_LENGTH = strlen(WORD_TEXT);

	if (
		WORD_LENGTH < 3 ||
		WORD_LENGTH >= 64 ||
		WORD_TEXT[WORD_LENGTH - 2] != '\'' ||
		WORD_TEXT[WORD_LENGTH - 1] != 's'
	)
		return (WORD_ID);

	char	STEM[64];

	memcpy(STEM, WORD_TEXT, WORD_LENGTH - 2);
	STEM[WORD_LENGTH - 2] = 0;

	int32_t	STEM_ID = LANGUAGE_FIND(ENGINE->LOADED_BRAIN.LEXICON, STEM);

	if (STEM_ID >= 0)
		return (STEM_ID);

	return (WORD_ID);
}

static float
	SCORE_RECORD(
		ENGINE_STATE *ENGINE, const MEMORY_RECORD *RECORD, const int32_t *QUERY,
		int QUERY_COUNT
	)
{
	float		SCORE = 0;
	uint32_t	WORD_INDEX;

	for (WORD_INDEX = 0; WORD_INDEX < RECORD->ID_COUNT; WORD_INDEX++)
	{
		if (!IS_CONTENT_WORD(ENGINE, RECORD->IDS[WORD_INDEX]))
			continue ;

		int32_t	STEM_ID = STRIP_POSSESSIVE(ENGINE, RECORD->IDS[WORD_INDEX]);
		int		QUERY_INDEX;

		for (QUERY_INDEX = 0; QUERY_INDEX < QUERY_COUNT; QUERY_INDEX++)
			if (
				QUERY[QUERY_INDEX] == RECORD->IDS[WORD_INDEX] ||
				STRIP_POSSESSIVE(ENGINE, QUERY[QUERY_INDEX]) == STEM_ID
			)
			{
				SCORE += INVERSE_FREQUENCY(ENGINE, STEM_ID);
				break ;
			}
	}

	return (SCORE);
}

static int
	MEAN_EMBEDDING(
		ENGINE_STATE *ENGINE, const int32_t *WORD_IDS, int ID_COUNT,
		float *OUTPUT
	)
{
	WEB			*NEURAL_WEB = ENGINE->LOADED_BRAIN.NEURAL_WEB;
	LANGUAGE	*LEXICON = ENGINE->LOADED_BRAIN.LEXICON;
	int			DIMENSION = NEURAL_WEB->CONFIGURATION.DIMENSION;
	int			USED_COUNT = 0;

	memset(OUTPUT, 0, DIMENSION * 4);

	int	ID_INDEX;

	for (ID_INDEX = 0; ID_INDEX < ID_COUNT; ID_INDEX++)
	{
		if (
			!IS_CONTENT_WORD(ENGINE, WORD_IDS[ID_INDEX]) ||
			LEXICON->LEXEME_TO_TOKEN[WORD_IDS[ID_INDEX]] < 0
		)
			continue ;

		int32_t	NEURON_ID =
			NEURAL_WEB
				->WORD_NEURONS[LEXICON->LEXEME_TO_TOKEN[WORD_IDS[ID_INDEX]]];
		float	WEIGHT = INVERSE_FREQUENCY(ENGINE, WORD_IDS[ID_INDEX]);
		int		DIMENSION_INDEX;

		for (
			DIMENSION_INDEX = 0;
			DIMENSION_INDEX < DIMENSION;
			DIMENSION_INDEX++
		)
			OUTPUT[DIMENSION_INDEX] +=
				WEIGHT * WEB_WEIGHT(NEURAL_WEB, NEURON_ID, DIMENSION_INDEX);

		USED_COUNT++;
	}

	return (USED_COUNT);
}

static float
	COSINE_SIMILARITY(
		const float *FIRST_VECTOR, const float *SECOND_VECTOR, int DIMENSION
	)
{
	double	DOT_SUM = 0;
	double	FIRST_SQUARED = 0;
	double	SECOND_SQUARED = 0;
	int		INDEX;

	for (INDEX = 0; INDEX < DIMENSION; INDEX++)
	{
		DOT_SUM += FIRST_VECTOR[INDEX] * SECOND_VECTOR[INDEX];
		FIRST_SQUARED += FIRST_VECTOR[INDEX] * FIRST_VECTOR[INDEX];
		SECOND_SQUARED += SECOND_VECTOR[INDEX] * SECOND_VECTOR[INDEX];
	}

	if (FIRST_SQUARED > 0 && SECOND_SQUARED > 0)
		return ((float)(DOT_SUM / sqrt(FIRST_SQUARED * SECOND_SQUARED)));

	return (0);
}

static void
	RECALL_MEMORIES(
		ENGINE_STATE *ENGINE, const int32_t *MESSAGE_IDS, int MESSAGE_LENGTH
	)
{
	THOUGHT	*WORKING_MEMORY = &ENGINE->WORKING_MEMORY;
	int32_t	QUERY[256];
	int		QUERY_COUNT = 0;
	int		INDEX;

	for (INDEX = 0; INDEX < MESSAGE_LENGTH && QUERY_COUNT < 250; INDEX++)
	{
		if (!IS_CONTENT_WORD(ENGINE, MESSAGE_IDS[INDEX]))
			continue ;

		QUERY[QUERY_COUNT++] = MESSAGE_IDS[INDEX];

		const char	*WORD_TEXT =
			ENGINE->LOADED_BRAIN.LEXICON->STRINGS[MESSAGE_IDS[INDEX]];
		size_t		WORD_LENGTH = strlen(WORD_TEXT);

		if (
			WORD_LENGTH > 2 &&
			WORD_LENGTH < 64 &&
			WORD_TEXT[WORD_LENGTH - 2] == '\'' &&
			WORD_TEXT[WORD_LENGTH - 1] == 's'
		)
		{
			char	STEM[64];

			memcpy(STEM, WORD_TEXT, WORD_LENGTH - 2);
			STEM[WORD_LENGTH - 2] = 0;

			int32_t	STEM_ID = LANGUAGE_FIND(ENGINE->LOADED_BRAIN.LEXICON, STEM);

			if (STEM_ID >= 0 && QUERY_COUNT < 250)
				QUERY[QUERY_COUNT++] = STEM_ID;
		}
	}

	for (
		INDEX = 0;
		INDEX < WORKING_MEMORY->TOPIC_COUNT && QUERY_COUNT < 256;
		INDEX++
	)
		QUERY[QUERY_COUNT++] = WORKING_MEMORY->TOPICS[INDEX];

	WORKING_MEMORY->IN_MIND_COUNT = 0;
	WORKING_MEMORY->RECALLED_FILE = WORKING_MEMORY->RECALLED_RECORD = -1;

	float	BEST_SCORES[8];
	int		FILE_INDEX;

	for (FILE_INDEX = 0; FILE_INDEX < MEMORY_FILE_COUNT(ENGINE); FILE_INDEX++)
	{
		int	INDEX;

		for (
			INDEX = 0;
			INDEX < MEMORY_FILE_AT(ENGINE, FILE_INDEX)->COUNT;
			INDEX++
		)
		{
			if (FILE_INDEX >= 3 && ENGINE->TOPIC_READ_ONLY[FILE_INDEX - 3])
				break ;

			MEMORY_RECORD	*RECORD =
				&MEMORY_FILE_AT(ENGINE, FILE_INDEX)->RECORDS[INDEX];
			float			SCORE =
				SCORE_RECORD(ENGINE, RECORD, QUERY, QUERY_COUNT);

			if (FILE_INDEX == 1)
				SCORE *= (float)0.8;

			if (SCORE <= 0)
				continue ;

			int	POSITION = WORKING_MEMORY->IN_MIND_COUNT;

			if (POSITION >= 4)
			{
				if (SCORE <= BEST_SCORES[3])
					continue ;

				POSITION = 3;
			}
			else
				WORKING_MEMORY->IN_MIND_COUNT++;

			while (POSITION > 0 && BEST_SCORES[POSITION - 1] < SCORE)
			{
				BEST_SCORES[POSITION] = BEST_SCORES[POSITION - 1];
				WORKING_MEMORY->IN_MIND_FILES[POSITION] =
					WORKING_MEMORY->IN_MIND_FILES[POSITION - 1];
				WORKING_MEMORY->IN_MIND_RECORDS[POSITION] =
					WORKING_MEMORY->IN_MIND_RECORDS[POSITION - 1];
				POSITION--;
			}

			BEST_SCORES[POSITION] = SCORE;
			WORKING_MEMORY->IN_MIND_FILES[POSITION] = FILE_INDEX;
			WORKING_MEMORY->IN_MIND_RECORDS[POSITION] = INDEX;
		}
	}

	int		DIMENSION =
		ENGINE->LOADED_BRAIN.NEURAL_WEB->CONFIGURATION.DIMENSION;
	float	*QUERY_EMBEDDING = malloc(DIMENSION * 4);
	float	*RECORD_EMBEDDING = malloc(DIMENSION * 4);

	if (MEAN_EMBEDDING(ENGINE, QUERY, QUERY_COUNT, QUERY_EMBEDDING))
	{
		float	BEST_SIMILARITY = (float)0.35;
		int		FILE_INDEX;

		for (
			FILE_INDEX = 0;
			FILE_INDEX < MEMORY_FILE_COUNT(ENGINE);
			FILE_INDEX++
		)
		{
			int	INDEX;

			for (
				INDEX = 0;
				INDEX < MEMORY_FILE_AT(ENGINE, FILE_INDEX)->COUNT;
				INDEX++
			)
			{
				if (FILE_INDEX >= 3 && ENGINE->TOPIC_READ_ONLY[FILE_INDEX - 3])
					break ;

				MEMORY_RECORD	*RECORD =
					&MEMORY_FILE_AT(ENGINE, FILE_INDEX)->RECORDS[INDEX];
				int				ALREADY_IN_MIND = 0;
				int				MIND_INDEX;

				for (
					MIND_INDEX = 0;
					MIND_INDEX < WORKING_MEMORY->IN_MIND_COUNT;
					MIND_INDEX++
				)
					if (
						WORKING_MEMORY->IN_MIND_FILES[MIND_INDEX] ==
							FILE_INDEX &&
						WORKING_MEMORY->IN_MIND_RECORDS[MIND_INDEX] == INDEX
					)
						ALREADY_IN_MIND = 1;

				if (
					ALREADY_IN_MIND ||
					!MEAN_EMBEDDING(
						ENGINE, RECORD->IDS, RECORD->ID_COUNT, RECORD_EMBEDDING
					)
				)
					continue ;

				float	SCORE = COSINE_SIMILARITY(
					QUERY_EMBEDDING, RECORD_EMBEDDING, DIMENSION
				);

				if (SCORE > BEST_SIMILARITY)
				{
					BEST_SIMILARITY = SCORE;
					WORKING_MEMORY->RECALLED_FILE = FILE_INDEX;
					WORKING_MEMORY->RECALLED_RECORD = INDEX;
				}
			}
		}
	}

	free(QUERY_EMBEDDING);
	free(RECORD_EMBEDDING);

	int	MIND_INDEX;

	for (
		MIND_INDEX = 0;
		MIND_INDEX < WORKING_MEMORY->IN_MIND_COUNT;
		MIND_INDEX++
	)
		MEMORY_RECORD_AT(
			ENGINE, WORKING_MEMORY->IN_MIND_FILES[MIND_INDEX],
			WORKING_MEMORY->IN_MIND_RECORDS[MIND_INDEX]
		)
			->HIT_COUNT++;
}

static int
	PUSH_MARKED_LINE(
		ENGINE_STATE *ENGINE, int MARKER, const int32_t *WORD_IDS, int ID_COUNT,
		int32_t *SEQUENCE, int SEQUENCE_LENGTH, int MAXIMUM_LENGTH
	)
{
	if (SEQUENCE_LENGTH + 2 >= MAXIMUM_LENGTH)
		return (SEQUENCE_LENGTH);

	SEQUENCE[SEQUENCE_LENGTH++] = MARKER;

	return (
		SEQUENCE_LENGTH +
			WORD_IDS_TO_TOKENS(
				ENGINE->LOADED_BRAIN.LEXICON, WORD_IDS, ID_COUNT,
				SEQUENCE + SEQUENCE_LENGTH, MAXIMUM_LENGTH - SEQUENCE_LENGTH
			)
	);
}

static int
	BUILD_CONTEXT(
		ENGINE_STATE *ENGINE, int32_t *SEQUENCE, int MAXIMUM_LENGTH,
		int RESERVE, int *MESSAGE_START
	)
{
	THOUGHT	*WORKING_MEMORY = &ENGINE->WORKING_MEMORY;
	int		MEMORY_LIMIT = MAXIMUM_LENGTH / 3;
	int		MEMORY_LENGTH = 0;
	int32_t	*MEMORY_TOKENS = malloc((MEMORY_LIMIT + 8) * 4);
	int		INDEX;

	for (INDEX = 0; INDEX < ENGINE->SELF_FACTS.COUNT && INDEX < 4; INDEX++)
		MEMORY_LENGTH = PUSH_MARKED_LINE(
			ENGINE, TOKEN_MEMORY, ENGINE->SELF_FACTS.RECORDS[INDEX].IDS,
			ENGINE->SELF_FACTS.RECORDS[INDEX].ID_COUNT, MEMORY_TOKENS,
			MEMORY_LENGTH, MEMORY_LIMIT
		);

	if (ENGINE->GOAL_LENGTH)
	{
		int32_t	GOAL_LINE[WORKING_MEMORY_IDS + 8];
		int		GOAL_LINE_LENGTH =
			TEXT_TO_WORD_IDS(ENGINE, "my current goal:", GOAL_LINE, 8, 1);
		int		INDEX;

		for (
			INDEX = 0;
			INDEX < ENGINE->GOAL_LENGTH &&GOAL_LINE_LENGTH <
				WORKING_MEMORY_IDS + 8;
			INDEX++
		)
			GOAL_LINE[GOAL_LINE_LENGTH++] = ENGINE->GOAL_IDS[INDEX];

		MEMORY_LENGTH = PUSH_MARKED_LINE(
			ENGINE, TOKEN_MEMORY, GOAL_LINE, GOAL_LINE_LENGTH, MEMORY_TOKENS,
			MEMORY_LENGTH, MEMORY_LIMIT
		);
	}

	MEMORY_RECORD	*ASSOCIATED = MEMORY_RECORD_AT(
		ENGINE, WORKING_MEMORY->RECALLED_FILE, WORKING_MEMORY->RECALLED_RECORD
	);
	int				PASS;

	for (PASS = 0; PASS < 2; PASS++)
	{
		int	WANT_PERSON;

		if (PASS == 0)
			WANT_PERSON = 0;
		else
			WANT_PERSON = 1;

		int	INDEX;

		for (INDEX = 0; INDEX < WORKING_MEMORY->IN_MIND_COUNT; INDEX++)
		{
			MEMORY_RECORD	*RECORD = MEMORY_RECORD_AT(
				ENGINE, WORKING_MEMORY->IN_MIND_FILES[INDEX],
				WORKING_MEMORY->IN_MIND_RECORDS[INDEX]
			);

			if (RECORD && (RECORD->KIND == MEMORY_KIND_PERSON) == WANT_PERSON)
				MEMORY_LENGTH = PUSH_MARKED_LINE(
					ENGINE, WANT_PERSON ? TOKEN_YOU : TOKEN_MEMORY, RECORD->IDS,
					RECORD->ID_COUNT, MEMORY_TOKENS, MEMORY_LENGTH, MEMORY_LIMIT
				);
		}

		if (
			ASSOCIATED &&
			(ASSOCIATED->KIND == MEMORY_KIND_PERSON) == WANT_PERSON
		)
			MEMORY_LENGTH = PUSH_MARKED_LINE(
				ENGINE, WANT_PERSON ? TOKEN_YOU : TOKEN_MEMORY, ASSOCIATED->IDS,
				ASSOCIATED->ID_COUNT, MEMORY_TOKENS, MEMORY_LENGTH, MEMORY_LIMIT
			);
	}

	int	ADDED = 0;

	for (INDEX = ENGINE->PEOPLE.COUNT - 1; INDEX >= 0 && ADDED < 2; INDEX--)
	{
		MEMORY_RECORD	*RECORD = &ENGINE->PEOPLE.RECORDS[INDEX];
		int				ALREADY_USED = RECORD == ASSOCIATED;
		int				POSITION;

		for (POSITION = 0; POSITION < WORKING_MEMORY->IN_MIND_COUNT; POSITION++)
			if (
				MEMORY_RECORD_AT(
					ENGINE, WORKING_MEMORY->IN_MIND_FILES[POSITION],
					WORKING_MEMORY->IN_MIND_RECORDS[POSITION]
				) == RECORD
			)
				ALREADY_USED = 1;

		if (ALREADY_USED)
			continue ;

		MEMORY_LENGTH = PUSH_MARKED_LINE(
			ENGINE, TOKEN_YOU, RECORD->IDS, RECORD->ID_COUNT, MEMORY_TOKENS,
			MEMORY_LENGTH, MEMORY_LIMIT
		);
		ADDED++;
	}

	int32_t	*MESSAGE_TOKENS[WORKING_MEMORY_MESSAGES];
	int		MESSAGE_LENGTHS[WORKING_MEMORY_MESSAGES];
	int		LAST_USER = -1;

	for (INDEX = 0; INDEX < WORKING_MEMORY->MESSAGE_COUNT; INDEX++)
		if (
			WORKING_MEMORY->MESSAGES[INDEX].SPEAKER == 0 ||
			WORKING_MEMORY->MESSAGES[INDEX].SPEAKER == 4
		)
			LAST_USER = INDEX;

	for (INDEX = 0; INDEX < WORKING_MEMORY->MESSAGE_COUNT; INDEX++)
	{
		MESSAGE_TOKENS[INDEX] = malloc((WORKING_MEMORY_IDS * 8 + 8) * 4);

		if (ENGINE->SKIP_USER_MESSAGE && INDEX == LAST_USER)
		{
			MESSAGE_LENGTHS[INDEX] = 0;
			continue ;
		}

		int	SPEAKER = WORKING_MEMORY->MESSAGES[INDEX].SPEAKER;
		int	MARKER_TOKEN;

		if (SPEAKER == 0 || SPEAKER == 4)
			MARKER_TOKEN = TOKEN_USER_TURN;
		else if (SPEAKER == 1)
			MARKER_TOKEN = TOKEN_CODE_TURN;
		else if (SPEAKER == 2)
			MARKER_TOKEN = ENGINE->TOKEN_DO;
		else
			MARKER_TOKEN = ENGINE->TOKEN_RESULT;

		if (MARKER_TOKEN < 0)
			MESSAGE_LENGTHS[INDEX] = 0;
		else
			MESSAGE_LENGTHS[INDEX] = PUSH_MARKED_LINE(
				ENGINE, MARKER_TOKEN, WORKING_MEMORY->MESSAGES[INDEX].IDS,
				WORKING_MEMORY->MESSAGES[INDEX].ID_COUNT, MESSAGE_TOKENS[INDEX],
				0, WORKING_MEMORY_IDS * 8
			);

		if (
			SPEAKER == 4 &&
			ENGINE->TOKEN_MORE >= 0 &&
			MESSAGE_LENGTHS[INDEX] > 0
		)
			MESSAGE_TOKENS[INDEX][MESSAGE_LENGTHS[INDEX]++] =
				ENGINE->TOKEN_MORE;
	}

	int	FIRST_KEPT = 0;
	int	TOTAL_LENGTH = 0;

	for (INDEX = 0; INDEX < WORKING_MEMORY->MESSAGE_COUNT; INDEX++)
		TOTAL_LENGTH += MESSAGE_LENGTHS[INDEX];

	while (
		FIRST_KEPT < WORKING_MEMORY->MESSAGE_COUNT - 1 &&
		MEMORY_LENGTH + TOTAL_LENGTH + RESERVE > MAXIMUM_LENGTH
	)
		TOTAL_LENGTH -= MESSAGE_LENGTHS[FIRST_KEPT++];

	int	RECALL_START = -1;
	int	RECALL_END = -1;
	int	RECALL_LENGTH = 0;

	if (FIRST_KEPT > 0 && LAST_USER >= FIRST_KEPT)
	{
		MESSAGE	*LAST_MESSAGE = &WORKING_MEMORY->MESSAGES[LAST_USER];
		float	BEST_SCORE = (float)1.5;
		int		GROUP_START;

		for (GROUP_START = 0; GROUP_START < FIRST_KEPT; GROUP_START++)
		{
			if (
				WORKING_MEMORY->MESSAGES[GROUP_START].SPEAKER != 0 &&
				WORKING_MEMORY->MESSAGES[GROUP_START].SPEAKER != 4
			)
				continue ;

			int	GROUP_END = GROUP_START + 1;

			while (
				GROUP_END < FIRST_KEPT &&
				WORKING_MEMORY->MESSAGES[GROUP_END].SPEAKER != 0 &&
				WORKING_MEMORY->MESSAGES[GROUP_END].SPEAKER != 4
			)
				GROUP_END++;

			float	SCORE = 0;
			int		WORD_INDEX;

			for (
				WORD_INDEX = 0;
				WORD_INDEX < LAST_MESSAGE->ID_COUNT;
				WORD_INDEX++
			)
			{
				if (!IS_CONTENT_WORD(ENGINE, LAST_MESSAGE->IDS[WORD_INDEX]))
					continue ;

				int	HIT = 0;
				int	MESSAGE_INDEX;

				for (
					MESSAGE_INDEX = GROUP_START;
					MESSAGE_INDEX < GROUP_END && !HIT;
					MESSAGE_INDEX++
				)
				{
					int	ID_INDEX;

					for (
						ID_INDEX = 0;
						ID_INDEX <
							WORKING_MEMORY->MESSAGES[MESSAGE_INDEX].ID_COUNT;
						ID_INDEX++
					)
						if (
							WORKING_MEMORY->MESSAGES[MESSAGE_INDEX]
									.IDS[ID_INDEX] ==
								LAST_MESSAGE->IDS[WORD_INDEX]
						)
						{
							HIT = 1;
							break ;
						}
				}

				if (HIT)
					SCORE += INVERSE_FREQUENCY(
						ENGINE, LAST_MESSAGE->IDS[WORD_INDEX]
					);
			}

			SCORE += (float)0.01 * GROUP_START;

			if (SCORE > BEST_SCORE)
			{
				BEST_SCORE = SCORE;
				RECALL_START = GROUP_START;
				RECALL_END = GROUP_END;
			}
		}

		if (RECALL_START >= 0)
		{
			int	MESSAGE_INDEX;

			for (
				MESSAGE_INDEX = RECALL_START;
				MESSAGE_INDEX < RECALL_END;
				MESSAGE_INDEX++
			)
				RECALL_LENGTH += MESSAGE_LENGTHS[MESSAGE_INDEX];

			if (RECALL_LENGTH > MAXIMUM_LENGTH / 4)
				RECALL_START = -1;
			else
			{
				while (
					FIRST_KEPT < WORKING_MEMORY->MESSAGE_COUNT - 1 &&
					MEMORY_LENGTH + RECALL_LENGTH + TOTAL_LENGTH + RESERVE >
						MAXIMUM_LENGTH
				)
					TOTAL_LENGTH -= MESSAGE_LENGTHS[FIRST_KEPT++];

				if (RECALL_END > FIRST_KEPT)
					RECALL_START = -1;
			}
		}
	}

	memcpy(SEQUENCE, MEMORY_TOKENS, MEMORY_LENGTH * 4);

	int	POSITION = MEMORY_LENGTH;

	if (RECALL_START >= 0)
	{
		int	MESSAGE_INDEX;

		for (
			MESSAGE_INDEX = RECALL_START;
			MESSAGE_INDEX < RECALL_END;
			MESSAGE_INDEX++
		)
		{
			memcpy(
				SEQUENCE + POSITION, MESSAGE_TOKENS[MESSAGE_INDEX],
				MESSAGE_LENGTHS[MESSAGE_INDEX] * 4
			);
			POSITION += MESSAGE_LENGTHS[MESSAGE_INDEX];
		}
	}

	if (RECALL_START >= 0)
		ENGINE->RECALLED_TURN = RECALL_START;
	else
		ENGINE->RECALLED_TURN = -1;

	if (MESSAGE_START)
		*MESSAGE_START = -1;

	for (INDEX = FIRST_KEPT; INDEX < WORKING_MEMORY->MESSAGE_COUNT; INDEX++)
	{
		int	ROOM = MAXIMUM_LENGTH - RESERVE - POSITION;

		if (ROOM < 2)
			break ;

		if (INDEX == WORKING_MEMORY->MESSAGE_COUNT - 1 && MESSAGE_START)
			*MESSAGE_START = POSITION;

		if (MESSAGE_LENGTHS[INDEX] <= ROOM)
		{
			memcpy(
				SEQUENCE + POSITION, MESSAGE_TOKENS[INDEX],
				MESSAGE_LENGTHS[INDEX] * 4
			);
			POSITION += MESSAGE_LENGTHS[INDEX];
		}
		else
		{
			SEQUENCE[POSITION] = MESSAGE_TOKENS[INDEX][0];
			memcpy(
				SEQUENCE + POSITION + 1,
				MESSAGE_TOKENS[INDEX] + MESSAGE_LENGTHS[INDEX] - (ROOM - 1),
				(ROOM - 1) * 4
			);
			POSITION += ROOM;
		}
	}

	for (INDEX = 0; INDEX < WORKING_MEMORY->MESSAGE_COUNT; INDEX++)
		free(MESSAGE_TOKENS[INDEX]);

	free(MEMORY_TOKENS);

	return (POSITION);
}

static float
	TRAIN_SEQUENCE(
		ENGINE_STATE *ENGINE, const int32_t *SEQUENCE, int SEQUENCE_LENGTH,
		const float *WEIGHTS, float STEP_RATE, int STEP_COUNT, float *SURPRISE,
		int SCORE_FROM
	)
{
	WEB	*NEURAL_WEB = ENGINE->LOADED_BRAIN.NEURAL_WEB;
	int	TIME_LIMIT = NEURAL_WEB->CONFIGURATION.MAXIMUM_LENGTH;

	if (SEQUENCE_LENGTH > TIME_LIMIT + 1)
		SEQUENCE_LENGTH = TIME_LIMIT + 1;

	if (!NEURAL_WEB->TRAINING_ENABLED)
		WEB_SET_TRAINING(NEURAL_WEB, 1);

	float	LAST_LOSS = 0;
	int		STEP;

	for (STEP = 0; STEP < STEP_COUNT; STEP++)
	{
		int32_t	*INPUT_TOKENS =
			(int32_t *)(NEURAL_WEB->ACTIVATIONS + NEURAL_WEB->TOKENS_OFFSET);
		int32_t	*TARGETS =
			(int32_t *)(NEURAL_WEB->ACTIVATIONS + NEURAL_WEB->TARGETS_OFFSET);
		float	*POSITION_WEIGHTS = (float *)(NEURAL_WEB->ACTIVATIONS +
											NEURAL_WEB->LOSS_WEIGHTS_OFFSET);
		double	WEIGHT_SUM = 0;
		int		POSITION;

		for (POSITION = 0; POSITION < SEQUENCE_LENGTH - 1; POSITION++)
		{
			INPUT_TOKENS[POSITION] = SEQUENCE[POSITION];
			TARGETS[POSITION] = SEQUENCE[POSITION + 1];
			POSITION_WEIGHTS[POSITION] = WEIGHTS[POSITION + 1];

			if (POSITION_WEIGHTS[POSITION] == 0)
				TARGETS[POSITION] = -1;

			WEIGHT_SUM += fabsf(POSITION_WEIGHTS[POSITION]);
		}

		if (WEIGHT_SUM <= 0)
			return (0);

		NEURAL_WEB->KERNEL_STATE->SEQUENCE_LENGTH = SEQUENCE_LENGTH - 1;
		NEURAL_WEB->KERNEL_STATE->START_POSITION = 0;
		NEURAL_WEB->KERNEL_STATE->GRADIENT_SCALE = (float)(1.0 / WEIGHT_SUM);
		LEARN_AVOID_WEIGHTS(
			NEURAL_WEB, NEURAL_WEB->KERNEL_STATE, NEURAL_WEB->ACTIVATIONS,
			SEQUENCE_LENGTH - 1
		);
		WEB_RUN(NEURAL_WEB, MODE_TRAIN);
		ENGINE->PREFIX_CACHE_VALID = 0;

		double	LOSS_SUM = 0;
		double	LOSS_COUNT = 0;

		for (
			POSITION = (SCORE_FROM > 0 ? SCORE_FROM - 1 : 0);
			POSITION < SEQUENCE_LENGTH - 1;
			POSITION++
		)
			if (TARGETS[POSITION] >= 0)
			{
				LOSS_SUM +=
					WEB_LOSS_AT(NEURAL_WEB, NEURAL_WEB->ACTIVATIONS, POSITION);
				LOSS_COUNT++;
			}

		if (LOSS_COUNT)
			LAST_LOSS = (float)(LOSS_SUM / LOSS_COUNT);
		else
			LAST_LOSS = 0;

		if (STEP == 0 && SURPRISE)
			*SURPRISE = LAST_LOSS;

		float	SAVED_RATE = NEURAL_WEB->KERNEL_STATE->LEARNING_RATE;

		NEURAL_WEB->KERNEL_STATE->LEARNING_RATE = STEP_RATE;
		LEARN_UPDATE(NEURAL_WEB);
		NEURAL_WEB->KERNEL_STATE->LEARNING_RATE = SAVED_RATE;
	}

	ENGINE->BRAIN_DIRTY = 1;

	return (LAST_LOSS);
}

static void
	UPDATE_TOPIC_WEIGHTS(
		ENGINE_STATE *ENGINE, const int32_t *WORD_IDS, int ID_COUNT
	)
{
	THOUGHT	*WORKING_MEMORY = &ENGINE->WORKING_MEMORY;
	int		INDEX;

	for (INDEX = 0; INDEX < WORKING_MEMORY->TOPIC_COUNT; INDEX++)
		WORKING_MEMORY->TOPIC_WEIGHTS[INDEX] *= (float)0.6;

	for (INDEX = 0; INDEX < ID_COUNT; INDEX++)
	{
		if (!IS_CONTENT_WORD(ENGINE, WORD_IDS[INDEX]))
			continue ;

		float	WEIGHT = INVERSE_FREQUENCY(ENGINE, WORD_IDS[INDEX]);
		int		TOPIC_INDEX;

		for (
			TOPIC_INDEX = 0;
			TOPIC_INDEX < WORKING_MEMORY->TOPIC_COUNT;
			TOPIC_INDEX++
		)
			if (WORKING_MEMORY->TOPICS[TOPIC_INDEX] == WORD_IDS[INDEX])
			{
				WORKING_MEMORY->TOPIC_WEIGHTS[TOPIC_INDEX] += WEIGHT;
				break ;
			}

		if (TOPIC_INDEX < WORKING_MEMORY->TOPIC_COUNT)
			continue ;

		if (WORKING_MEMORY->TOPIC_COUNT < 4)
		{
			WORKING_MEMORY->TOPICS[WORKING_MEMORY->TOPIC_COUNT] =
				WORD_IDS[INDEX];
			WORKING_MEMORY->TOPIC_WEIGHTS[WORKING_MEMORY->TOPIC_COUNT++] =
				WEIGHT;
			continue ;
		}

		int	LOWEST = 0;

		for (TOPIC_INDEX = 1; TOPIC_INDEX < 4; TOPIC_INDEX++)
			if (
				WORKING_MEMORY->TOPIC_WEIGHTS[TOPIC_INDEX] <
					WORKING_MEMORY->TOPIC_WEIGHTS[LOWEST]
			)
				LOWEST = TOPIC_INDEX;

		if (WORKING_MEMORY->TOPIC_WEIGHTS[LOWEST] < WEIGHT)
		{
			WORKING_MEMORY->TOPICS[LOWEST] = WORD_IDS[INDEX];
			WORKING_MEMORY->TOPIC_WEIGHTS[LOWEST] = WEIGHT;
		}
	}

	for (INDEX = 0; INDEX < WORKING_MEMORY->TOPIC_COUNT; INDEX++)
	{
		int	OTHER_INDEX;

		for (
			OTHER_INDEX = INDEX + 1;
			OTHER_INDEX < WORKING_MEMORY->TOPIC_COUNT;
			OTHER_INDEX++
		)
			if (
				WORKING_MEMORY->TOPIC_WEIGHTS[OTHER_INDEX] >
					WORKING_MEMORY->TOPIC_WEIGHTS[INDEX]
			)
			{
				float	SWAP_WEIGHT = WORKING_MEMORY->TOPIC_WEIGHTS[INDEX];

				WORKING_MEMORY->TOPIC_WEIGHTS[INDEX] =
					WORKING_MEMORY->TOPIC_WEIGHTS[OTHER_INDEX];
				WORKING_MEMORY->TOPIC_WEIGHTS[OTHER_INDEX] = SWAP_WEIGHT;

				int32_t	SWAP_TOPIC = WORKING_MEMORY->TOPICS[INDEX];

				WORKING_MEMORY->TOPICS[INDEX] =
					WORKING_MEMORY->TOPICS[OTHER_INDEX];
				WORKING_MEMORY->TOPICS[OTHER_INDEX] = SWAP_TOPIC;
			}
	}

	while (
		WORKING_MEMORY->TOPIC_COUNT > 0 &&
		WORKING_MEMORY->TOPIC_WEIGHTS[WORKING_MEMORY->TOPIC_COUNT - 1] <
			(float)0.5
	)
		WORKING_MEMORY->TOPIC_COUNT--;
}

static void
	REMEMBER_MESSAGE(
		ENGINE_STATE *ENGINE, const int32_t *WORD_IDS, int ID_COUNT,
		float SURPRISE
	)
{
	LANGUAGE	*LEXICON = ENGINE->LOADED_BRAIN.LEXICON;
	THOUGHT		*WORKING_MEMORY = &ENGINE->WORKING_MEMORY;
	int			WORD_COUNT = 0;
	int			IS_QUESTION = 0;
	int			INDEX;

	for (INDEX = 0; INDEX < ID_COUNT; INDEX++)
	{
		if (IS_WORD_ID(LEXICON, WORD_IDS[INDEX]))
			WORD_COUNT++;

		if (!strcmp(LEXICON->STRINGS[WORD_IDS[INDEX]], "?"))
			IS_QUESTION = 1;
	}

	if (IS_QUESTION || WORD_COUNT < 3)
		return ;

	const char	*FIRST_WORD = LEXICON->STRINGS[WORD_IDS[0]];
	int			FIRST_PERSON =
		!strcmp(FIRST_WORD, "i") || !strcmp(FIRST_WORD, "i'm") ||
			!strcmp(FIRST_WORD, "my") || !strcmp(FIRST_WORD, "i've") ||
			!strcmp(FIRST_WORD, "i'll") || !strcmp(FIRST_WORD, "im") ||
			!strcmp(FIRST_WORD, "we");
	int			CONTENT_END = ID_COUNT;

	while (CONTENT_END > 0 && !IS_WORD_ID(LEXICON, WORD_IDS[CONTENT_END - 1]))
		CONTENT_END--;

	if (FIRST_PERSON)
	{
		if (FIND_MEMORY_RECORD(&ENGINE->PEOPLE, WORD_IDS, ID_COUNT) >= 0)
			return ;

		MEMORY_FILE_ADD(
			&ENGINE->PEOPLE, MEMORY_KIND_PERSON, WORD_IDS, ID_COUNT,
			WORKING_MEMORY->TURN
		);
		COLLECT_NAMES_FROM(ENGINE, &ENGINE->PEOPLE);
	}
	else if (WORD_COUNT >= 4 && SURPRISE > WORKING_MEMORY->SURPRISE_AVERAGE)
		MEMORY_FILE_ADD(
			&ENGINE->NOTES, MEMORY_KIND_NOTE, WORD_IDS, ID_COUNT,
			WORKING_MEMORY->TURN
		);

	(void)CONTENT_END;
}

static int
	IS_PUNCTUATION_TOKEN(ENGINE_STATE *ENGINE, int32_t TOKEN)
{
	LANGUAGE	*LEXICON = ENGINE->LOADED_BRAIN.LEXICON;

	if (TOKEN < TOKEN_FIRST_WORD || TOKEN >= LEXICON->TOKEN_COUNT)
		return (0);

	int32_t	LEXEME = LEXICON->TOKEN_TO_LEXEME[TOKEN];

	return (
		!IS_SPECIAL_WORD(LEXICON, LEXEME) &&
		!isalnum((uint8_t)LEXICON->STRINGS[LEXEME][0])
	);
}

static int
	IS_VALID_TOKEN(
		ENGINE_STATE *ENGINE, int32_t PREVIOUS_TOKEN, int32_t TOKEN,
		int SPELLED_COUNT, int REPLY_LENGTH, int GENERATE_MODE
	)
{
	LANGUAGE	*LEXICON = ENGINE->LOADED_BRAIN.LEXICON;

	if (
		TOKEN == TOKEN_TEXT ||
		TOKEN == TOKEN_MEMORY ||
		TOKEN == TOKEN_YOU ||
		TOKEN == TOKEN_CODE_TURN
	)
		return (0);

	if (TOKEN == TOKEN_USER_TURN)
		return (GENERATE_MODE == 0 && REPLY_LENGTH > 0);

	if (TOKEN == ENGINE->TOKEN_DO)
		return (0);

	if (TOKEN == ENGINE->TOKEN_RESULT)
		return (GENERATE_MODE == 1 && REPLY_LENGTH > 0);

	int	IS_CONTINUATION = TOKEN >= TOKEN_FIRST_CHARACTER + CHARACTER_COUNT &&
		TOKEN < TOKEN_FIRST_WORD;
	int	IS_SPELL_START = TOKEN >= TOKEN_FIRST_CHARACTER &&
		TOKEN < TOKEN_FIRST_CHARACTER + CHARACTER_COUNT;

	if (IS_CONTINUATION)
		return (
			PREVIOUS_TOKEN >= TOKEN_FIRST_CHARACTER &&
			PREVIOUS_TOKEN < TOKEN_FIRST_WORD &&
			SPELLED_COUNT < 16
		);

	if (IS_SPELL_START)
		return (1);

	if (TOKEN >= LEXICON->TOKEN_COUNT)
		return (0);

	if (IS_SPECIAL_WORD(LEXICON, LEXICON->TOKEN_TO_LEXEME[TOKEN]))
		return (0);

	if (GENERATE_MODE == 0 && REPLY_LENGTH == 0)
	{
		const char	*WORD_TEXT =
			LEXICON->STRINGS[LEXICON->TOKEN_TO_LEXEME[TOKEN]];

		if (
			!isalnum((uint8_t)WORD_TEXT[0]) &&
			strcmp(WORD_TEXT, "\"") &&
			strcmp(WORD_TEXT, "(") &&
			strcmp(WORD_TEXT, "...")
		)
			return (0);
	}

	return (1);
}

static const float	*SORT_PROBABILITIES;

static int
	BY_PROBABILITY(const void *FIRST_ITEM, const void *SECOND_ITEM)
{
	float	FIRST_PROBABILITY =
		SORT_PROBABILITIES[*(const int32_t *)FIRST_ITEM];
	float	SECOND_PROBABILITY =
		SORT_PROBABILITIES[*(const int32_t *)SECOND_ITEM];

	if (FIRST_PROBABILITY > SECOND_PROBABILITY)
		return (-1);

	if (FIRST_PROBABILITY < SECOND_PROBABILITY)
		return (1);

	return (0);
}

static void
	RUN_PREFIX(
		ENGINE_STATE *ENGINE, const int32_t *SEQUENCE, int SEQUENCE_LENGTH
	)
{
	WEB		*NEURAL_WEB = ENGINE->LOADED_BRAIN.NEURAL_WEB;
	int32_t	*TOKEN_BUFFER =
		(int32_t *)(NEURAL_WEB->ACTIVATIONS + NEURAL_WEB->TOKENS_OFFSET);
	int		PREFIX_LENGTH = 0;
	int		CACHED_LIMIT;

	if (ENGINE->PREFIX_CACHE_VALID < SEQUENCE_LENGTH)
		CACHED_LIMIT = ENGINE->PREFIX_CACHE_VALID;
	else
		CACHED_LIMIT = SEQUENCE_LENGTH;

	while (
		PREFIX_LENGTH < CACHED_LIMIT &&
		TOKEN_BUFFER[PREFIX_LENGTH] == SEQUENCE[PREFIX_LENGTH]
	)
		PREFIX_LENGTH++;

	if (PREFIX_LENGTH >= SEQUENCE_LENGTH)
		PREFIX_LENGTH = SEQUENCE_LENGTH - 1;

	memcpy(
		TOKEN_BUFFER + PREFIX_LENGTH, SEQUENCE + PREFIX_LENGTH,
		(SEQUENCE_LENGTH - PREFIX_LENGTH) * 4
	);
	NEURAL_WEB->KERNEL_STATE->START_POSITION = PREFIX_LENGTH;
	NEURAL_WEB->KERNEL_STATE->SEQUENCE_LENGTH = SEQUENCE_LENGTH;
	WEB_RUN(NEURAL_WEB, MODE_INFER);
	ENGINE->PREFIX_CACHE_VALID = SEQUENCE_LENGTH;
}

typedef struct
{
	uint8_t	*IN_CONTEXT;
	char	(*SPELLED_WORDS)[33];
	int		SPELLED_WORD_COUNT;
	char	CURRENT_WORD[33];
	int		CURRENT_WORD_LENGTH;
	uint8_t	*IN_USER_TURN;
	char	(*USER_SPELLED_WORDS)[33];
	int		USER_SPELLED_COUNT;
	int		PICKED_COUNT;
	int32_t	TOKEN_REMEMBER;
	int32_t	TOKEN_CALC;
	int32_t	TOKEN_CALCULATE;
	int32_t	MATH_SPANS[4][40];
	int		MATH_SPAN_COUNT;
	int		MATH_SPAN_LENGTHS[4];
} COPY_CONSTRAINT;

static const char	SPELLING_CHARACTERS[38] =
	"abcdefghijklmnopqrstuvwxyz0123456789'";

static int
	IS_ALL_DIGITS(const char *STRING)
{
	if (!*STRING)
		return (0);

	for (; *STRING; STRING++)
		if (!isdigit((uint8_t)*STRING))
			return (0);

	return (1);
}

static int
	MATH_TOKEN_KIND(
		ENGINE_STATE *ENGINE, const int32_t *SEQUENCE, int POSITION,
		int SEQUENCE_LENGTH, int DEPTH
	)
{
	static const char	*OPERATORS[13] = {
		"+", "-", "*", "/", "^", "%", "plus", "minus", "times", "divided", "by",
		"over", "multiplied"
	};
	static const char	*FUNCTIONS[12] = {
		"sqrt", "round", "abs", "min", "max", "floor", "ceil", "pi", "ln",
		"log", "exp", "pow"
	};
	static const char	*NUMBER_WORDS[14] = {
		"zero", "one", "two", "three", "four", "five", "six", "seven", "eight",
		"nine", "ten", "eleven", "twelve", "hundred"
	};
	int32_t				TOKEN = SEQUENCE[POSITION];

	if (
		TOKEN >= TOKEN_FIRST_CHARACTER &&
		TOKEN < TOKEN_FIRST_CHARACTER + CHARACTER_COUNT
	)
	{
		if (
			!isdigit(
				(uint8_t)SPELLING_CHARACTERS[TOKEN - TOKEN_FIRST_CHARACTER]
			)
		)
			return (0);

		int	SPELL_INDEX;

		for (
			SPELL_INDEX = POSITION + 1;
			SPELL_INDEX < SEQUENCE_LENGTH &&SEQUENCE[SPELL_INDEX] >=
				TOKEN_FIRST_CHARACTER +
					CHARACTER_COUNT &&SEQUENCE[SPELL_INDEX] <
				TOKEN_FIRST_WORD;
			SPELL_INDEX++
		)
			if (
				!isdigit(
					(uint8_t) SPELLING_CHARACTERS
						[SEQUENCE[SPELL_INDEX] - TOKEN_FIRST_CHARACTER -
							CHARACTER_COUNT]
				)
			)
				return (0);

		return (1);
	}

	if (
		TOKEN < TOKEN_FIRST_WORD ||
		TOKEN >= ENGINE->LOADED_BRAIN.NEURAL_WEB->WORD_COUNT
	)
		return (0);

	const char	*WORD_TEXT =
		ENGINE->LOADED_BRAIN.LEXICON
			->STRINGS[ENGINE->LOADED_BRAIN.LEXICON->TOKEN_TO_LEXEME[TOKEN]];

	if (
		IS_ALL_DIGITS(WORD_TEXT) ||
		(
			isdigit((uint8_t)WORD_TEXT[0]) &&
			strchr(WORD_TEXT, '.') &&
			isdigit((uint8_t)WORD_TEXT[strlen(WORD_TEXT) - 1])
		)
	)
		return (1);

	size_t	LIST_INDEX;

	for (
		LIST_INDEX = 0;
		LIST_INDEX < sizeof NUMBER_WORDS / sizeof NUMBER_WORDS[0];
		LIST_INDEX++
	)
		if (!strcmp(WORD_TEXT, NUMBER_WORDS[LIST_INDEX]))
			return (1);

	for (
		LIST_INDEX = 0;
		LIST_INDEX < sizeof OPERATORS / sizeof OPERATORS[0];
		LIST_INDEX++
	)
		if (!strcmp(WORD_TEXT, OPERATORS[LIST_INDEX]))
			return (2);

	for (
		LIST_INDEX = 0;
		LIST_INDEX < sizeof FUNCTIONS / sizeof FUNCTIONS[0];
		LIST_INDEX++
	)
		if (!strcmp(WORD_TEXT, FUNCTIONS[LIST_INDEX]))
			return (3);

	if (!strcmp(WORD_TEXT, "("))
		return (4);

	if (!strcmp(WORD_TEXT, ")"))
	{
		if (DEPTH > 0)
			return (5);

		return (0);
	}

	if (!strcmp(WORD_TEXT, ","))
	{
		if (DEPTH > 0)
			return (6);

		return (0);
	}

	if (
		!strcmp(WORD_TEXT, "x") &&
		POSITION > 0 &&
		POSITION + 1 < SEQUENCE_LENGTH
	)
		return (2);

	if (
		!strcmp(WORD_TEXT, "of") &&
		POSITION > 0 &&
		SEQUENCE[POSITION - 1] >= TOKEN_FIRST_WORD &&
		SEQUENCE[POSITION - 1] < ENGINE->LOADED_BRAIN.NEURAL_WEB->WORD_COUNT &&
		(
			!strcmp(
				ENGINE->LOADED_BRAIN.LEXICON
					->STRINGS[ENGINE->LOADED_BRAIN.LEXICON
						->TOKEN_TO_LEXEME[SEQUENCE[POSITION - 1]]],
				"%"
			) ||
			!strcmp(
				ENGINE->LOADED_BRAIN.LEXICON
					->STRINGS[ENGINE->LOADED_BRAIN.LEXICON
						->TOKEN_TO_LEXEME[SEQUENCE[POSITION - 1]]],
				"percent"
			)
		)
	)
		return (2);

	if (!strcmp(WORD_TEXT, "percent"))
		return (2);

	if (
		!strcmp(WORD_TEXT, ".") &&
		POSITION > 0 &&
		POSITION + 1 < SEQUENCE_LENGTH &&
		SEQUENCE[POSITION + 1] >= TOKEN_FIRST_WORD &&
		SEQUENCE[POSITION + 1] < ENGINE->LOADED_BRAIN.NEURAL_WEB->WORD_COUNT &&
		IS_ALL_DIGITS(
			ENGINE->LOADED_BRAIN.LEXICON
				->STRINGS[ENGINE->LOADED_BRAIN.LEXICON
					->TOKEN_TO_LEXEME[SEQUENCE[POSITION + 1]]]
		) &&
		SEQUENCE[POSITION - 1] >= TOKEN_FIRST_WORD &&
		SEQUENCE[POSITION - 1] < ENGINE->LOADED_BRAIN.NEURAL_WEB->WORD_COUNT &&
		IS_ALL_DIGITS(
			ENGINE->LOADED_BRAIN.LEXICON
				->STRINGS[ENGINE->LOADED_BRAIN.LEXICON
					->TOKEN_TO_LEXEME[SEQUENCE[POSITION - 1]]]
		)
	)
		return (7);

	if (
		!strcmp(WORD_TEXT, ".") &&
		POSITION > 0 &&
		POSITION + 1 < SEQUENCE_LENGTH &&
		SEQUENCE[POSITION + 1] >= TOKEN_FIRST_CHARACTER &&
		SEQUENCE[POSITION + 1] < TOKEN_FIRST_CHARACTER + CHARACTER_COUNT &&
		isdigit(
			(uint8_t) SPELLING_CHARACTERS
				[SEQUENCE[POSITION + 1] - TOKEN_FIRST_CHARACTER]
		)
	)
		return (7);

	return (0);
}

static void
	FIND_MATH_SPANS(
		ENGINE_STATE *ENGINE, COPY_CONSTRAINT *COPY_STATE,
		const int32_t *SEQUENCE, int SPAN_FROM, int SPAN_TO
	)
{
	COPY_STATE->MATH_SPAN_COUNT = 0;

	int	START = SPAN_FROM;

	while (START < SPAN_TO && COPY_STATE->MATH_SPAN_COUNT < 4)
	{
		int		DEPTH = 0;
		int		NUMBER_COUNT = 0;
		int		OPERATOR_COUNT = 0;
		int		SPAN_LENGTH = 0;
		int		POSITION = START;
		int32_t	*SPAN = COPY_STATE->MATH_SPANS[COPY_STATE->MATH_SPAN_COUNT];

		while (POSITION < SPAN_TO)
		{
			int	KIND =
				MATH_TOKEN_KIND(ENGINE, SEQUENCE, POSITION, SPAN_TO, DEPTH);

			if (!KIND)
				break ;

			if (KIND == 4)
				DEPTH++;

			if (KIND == 5)
				DEPTH--;

			if (KIND == 1)
				NUMBER_COUNT++;

			if (KIND == 2 || KIND == 3)
				OPERATOR_COUNT++;

			int	PIECE_END = POSITION + 1;

			if (
				SEQUENCE[POSITION] >= TOKEN_FIRST_CHARACTER &&
				SEQUENCE[POSITION] < TOKEN_FIRST_CHARACTER + CHARACTER_COUNT
			)
				while (
					PIECE_END < SPAN_TO &&
					SEQUENCE[PIECE_END] >=
						TOKEN_FIRST_CHARACTER + CHARACTER_COUNT &&
					SEQUENCE[PIECE_END] < TOKEN_FIRST_WORD
				)
					PIECE_END++;

			while (POSITION < PIECE_END && SPAN_LENGTH < 40)
				SPAN[SPAN_LENGTH++] = SEQUENCE[POSITION++];

			if (SPAN_LENGTH >= 40)
				break ;
		}

		while (SPAN_LENGTH > 0 && DEPTH == 0)
		{
			int	TAIL_INDEX = SPAN_LENGTH - 1;

			while (
				TAIL_INDEX > 0 &&
				SPAN[TAIL_INDEX] >= TOKEN_FIRST_CHARACTER + CHARACTER_COUNT &&
				SPAN[TAIL_INDEX] < TOKEN_FIRST_WORD
			)
				TAIL_INDEX--;

			if (MATH_TOKEN_KIND(ENGINE, SPAN, TAIL_INDEX, SPAN_LENGTH, 1) != 2)
				break ;

			SPAN_LENGTH = TAIL_INDEX;
		}

		NUMBER_COUNT = OPERATOR_COUNT = 0;

		int	TAIL_INDEX;

		for (TAIL_INDEX = 0; TAIL_INDEX < SPAN_LENGTH; TAIL_INDEX++)
		{
			int	KIND =
				MATH_TOKEN_KIND(ENGINE, SPAN, TAIL_INDEX, SPAN_LENGTH, 1);

			if (KIND == 1)
				NUMBER_COUNT++;

			if (KIND == 2 || KIND == 3)
				OPERATOR_COUNT++;
		}

		if (
			DEPTH == 0 &&
			NUMBER_COUNT >= 1 &&
			OPERATOR_COUNT > 0 &&
			(
				NUMBER_COUNT >= 2 ||
				MATH_TOKEN_KIND(ENGINE, SPAN, 0, SPAN_LENGTH, 0) == 3
			) &&
			POSITION - START < 40
		)
			COPY_STATE->MATH_SPAN_LENGTHS[COPY_STATE->MATH_SPAN_COUNT++] =
				SPAN_LENGTH;

		if (POSITION > START)
			START = POSITION;
		else
			START = START + 1;
	}
}

static int
	MATH_SPAN_ALLOWS(
		COPY_CONSTRAINT *COPY_STATE, const int32_t *ARGUMENT,
		int ARGUMENT_LENGTH, int32_t NEXT_TOKEN, int32_t RESULT_TOKEN
	)
{
	int	ANY_MATCH = 0;
	int	SPAN_INDEX;

	for (SPAN_INDEX = 0; SPAN_INDEX < COPY_STATE->MATH_SPAN_COUNT; SPAN_INDEX++)
	{
		if (
			ARGUMENT_LENGTH > COPY_STATE->MATH_SPAN_LENGTHS[SPAN_INDEX] ||
			memcmp(
				COPY_STATE->MATH_SPANS[SPAN_INDEX], ARGUMENT,
				ARGUMENT_LENGTH * 4
			)
		)
			continue ;

		ANY_MATCH = 1;

		if (
			NEXT_TOKEN == RESULT_TOKEN
				? ARGUMENT_LENGTH == COPY_STATE->MATH_SPAN_LENGTHS[SPAN_INDEX]
				: (ARGUMENT_LENGTH <
					COPY_STATE->MATH_SPAN_LENGTHS[SPAN_INDEX] &&
					COPY_STATE->MATH_SPANS[SPAN_INDEX][ARGUMENT_LENGTH] ==
					NEXT_TOKEN)
		)
			return (1);
	}

	return (!ANY_MATCH);
}

static void
	INITIALIZE_COPY(
		ENGINE_STATE *ENGINE, COPY_CONSTRAINT *COPY_STATE,
		const int32_t *SEQUENCE, int SEQUENCE_LENGTH
	)
{
	LANGUAGE			*LEXICON = ENGINE->LOADED_BRAIN.LEXICON;
	static const char	*COMMAND_WORDS[65] = {
		"lookup", "remember", "recall", "forget", "calc", "formula", "formulas",
		"memories", "time", "date", "files", "read", "write", "append", "mkdir",
		"move", "rename", "delete", "goal", "export", "topics", "topic", "done",
		"to", "into", ".", "txt", "/", "(", ")", ",", "=", "+", "-", "*", "^",
		"%", "pi", "sqrt", "round", "abs", "min", "max", "floor", "ceil", ";",
		":", "my", "is", "name", "the", "a", "an", "and", "count", "words",
		"letters", "characters", "in", "range", "reverse", "random", "step",
		"rule", "=>"
	};

	COPY_STATE->IN_CONTEXT =
		calloc(ENGINE->LOADED_BRAIN.NEURAL_WEB->WORD_COUNT, 1);
	COPY_STATE->SPELLED_WORDS = malloc(512 * sizeof *COPY_STATE->SPELLED_WORDS);
	COPY_STATE->SPELLED_WORD_COUNT = 0;
	COPY_STATE->CURRENT_WORD_LENGTH = 0;
	COPY_STATE->CURRENT_WORD[0] = 0;
	COPY_STATE->IN_USER_TURN =
		calloc(ENGINE->LOADED_BRAIN.NEURAL_WEB->WORD_COUNT, 1);
	COPY_STATE->USER_SPELLED_WORDS =
		malloc(128 * sizeof *COPY_STATE->USER_SPELLED_WORDS);
	COPY_STATE->USER_SPELLED_COUNT = 0;
	COPY_STATE->PICKED_COUNT = 0;
	COPY_STATE->TOKEN_REMEMBER = LANGUAGE_TOKEN(LEXICON, "remember");
	COPY_STATE->TOKEN_CALC = LANGUAGE_TOKEN(LEXICON, "calc");
	COPY_STATE->TOKEN_CALCULATE = LANGUAGE_TOKEN(LEXICON, "calculate");
	COPY_STATE->MATH_SPAN_COUNT = 0;

	size_t	INDEX;

	for (
		INDEX = 0;
		INDEX < sizeof COMMAND_WORDS / sizeof COMMAND_WORDS[0];
		INDEX++
	)
	{
		int32_t	TOKEN = LANGUAGE_TOKEN(LEXICON, COMMAND_WORDS[INDEX]);

		if (TOKEN >= 0 && TOKEN < ENGINE->LOADED_BRAIN.NEURAL_WEB->WORD_COUNT)
			COPY_STATE->IN_CONTEXT[TOKEN] = COPY_STATE->IN_USER_TURN[TOKEN] = 1;
	}

	int	USER_START = -1;

	{
		int	INDEX;

		for (INDEX = 0; INDEX < SEQUENCE_LENGTH; INDEX++)
			if (SEQUENCE[INDEX] == TOKEN_USER_TURN)
				USER_START = INDEX;
	}

	if (USER_START >= 0)
	{
		int	USER_END = USER_START + 1;

		while (
			USER_END < SEQUENCE_LENGTH &&
			SEQUENCE[USER_END] != TOKEN_CODE_TURN &&
			SEQUENCE[USER_END] != ENGINE->TOKEN_DO &&
			SEQUENCE[USER_END] != ENGINE->TOKEN_RESULT
		)
			USER_END++;

		FIND_MATH_SPANS(ENGINE, COPY_STATE, SEQUENCE, USER_START + 1, USER_END);
	}

	if (USER_START >= 0)
	{
		int	INDEX;

		for (
			INDEX = USER_START + 1;
			INDEX < SEQUENCE_LENGTH &&SEQUENCE[INDEX] !=
				TOKEN_CODE_TURN &&SEQUENCE[INDEX] !=
				ENGINE->TOKEN_DO &&SEQUENCE[INDEX] != ENGINE->TOKEN_RESULT;
			INDEX++
		)
		{
			int32_t	TOKEN = SEQUENCE[INDEX];

			if (
				TOKEN >= TOKEN_FIRST_WORD &&
				TOKEN < ENGINE->LOADED_BRAIN.NEURAL_WEB->WORD_COUNT
			)
				COPY_STATE->IN_USER_TURN[TOKEN] = 1;

			if (
				TOKEN >= TOKEN_FIRST_CHARACTER &&
				TOKEN < TOKEN_FIRST_CHARACTER + CHARACTER_COUNT &&
				COPY_STATE->USER_SPELLED_COUNT < 128
			)
			{
				int	LETTER_INDEX = 0;

				COPY_STATE->USER_SPELLED_WORDS[COPY_STATE->USER_SPELLED_COUNT]
				[LETTER_INDEX++] =
					SPELLING_CHARACTERS[TOKEN - TOKEN_FIRST_CHARACTER];

				while (
					INDEX + 1 < SEQUENCE_LENGTH &&
					SEQUENCE[INDEX + 1] >=
						TOKEN_FIRST_CHARACTER + CHARACTER_COUNT &&
					SEQUENCE[INDEX + 1] < TOKEN_FIRST_WORD &&
					LETTER_INDEX < 32
				)
					COPY_STATE
						->USER_SPELLED_WORDS[COPY_STATE->USER_SPELLED_COUNT]
											[LETTER_INDEX++] =
						SPELLING_CHARACTERS
							[SEQUENCE[++INDEX] - TOKEN_FIRST_CHARACTER -
								CHARACTER_COUNT];

				COPY_STATE->USER_SPELLED_WORDS[COPY_STATE->USER_SPELLED_COUNT]
				[LETTER_INDEX] = 0;
				COPY_STATE->USER_SPELLED_COUNT++;
			}
		}
	}

	{
		int	INDEX;

		for (INDEX = 0; INDEX < SEQUENCE_LENGTH; INDEX++)
		{
			int32_t	TOKEN = SEQUENCE[INDEX];

			if (
				TOKEN >= TOKEN_FIRST_WORD &&
				TOKEN < ENGINE->LOADED_BRAIN.NEURAL_WEB->WORD_COUNT
			)
				COPY_STATE->IN_CONTEXT[TOKEN] = 1;

			if (
				TOKEN >= TOKEN_FIRST_CHARACTER &&
				TOKEN < TOKEN_FIRST_CHARACTER + CHARACTER_COUNT &&
				COPY_STATE->SPELLED_WORD_COUNT < 512
			)
			{
				int	LETTER_INDEX = 0;

				COPY_STATE->SPELLED_WORDS[COPY_STATE->SPELLED_WORD_COUNT]
				[LETTER_INDEX++] =
					SPELLING_CHARACTERS[TOKEN - TOKEN_FIRST_CHARACTER];

				while (
					INDEX + 1 < SEQUENCE_LENGTH &&
					SEQUENCE[INDEX + 1] >=
						TOKEN_FIRST_CHARACTER + CHARACTER_COUNT &&
					SEQUENCE[INDEX + 1] < TOKEN_FIRST_WORD &&
					LETTER_INDEX < 32
				)
					COPY_STATE->SPELLED_WORDS[COPY_STATE->SPELLED_WORD_COUNT]
				[LETTER_INDEX++] =
						SPELLING_CHARACTERS
							[SEQUENCE[++INDEX] - TOKEN_FIRST_CHARACTER -
								CHARACTER_COUNT];

				COPY_STATE->SPELLED_WORDS[COPY_STATE->SPELLED_WORD_COUNT]
				[LETTER_INDEX] = 0;
				COPY_STATE->SPELLED_WORD_COUNT++;
			}
		}
	}
}

static int
	COPY_HAS_PREFIX(
		COPY_CONSTRAINT *COPY_STATE, const char *PREFIX, int WHOLE_WORD
	)
{
	size_t	PREFIX_LENGTH = strlen(PREFIX);
	int		WORD_INDEX;

	for (
		WORD_INDEX = 0;
		WORD_INDEX < COPY_STATE->SPELLED_WORD_COUNT;
		WORD_INDEX++
	)
		if (
			!strncmp(
				COPY_STATE->SPELLED_WORDS[WORD_INDEX], PREFIX, PREFIX_LENGTH
			) &&
			(
				!WHOLE_WORD ||
				COPY_STATE->SPELLED_WORDS[WORD_INDEX][PREFIX_LENGTH] == 0
			)
		)
			return (1);

	return (0);
}

static int
	COPY_ALLOWS_TOKEN(
		ENGINE_STATE *ENGINE, COPY_CONSTRAINT *COPY_STATE, int32_t TOKEN
	)
{
	int	IS_CONTINUATION = TOKEN >= TOKEN_FIRST_CHARACTER + CHARACTER_COUNT &&
		TOKEN < TOKEN_FIRST_WORD;
	int	IS_SPELL_START = TOKEN >= TOKEN_FIRST_CHARACTER &&
		TOKEN < TOKEN_FIRST_CHARACTER + CHARACTER_COUNT;
	int	INCOMPLETE = COPY_STATE->CURRENT_WORD_LENGTH > 0 &&
		!IS_ALL_DIGITS(COPY_STATE->CURRENT_WORD) &&
		!COPY_HAS_PREFIX(COPY_STATE, COPY_STATE->CURRENT_WORD, 1);

	if (IS_CONTINUATION)
	{
		if (
			!COPY_STATE->CURRENT_WORD_LENGTH ||
			COPY_STATE->CURRENT_WORD_LENGTH >= 32
		)
			return (0);

		char	SPELLED_PREFIX[34];

		memcpy(
			SPELLED_PREFIX, COPY_STATE->CURRENT_WORD,
			COPY_STATE->CURRENT_WORD_LENGTH
		);
		SPELLED_PREFIX[COPY_STATE->CURRENT_WORD_LENGTH] = SPELLING_CHARACTERS
			[TOKEN - TOKEN_FIRST_CHARACTER - CHARACTER_COUNT];
		SPELLED_PREFIX[COPY_STATE->CURRENT_WORD_LENGTH + 1] = 0;
		return (
			(
				IS_ALL_DIGITS(COPY_STATE->CURRENT_WORD) &&
				isdigit(
					(uint8_t)SPELLED_PREFIX[COPY_STATE->CURRENT_WORD_LENGTH]
				)
			) ||
			COPY_HAS_PREFIX(COPY_STATE, SPELLED_PREFIX, 0)
		);
	}

	if (INCOMPLETE)
		return (0);

	if (IS_SPELL_START)
	{
		char	SPELLED_PREFIX[2] = {
			SPELLING_CHARACTERS[TOKEN - TOKEN_FIRST_CHARACTER], 0
		};

		return (
			isdigit((uint8_t)SPELLED_PREFIX[0]) ||
			COPY_HAS_PREFIX(COPY_STATE, SPELLED_PREFIX, 0)
		);
	}

	if (TOKEN == ENGINE->TOKEN_RESULT)
		return (1);

	if (
		TOKEN >= TOKEN_FIRST_WORD &&
		TOKEN < ENGINE->LOADED_BRAIN.NEURAL_WEB->WORD_COUNT
	)
		return (
			COPY_STATE->IN_CONTEXT[TOKEN] ||
			IS_ALL_DIGITS(
				ENGINE->LOADED_BRAIN.LEXICON->STRINGS
					[ENGINE->LOADED_BRAIN.LEXICON->TOKEN_TO_LEXEME[TOKEN]]
			)
		);

	return (1);
}

static void
	COPY_PUSH_TOKEN(COPY_CONSTRAINT *COPY_STATE, int32_t TOKEN)
{
	if (
		COPY_STATE->PICKED_COUNT++ == 0 &&
		TOKEN == COPY_STATE->TOKEN_REMEMBER &&
		COPY_STATE->TOKEN_REMEMBER >= 0
	)
	{
		uint8_t	*SWAP_MASK = COPY_STATE->IN_CONTEXT;

		COPY_STATE->IN_CONTEXT = COPY_STATE->IN_USER_TURN;
		COPY_STATE->IN_USER_TURN = SWAP_MASK;

		char	(*SWAP_WORDS)[33] = COPY_STATE->SPELLED_WORDS;

		COPY_STATE->SPELLED_WORDS = COPY_STATE->USER_SPELLED_WORDS;
		COPY_STATE->USER_SPELLED_WORDS = SWAP_WORDS;

		int	SWAP_COUNT = COPY_STATE->SPELLED_WORD_COUNT;

		COPY_STATE->SPELLED_WORD_COUNT = COPY_STATE->USER_SPELLED_COUNT;
		COPY_STATE->USER_SPELLED_COUNT = SWAP_COUNT;
	}

	if (
		TOKEN >= TOKEN_FIRST_CHARACTER &&
		TOKEN < TOKEN_FIRST_CHARACTER + CHARACTER_COUNT
	)
	{
		COPY_STATE->CURRENT_WORD[0] =
			SPELLING_CHARACTERS[TOKEN - TOKEN_FIRST_CHARACTER];
		COPY_STATE->CURRENT_WORD_LENGTH = 1;
		COPY_STATE->CURRENT_WORD[1] = 0;
	}
	else if (
		TOKEN >= TOKEN_FIRST_CHARACTER + CHARACTER_COUNT &&
		TOKEN < TOKEN_FIRST_WORD
	)
	{
		if (COPY_STATE->CURRENT_WORD_LENGTH < 32)
		{
			COPY_STATE->CURRENT_WORD[COPY_STATE->CURRENT_WORD_LENGTH++] =
				SPELLING_CHARACTERS
					[TOKEN - TOKEN_FIRST_CHARACTER - CHARACTER_COUNT];
			COPY_STATE->CURRENT_WORD[COPY_STATE->CURRENT_WORD_LENGTH] = 0;
		}
	}
	else
	{
		COPY_STATE->CURRENT_WORD_LENGTH = 0;
		COPY_STATE->CURRENT_WORD[0] = 0;
	}
}

static int
	SPLIT_MATH_WORDS(
		const char *INPUT_TEXT, char (*WORDS)[24], int MAXIMUM_WORDS
	)
{
	int			WORD_COUNT = 0;
	const char	*CURSOR = INPUT_TEXT;

	while (*CURSOR && WORD_COUNT < MAXIMUM_WORDS)
	{
		uint8_t	CURRENT_CHARACTER = (uint8_t)*CURSOR;

		if (isdigit(CURRENT_CHARACTER))
		{
			int	LETTER_INDEX = 0;

			while (
				(
					isdigit((uint8_t)*CURSOR) ||
					(*CURSOR == '.' && isdigit((uint8_t)CURSOR[1])) ||
					(
						*CURSOR == ',' &&
						isdigit((uint8_t)CURSOR[1]) &&
						isdigit((uint8_t)CURSOR[2]) &&
						isdigit((uint8_t)CURSOR[3])
					)
				) &&
				LETTER_INDEX < 23
			)
			{
				if (*CURSOR != ',')
					WORDS[WORD_COUNT][LETTER_INDEX++] = *CURSOR;

				CURSOR++;
			}

			WORDS[WORD_COUNT++][LETTER_INDEX] = 0;
		}
		else if (isalpha(CURRENT_CHARACTER))
		{
			int	LETTER_INDEX = 0;

			while (
				(isalpha((uint8_t)*CURSOR) || *CURSOR == '\'') &&
				LETTER_INDEX < 23
			)
			{
				WORDS[WORD_COUNT][LETTER_INDEX++] =
					(char)tolower((uint8_t)*CURSOR);
				CURSOR++;
			}

			WORDS[WORD_COUNT++][LETTER_INDEX] = 0;
		}
		else if (strchr("+-*/^()%", CURRENT_CHARACTER))
		{
			WORDS[WORD_COUNT][0] = (char)CURRENT_CHARACTER;
			WORDS[WORD_COUNT++][1] = 0;
			CURSOR++;
		}
		else if (CURRENT_CHARACTER == ' ' || CURRENT_CHARACTER == '\t')
			CURSOR++;
		else
		{
			WORDS[WORD_COUNT][0] = (char)CURRENT_CHARACTER;
			WORDS[WORD_COUNT++][1] = 0;
			CURSOR++;
		}
	}

	return (WORD_COUNT);
}

static int
	MATH_SYMBOL(const char *WORD_TEXT, const char *PREVIOUS_WORD, char *OUTPUT)
{
	static const char	*NUMBER_WORDS[21] = {
		"zero", "one", "two", "three", "four", "five", "six", "seven", "eight",
		"nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen",
		"sixteen", "seventeen", "eighteen", "nineteen", "twenty"
	};
	static const char	*OPERATOR_WORDS[17][2] = {
		{ "+", "+" }, { "-", "-" }, { "*", "*" }, { "/", "/" }, { "^", "^" },
		{ "%", "%" }, { "(", "(" }, { ")", ")" }, { "plus", "+" },
		{ "minus", "-" }, { "times", "*" }, { "multiplied", "*" },
		{ "divided", "/" }, { "over", "/" }, { "sqrt", "sqrt" },
		{ "square", "sqrt" }, { "percent", "%" }
	};

	if (isdigit((uint8_t)WORD_TEXT[0]))
	{
		snprintf(OUTPUT, 24, "%s", WORD_TEXT);
		return (1);
	}

	int	NUMBER_VALUE;

	for (NUMBER_VALUE = 0; NUMBER_VALUE <= 20; NUMBER_VALUE++)
		if (!strcmp(WORD_TEXT, NUMBER_WORDS[NUMBER_VALUE]))
		{
			snprintf(OUTPUT, 24, "%d", NUMBER_VALUE);
			return (1);
		}

	size_t	OPERATOR_INDEX;

	for (
		OPERATOR_INDEX = 0;
		OPERATOR_INDEX < sizeof OPERATOR_WORDS / sizeof OPERATOR_WORDS[0];
		OPERATOR_INDEX++
	)
		if (!strcmp(WORD_TEXT, OPERATOR_WORDS[OPERATOR_INDEX][0]))
		{
			snprintf(OUTPUT, 24, "%s", OPERATOR_WORDS[OPERATOR_INDEX][1]);
			return (2);
		}

	if (
		!strcmp(WORD_TEXT, "x") &&
		PREVIOUS_WORD &&
		isdigit((uint8_t)PREVIOUS_WORD[0])
	)
	{
		snprintf(OUTPUT, 24, "*");
		return (2);
	}

	if (
		!strcmp(WORD_TEXT, "of") &&
		PREVIOUS_WORD &&
		(!strcmp(PREVIOUS_WORD, "%") || !strcmp(PREVIOUS_WORD, "percent"))
	)
	{
		snprintf(OUTPUT, 24, "of%%");
		return (2);
	}

	if (
		PREVIOUS_WORD &&
		(
			(
				!strcmp(WORD_TEXT, "by") &&
				(
					!strcmp(PREVIOUS_WORD, "divided") ||
					!strcmp(PREVIOUS_WORD, "multiplied")
				)
			) ||
			(!strcmp(WORD_TEXT, "root") && !strcmp(PREVIOUS_WORD, "square")) ||
			(!strcmp(WORD_TEXT, "of") && !strcmp(PREVIOUS_WORD, "root"))
		)
	)
	{
		OUTPUT[0] = 0;
		return (3);
	}

	return (0);
}

typedef struct
{
	char	SYMBOLS[40][24];
	int		SYMBOL_COUNT;
} MATH_SEQUENCE;

static void
	BUILD_MATH_SEQUENCE(
		char (*WORDS)[24], int FIRST_WORD, int END_WORD, MATH_SEQUENCE *SYMBOLS
	)
{
	SYMBOLS->SYMBOL_COUNT = 0;

	int	WORD_INDEX;

	for (
		WORD_INDEX = FIRST_WORD;
		WORD_INDEX < END_WORD && SYMBOLS->SYMBOL_COUNT < 40;
		WORD_INDEX++
	)
	{
		char	SYMBOL[24];
		int		SYMBOL_KIND = MATH_SYMBOL(
			WORDS[WORD_INDEX],
			WORD_INDEX > FIRST_WORD ? WORDS[WORD_INDEX - 1] : NULL, SYMBOL
		);

		if (SYMBOL_KIND == 1 || SYMBOL_KIND == 2)
			snprintf(
				SYMBOLS->SYMBOLS[SYMBOLS->SYMBOL_COUNT++], 24, "%s", SYMBOL
			);
	}
}

static int
	EVALUATE_MATH_SEQUENCE(const MATH_SEQUENCE *SYMBOLS, double *VALUE)
{
	char	EXPRESSION[1100];
	int		EXPRESSION_LENGTH = 0;
	int		OPERATION_COUNT = 0;
	int		SYMBOL_INDEX;

	for (
		SYMBOL_INDEX = 0;
		SYMBOL_INDEX < SYMBOLS->SYMBOL_COUNT && EXPRESSION_LENGTH < 1000;
		SYMBOL_INDEX++
	)
	{
		if (
			!strcmp(SYMBOLS->SYMBOLS[SYMBOL_INDEX], "sqrt") &&
			SYMBOL_INDEX + 1 < SYMBOLS->SYMBOL_COUNT &&
			isdigit((uint8_t)SYMBOLS->SYMBOLS[SYMBOL_INDEX + 1][0])
		)
		{
			EXPRESSION_LENGTH += snprintf(
				EXPRESSION + EXPRESSION_LENGTH,
				sizeof EXPRESSION - EXPRESSION_LENGTH, " sqrt(%s)",
				SYMBOLS->SYMBOLS[SYMBOL_INDEX + 1]
			);
			SYMBOL_INDEX++;
			OPERATION_COUNT++;
			continue ;
		}

		if (
			!strcmp(SYMBOLS->SYMBOLS[SYMBOL_INDEX], "%") &&
			SYMBOL_INDEX + 1 < SYMBOLS->SYMBOL_COUNT &&
			!strcmp(SYMBOLS->SYMBOLS[SYMBOL_INDEX + 1], "of%")
		)
		{
			EXPRESSION_LENGTH += snprintf(
				EXPRESSION + EXPRESSION_LENGTH,
				sizeof EXPRESSION - EXPRESSION_LENGTH, " / 100 *"
			);
			SYMBOL_INDEX++;
			OPERATION_COUNT++;
			continue ;
		}

		if (!strcmp(SYMBOLS->SYMBOLS[SYMBOL_INDEX], "of%"))
			continue ;

		if (
			!isdigit((uint8_t)SYMBOLS->SYMBOLS[SYMBOL_INDEX][0]) &&
			strcmp(SYMBOLS->SYMBOLS[SYMBOL_INDEX], "(") &&
			strcmp(SYMBOLS->SYMBOLS[SYMBOL_INDEX], ")")
		)
			OPERATION_COUNT++;

		EXPRESSION_LENGTH += snprintf(
			EXPRESSION + EXPRESSION_LENGTH,
			sizeof EXPRESSION - EXPRESSION_LENGTH, " %s",
			SYMBOLS->SYMBOLS[SYMBOL_INDEX]
		);
	}

	if (!OPERATION_COUNT)
		return (0);

	if (CALCULATOR_EVALUATE(EXPRESSION, VALUE))
		return (2);

	return (1);
}

static int
	MATH_SEQUENCE_PREFIX(
		const MATH_SEQUENCE *PREFIX_SEQUENCE, const MATH_SEQUENCE *FULL_SEQUENCE
	)
{
	if (PREFIX_SEQUENCE->SYMBOL_COUNT > FULL_SEQUENCE->SYMBOL_COUNT)
		return (0);

	int	SYMBOL_INDEX;

	for (
		SYMBOL_INDEX = 0;
		SYMBOL_INDEX < PREFIX_SEQUENCE->SYMBOL_COUNT;
		SYMBOL_INDEX++
	)
	{
		if (
			!strcmp(
				PREFIX_SEQUENCE->SYMBOLS[SYMBOL_INDEX],
				FULL_SEQUENCE->SYMBOLS[SYMBOL_INDEX]
			)
		)
			continue ;

		if (
			SYMBOL_INDEX == PREFIX_SEQUENCE->SYMBOL_COUNT - 1 &&
			isdigit((uint8_t)PREFIX_SEQUENCE->SYMBOLS[SYMBOL_INDEX][0]) &&
			!strncmp(
				FULL_SEQUENCE->SYMBOLS[SYMBOL_INDEX],
				PREFIX_SEQUENCE->SYMBOLS[SYMBOL_INDEX],
				strlen(PREFIX_SEQUENCE->SYMBOLS[SYMBOL_INDEX])
			)
		)
			continue ;

		return (0);
	}

	return (1);
}

static int
	MATH_SEQUENCES_EQUAL(
		const MATH_SEQUENCE *FIRST_SEQUENCE,
		const MATH_SEQUENCE *SECOND_SEQUENCE
	)
{
	if (FIRST_SEQUENCE->SYMBOL_COUNT != SECOND_SEQUENCE->SYMBOL_COUNT)
		return (0);

	int	SYMBOL_INDEX;

	for (
		SYMBOL_INDEX = 0;
		SYMBOL_INDEX < FIRST_SEQUENCE->SYMBOL_COUNT;
		SYMBOL_INDEX++
	)
		if (
			strcmp(
				FIRST_SEQUENCE->SYMBOLS[SYMBOL_INDEX],
				SECOND_SEQUENCE->SYMBOLS[SYMBOL_INDEX]
			)
		)
			return (0);

	return (1);
}

static int
	NEARLY_EQUAL(double FIRST_VALUE, double SECOND_VALUE)
{
	return (
		fabs(FIRST_VALUE - SECOND_VALUE) <=
			1e-6 * (fabs(SECOND_VALUE) > 1 ? fabs(SECOND_VALUE) : 1) ||
		fabs(FIRST_VALUE - SECOND_VALUE) <= 0.005
	);
}

static int
	MATH_TAIL_START(char (*WORDS)[24], int WORD_COUNT)
{
	int	START = WORD_COUNT;

	while (
		START > 0 &&
		MATH_SYMBOL(
			WORDS[START - 1], START > 1 ? WORDS[START - 2] : NULL,
			(char[24]){ 0 }
		)
	)
		START--;

	return (START);
}

static int
	MATH_RESULTS_CORRECT(const char *REPLY_TEXT)
{
	char	WORDS[80][24];
	int		WORD_COUNT = SPLIT_MATH_WORDS(REPLY_TEXT, WORDS, 80);
	int		WORD_INDEX;

	for (WORD_INDEX = 1; WORD_INDEX < WORD_COUNT; WORD_INDEX++)
	{
		char	SYMBOL[24];

		if (
			MATH_SYMBOL(WORDS[WORD_INDEX], WORDS[WORD_INDEX - 1], SYMBOL) ||
			!MATH_SYMBOL(
				WORDS[WORD_INDEX - 1],
				WORD_INDEX > 1 ? WORDS[WORD_INDEX - 2] : NULL, SYMBOL
			)
		)
			continue ;

		int				START = MATH_TAIL_START(WORDS, WORD_INDEX);
		MATH_SEQUENCE	SYMBOLS;

		BUILD_MATH_SEQUENCE(WORDS, START, WORD_INDEX, &SYMBOLS);

		double	VALUE;

		if (EVALUATE_MATH_SEQUENCE(&SYMBOLS, &VALUE) != 1)
			continue ;

		int	CHECK_INDEX;

		for (
			CHECK_INDEX = WORD_INDEX;
			CHECK_INDEX < WORD_COUNT && CHECK_INDEX < WORD_INDEX + 3;
			CHECK_INDEX++
		)
		{
			if (
				!strcmp(WORDS[CHECK_INDEX], ",") ||
				!strcmp(WORDS[CHECK_INDEX], ".") ||
				!strcmp(WORDS[CHECK_INDEX], "?") ||
				!strcmp(WORDS[CHECK_INDEX], "!")
			)
				break ;

			if (isdigit((uint8_t)WORDS[CHECK_INDEX][0]))
			{
				if (!NEARLY_EQUAL(VALUE, atof(WORDS[CHECK_INDEX])))
					return (0);

				break ;
			}
		}
	}

	return (1);
}

typedef struct
{
	MATH_SEQUENCE	EXPRESSIONS[4];
	int				EXPRESSION_COUNT;
	double			RESULTS[4];
	int				RESULT_COUNT;
	char			NUMBERS[64][24];
	int				NUMBER_COUNT;
} MATH_CONTEXT;

static void
	INITIALIZE_MATH_CONTEXT(ENGINE_STATE *ENGINE, MATH_CONTEXT *MATH_STATE)
{
	MATH_STATE->EXPRESSION_COUNT = MATH_STATE->RESULT_COUNT =
		MATH_STATE->NUMBER_COUNT = 0;

	int	ACTION_INDEX;

	for (
		ACTION_INDEX = 0;
		ACTION_INDEX < ENGINE->ACTION_COUNT && MATH_STATE->EXPRESSION_COUNT < 4;
		ACTION_INDEX++
	)
	{
		const char	*LOG_LINE = ENGINE->ACTION_LOG[ACTION_INDEX];

		if (
			tolower((uint8_t)LOG_LINE[0]) != 'c' ||
			tolower((uint8_t)LOG_LINE[1]) != 'a' ||
			tolower((uint8_t)LOG_LINE[2]) != 'l' ||
			tolower((uint8_t)LOG_LINE[3]) != 'c'
		)
			continue ;

		char	*PARSE_END;
		double	VALUE =
			strtod(ENGINE->ACTION_RESULTS[ACTION_INDEX], &PARSE_END);

		if (PARSE_END == ENGINE->ACTION_RESULTS[ACTION_INDEX])
			continue ;

		const char	*SPACE_POSITION = strchr(LOG_LINE, ' ');

		if (!SPACE_POSITION)
			continue ;

		char	WORDS[80][24];
		int		WORD_COUNT = SPLIT_MATH_WORDS(SPACE_POSITION + 1, WORDS, 80);

		BUILD_MATH_SEQUENCE(
			WORDS, 0, WORD_COUNT,
			&MATH_STATE->EXPRESSIONS[MATH_STATE->EXPRESSION_COUNT]
		);

		int	SYMBOL_INDEX;

		for (
			SYMBOL_INDEX = 0;
			SYMBOL_INDEX <
					MATH_STATE->EXPRESSIONS[MATH_STATE->EXPRESSION_COUNT]
						.SYMBOL_COUNT &&
				MATH_STATE->NUMBER_COUNT < 64;
			SYMBOL_INDEX++
		)
			if (
				isdigit(
					(uint8_t)
						MATH_STATE->EXPRESSIONS[MATH_STATE->EXPRESSION_COUNT]
							.SYMBOLS[SYMBOL_INDEX][0]
				)
			)
				snprintf(
					MATH_STATE->NUMBERS[MATH_STATE->NUMBER_COUNT++], 24, "%s",
					MATH_STATE->EXPRESSIONS[MATH_STATE->EXPRESSION_COUNT]
						.SYMBOLS[SYMBOL_INDEX]
				);

		if (MATH_STATE->NUMBER_COUNT < 64)
			CALCULATOR_FORMAT(
				VALUE, MATH_STATE->NUMBERS[MATH_STATE->NUMBER_COUNT++], 24
			);

		MATH_STATE->RESULTS[MATH_STATE->RESULT_COUNT++] = VALUE;
		MATH_STATE->EXPRESSION_COUNT++;
	}
}

static int
	NUMBER_HAS_PREFIX(
		MATH_CONTEXT *MATH_STATE, const char *PREFIX, int WHOLE_NUMBER
	)
{
	size_t	PREFIX_LENGTH = strlen(PREFIX);
	int		NUMBER_INDEX;

	for (
		NUMBER_INDEX = 0;
		NUMBER_INDEX < MATH_STATE->NUMBER_COUNT;
		NUMBER_INDEX++
	)
		if (
			!strncmp(
				MATH_STATE->NUMBERS[NUMBER_INDEX], PREFIX, PREFIX_LENGTH
			) &&
			(!WHOLE_NUMBER || !MATH_STATE->NUMBERS[NUMBER_INDEX][PREFIX_LENGTH])
		)
			return (1);

	return (0);
}

static int	CLASSIFY_MATH_TOKEN(
	ENGINE_STATE *ENGINE, int32_t TOKEN_ID, char *TOKEN_SPELLING
);

static int
	MATH_TOKEN_CACHED(
		ENGINE_STATE *ENGINE, int32_t TOKEN_ID, char *TOKEN_SPELLING
	)
{
	static uint8_t	*KIND_CACHE;
	static int		CACHED_VOCABULARY_SIZE;

	if (
		!KIND_CACHE ||
		CACHED_VOCABULARY_SIZE != ENGINE->LOADED_BRAIN.NEURAL_WEB->WORD_COUNT
	)
	{
		free(KIND_CACHE);
		CACHED_VOCABULARY_SIZE = ENGINE->LOADED_BRAIN.NEURAL_WEB->WORD_COUNT;
		KIND_CACHE = malloc(CACHED_VOCABULARY_SIZE);

		int	TOKEN_INDEX;

		for (
			TOKEN_INDEX = 0;
			TOKEN_INDEX < CACHED_VOCABULARY_SIZE;
			TOKEN_INDEX++
		)
		{
			char	SCRATCH_SPELLING[24];

			KIND_CACHE[TOKEN_INDEX] = (uint8_t
			)CLASSIFY_MATH_TOKEN(ENGINE, TOKEN_INDEX, SCRATCH_SPELLING);
		}
	}

	if (!KIND_CACHE[TOKEN_ID])
		return (0);

	return (CLASSIFY_MATH_TOKEN(ENGINE, TOKEN_ID, TOKEN_SPELLING));
}

static int
	CLASSIFY_MATH_TOKEN(
		ENGINE_STATE *ENGINE, int32_t TOKEN_ID, char *TOKEN_SPELLING
	)
{
	if (
		TOKEN_ID >= TOKEN_FIRST_CHARACTER &&
		TOKEN_ID < TOKEN_FIRST_CHARACTER + CHARACTER_COUNT
	)
	{
		TOKEN_SPELLING[0] =
			SPELLING_CHARACTERS[TOKEN_ID - TOKEN_FIRST_CHARACTER];
		TOKEN_SPELLING[1] = 0;

		if (isdigit((uint8_t)TOKEN_SPELLING[0]))
			return (1);

		return (0);
	}

	if (
		TOKEN_ID >= TOKEN_FIRST_CHARACTER + CHARACTER_COUNT &&
		TOKEN_ID < TOKEN_FIRST_WORD
	)
	{
		TOKEN_SPELLING[0] = SPELLING_CHARACTERS
			[TOKEN_ID - TOKEN_FIRST_CHARACTER - CHARACTER_COUNT];
		TOKEN_SPELLING[1] = 0;

		if (isdigit((uint8_t)TOKEN_SPELLING[0]))
			return (4);

		return (0);
	}

	if (TOKEN_ID < TOKEN_FIRST_WORD)
		return (0);

	const char	*LEXEME_STRING =
		ENGINE->LOADED_BRAIN.LEXICON
			->STRINGS[ENGINE->LOADED_BRAIN.LEXICON->TOKEN_TO_LEXEME[TOKEN_ID]];

	snprintf(TOKEN_SPELLING, 24, "%s", LEXEME_STRING);

	char	OPERATOR_SYMBOL[24];

	if (!strcmp(LEXEME_STRING, "."))
		return (5);

	if (
		MATH_SYMBOL(LEXEME_STRING, "9", OPERATOR_SYMBOL) ||
		!strcmp(LEXEME_STRING, "by") ||
		!strcmp(LEXEME_STRING, "root") ||
		!strcmp(LEXEME_STRING, "of")
	)
		return (2);

	return (0);
}

static int
	MATH_CONTEXT_ALLOWS(
		MATH_CONTEXT *MATH_STATE, char (*MATH_WORDS)[24], int MATH_WORD_COUNT,
		int TAIL_START, int ENDS_WITH_DIGIT, int TOKEN_KIND,
		const char *CANDIDATE_WORD
	)
{
	MATH_SEQUENCE	TAIL_SEQUENCE;

	BUILD_MATH_SEQUENCE(
		MATH_WORDS, TAIL_START, MATH_WORD_COUNT, &TAIL_SEQUENCE
	);

	int	ENDS_WITH_DOT = MATH_WORD_COUNT >= 2 &&
		!strcmp(MATH_WORDS[MATH_WORD_COUNT - 1], ".") &&
		isdigit((uint8_t)MATH_WORDS[MATH_WORD_COUNT - 2][0]);

	if (TOKEN_KIND == 5)
	{
		char	DOTTED_NUMBER[48];

		if (
			ENDS_WITH_DIGIT &&
			TAIL_SEQUENCE.SYMBOL_COUNT &&
			isdigit(
				(uint8_t)
					TAIL_SEQUENCE.SYMBOLS[TAIL_SEQUENCE.SYMBOL_COUNT - 1][0]
			)
		)
		{
			snprintf(
				DOTTED_NUMBER, sizeof DOTTED_NUMBER, "%s.",
				TAIL_SEQUENCE.SYMBOLS[TAIL_SEQUENCE.SYMBOL_COUNT - 1]
			);

			if (NUMBER_HAS_PREFIX(MATH_STATE, DOTTED_NUMBER, 0))
				return (1);
		}

		TOKEN_KIND = 0;
	}

	if (TOKEN_KIND == 2)
	{
		char	SYMBOL_CHECK[24];

		if (
			!MATH_SYMBOL(
				CANDIDATE_WORD,
				MATH_WORD_COUNT > TAIL_START ? MATH_WORDS[MATH_WORD_COUNT - 1]
				: NULL,
				SYMBOL_CHECK
			)
		)
			TOKEN_KIND = 0;
	}

	if (
		!TOKEN_KIND &&
		ENDS_WITH_DIGIT &&
		TAIL_SEQUENCE.SYMBOL_COUNT &&
		isdigit(
			(uint8_t)TAIL_SEQUENCE.SYMBOLS[TAIL_SEQUENCE.SYMBOL_COUNT - 1][0]
		) &&
		!NUMBER_HAS_PREFIX(
			MATH_STATE, TAIL_SEQUENCE.SYMBOLS[TAIL_SEQUENCE.SYMBOL_COUNT - 1], 1
		)
	)
		return (0);

	if (TOKEN_KIND)
	{
		char	DIGIT_SYMBOL[24];
		char	CURRENT_NUMBER[48];
		int		DIGIT_SYMBOL_KIND;

		if (TOKEN_KIND == 4 || TOKEN_KIND == 1)
			DIGIT_SYMBOL_KIND = 1;
		else
			DIGIT_SYMBOL_KIND = MATH_SYMBOL(CANDIDATE_WORD, "9", DIGIT_SYMBOL);

		if (DIGIT_SYMBOL_KIND == 1)
		{
			const char	*NUMBER_PIECE =
				TOKEN_KIND == 2 ? DIGIT_SYMBOL : CANDIDATE_WORD;

			if (TOKEN_KIND == 4)
				snprintf(
					CURRENT_NUMBER, sizeof CURRENT_NUMBER, "%s%s",
					ENDS_WITH_DIGIT && TAIL_SEQUENCE.SYMBOL_COUNT
						? TAIL_SEQUENCE.SYMBOLS[TAIL_SEQUENCE.SYMBOL_COUNT - 1]
						: "",
					NUMBER_PIECE
				);
			else if (ENDS_WITH_DOT)
				snprintf(
					CURRENT_NUMBER, sizeof CURRENT_NUMBER, "%s.%s",
					MATH_WORDS[MATH_WORD_COUNT - 2], NUMBER_PIECE
				);
			else
				snprintf(
					CURRENT_NUMBER, sizeof CURRENT_NUMBER, "%s", NUMBER_PIECE
				);

			if (!NUMBER_HAS_PREFIX(MATH_STATE, CURRENT_NUMBER, 0))
				return (0);

			if (ENDS_WITH_DOT)
				return (1);
		}
	}

	int	HAS_OPERATOR = 0;
	int	INDEX;

	for (INDEX = 0; INDEX < TAIL_SEQUENCE.SYMBOL_COUNT; INDEX++)
		if (!isdigit((uint8_t)TAIL_SEQUENCE.SYMBOLS[INDEX][0]))
			HAS_OPERATOR = 1;

	int		IS_KNOWN = 0;
	double	SEQUENCE_VALUE;

	for (INDEX = 0; INDEX < MATH_STATE->EXPRESSION_COUNT; INDEX++)
		if (
			MATH_SEQUENCES_EQUAL(
				&TAIL_SEQUENCE, &MATH_STATE->EXPRESSIONS[INDEX]
			)
		)
			IS_KNOWN = 1;

	if (
		!IS_KNOWN &&
		HAS_OPERATOR &&
		EVALUATE_MATH_SEQUENCE(&TAIL_SEQUENCE, &SEQUENCE_VALUE) == 1
	)
	{
		int	INDEX;

		for (INDEX = 0; INDEX < MATH_STATE->RESULT_COUNT; INDEX++)
			if (NEARLY_EQUAL(SEQUENCE_VALUE, MATH_STATE->RESULTS[INDEX]))
				IS_KNOWN = 1;
	}

	if (TAIL_SEQUENCE.SYMBOL_COUNT > 16)
		return (1);

	if (!HAS_OPERATOR && TAIL_SEQUENCE.SYMBOL_COUNT == 1)
	{
		double	NUMBER_VALUE = atof(TAIL_SEQUENCE.SYMBOLS[0]);
		int		MATCHES_RESULT = 0;
		int		IS_PREFIX = 0;
		int		INDEX;

		for (INDEX = 0; INDEX < MATH_STATE->RESULT_COUNT; INDEX++)
			if (NEARLY_EQUAL(NUMBER_VALUE, MATH_STATE->RESULTS[INDEX]))
				MATCHES_RESULT = 1;

		for (INDEX = 0; INDEX < MATH_STATE->EXPRESSION_COUNT; INDEX++)
			if (
				MATH_STATE->EXPRESSIONS[INDEX].SYMBOL_COUNT > 1 &&
				MATH_SEQUENCE_PREFIX(
					&TAIL_SEQUENCE, &MATH_STATE->EXPRESSIONS[INDEX]
				)
			)
				IS_PREFIX = 1;

		if (IS_PREFIX && !MATCHES_RESULT)
			HAS_OPERATOR = 1;
	}

	if (!TOKEN_KIND)
		return (!HAS_OPERATOR || IS_KNOWN);

	const char	*PREVIOUS_WORD =
		MATH_WORD_COUNT > TAIL_START ? MATH_WORDS[MATH_WORD_COUNT - 1] : NULL;
	char		SYMBOL_NAME[24];
	int			SYMBOL_KIND;

	if (TOKEN_KIND == 4)
		SYMBOL_KIND = 1;
	else
		SYMBOL_KIND = MATH_SYMBOL(CANDIDATE_WORD, PREVIOUS_WORD, SYMBOL_NAME);

	if (TOKEN_KIND == 2 && !SYMBOL_KIND)
		return (!HAS_OPERATOR || IS_KNOWN);

	if (
		SYMBOL_KIND == 1 &&
		TOKEN_KIND != 4 &&
		TAIL_SEQUENCE.SYMBOL_COUNT &&
		HAS_OPERATOR &&
		!IS_KNOWN &&
		isdigit(
			(uint8_t)TAIL_SEQUENCE.SYMBOLS[TAIL_SEQUENCE.SYMBOL_COUNT - 1][0]
		)
	)
		return (0);

	if (SYMBOL_KIND == 3)
		return (1);

	MATH_SEQUENCE	EXTENDED_SEQUENCE = TAIL_SEQUENCE;

	if (TOKEN_KIND == 4)
	{
		if (
			!ENDS_WITH_DIGIT ||
			!EXTENDED_SEQUENCE.SYMBOL_COUNT ||
			!isdigit(
				(uint8_t) EXTENDED_SEQUENCE
					.SYMBOLS[EXTENDED_SEQUENCE.SYMBOL_COUNT - 1][0]
			)
		)
			return (1);

		size_t	LAST_LENGTH =
			strlen(EXTENDED_SEQUENCE.SYMBOLS[EXTENDED_SEQUENCE.SYMBOL_COUNT - 1]
			);

		if (LAST_LENGTH < 22)
		{
			EXTENDED_SEQUENCE
				.SYMBOLS[EXTENDED_SEQUENCE.SYMBOL_COUNT - 1][LAST_LENGTH] =
				CANDIDATE_WORD[0];
			EXTENDED_SEQUENCE
				.SYMBOLS[EXTENDED_SEQUENCE.SYMBOL_COUNT - 1][LAST_LENGTH + 1] =
				0;
		}
	}
	else if (EXTENDED_SEQUENCE.SYMBOL_COUNT < 40)
		snprintf(
			EXTENDED_SEQUENCE.SYMBOLS[EXTENDED_SEQUENCE.SYMBOL_COUNT++], 24,
			"%s",
			SYMBOL_KIND == 1 && TOKEN_KIND == 1 ? CANDIDATE_WORD : SYMBOL_NAME
		);

	int	EXTENDED_HAS_OPERATOR = 0;

	for (INDEX = 0; INDEX < EXTENDED_SEQUENCE.SYMBOL_COUNT; INDEX++)
		if (!isdigit((uint8_t)EXTENDED_SEQUENCE.SYMBOLS[INDEX][0]))
			EXTENDED_HAS_OPERATOR = 1;

	if (!EXTENDED_HAS_OPERATOR)
		return (1);

	for (INDEX = 0; INDEX < MATH_STATE->EXPRESSION_COUNT; INDEX++)
		if (
			MATH_SEQUENCE_PREFIX(
				&EXTENDED_SEQUENCE, &MATH_STATE->EXPRESSIONS[INDEX]
			)
		)
			return (1);

	return (0);
}

static void
	WORD_STEM(const char *SOURCE_WORD, char *OUTPUT, int OUTPUT_SIZE)
{
	int	STEM_LENGTH = 0;

	for (
		;
		SOURCE_WORD[STEM_LENGTH] && STEM_LENGTH < OUTPUT_SIZE - 1;
		STEM_LENGTH++
	)
		OUTPUT[STEM_LENGTH] = (char)tolower((uint8_t)SOURCE_WORD[STEM_LENGTH]);

	OUTPUT[STEM_LENGTH] = 0;

	if (
		STEM_LENGTH > 2 &&
		OUTPUT[STEM_LENGTH - 2] == '\'' &&
		OUTPUT[STEM_LENGTH - 1] == 's'
	)
	{
		STEM_LENGTH -= 2;
		OUTPUT[STEM_LENGTH] = 0;
	}

	static const char	*SUFFIXES[5] = { "ing", "ed", "es", "s", NULL };
	int					SUFFIX_INDEX;

	for (SUFFIX_INDEX = 0; SUFFIXES[SUFFIX_INDEX]; SUFFIX_INDEX++)
	{
		int	SUFFIX_LENGTH = (int)strlen(SUFFIXES[SUFFIX_INDEX]);

		if (
			STEM_LENGTH > SUFFIX_LENGTH + 2 &&
			!strcmp(
				OUTPUT + STEM_LENGTH - SUFFIX_LENGTH, SUFFIXES[SUFFIX_INDEX]
			)
		)
		{
			OUTPUT[STEM_LENGTH - SUFFIX_LENGTH] = 0;
			STEM_LENGTH -= SUFFIX_LENGTH;
			break ;
		}
	}

	if (STEM_LENGTH > 3 && OUTPUT[STEM_LENGTH - 1] == 'e')
		OUTPUT[STEM_LENGTH - 1] =
			0; /* close / closes / closed / closing -> clos */
}

typedef struct
{
	char	KEYS[1024][32];
	uint8_t	USED[1024];
} STEM_SET;

static uint32_t
	HASH_STEM(const char *CHARACTER_CURSOR)
{
	uint32_t	HASH_VALUE = (unsigned int)2166136261;

	for (; *CHARACTER_CURSOR; CHARACTER_CURSOR++)
		HASH_VALUE =
			(HASH_VALUE ^ (uint8_t)*CHARACTER_CURSOR) * (unsigned int)16777619;

	return (HASH_VALUE);
}

static void
	ADD_STEM(STEM_SET *STEMS, const char *SOURCE_WORD)
{
	char	STEM[32];

	WORD_STEM(SOURCE_WORD, STEM, sizeof STEM);

	if (!STEM[0])
		return ;

	uint32_t	SLOT = HASH_STEM(STEM) & 1023;
	int			PROBE_COUNT;

	for (
		PROBE_COUNT = 0;
		PROBE_COUNT < 1024;
		PROBE_COUNT++, SLOT = (SLOT + 1) & 1023
	)
	{
		if (!STEMS->USED[SLOT])
		{
			STEMS->USED[SLOT] = 1;
			snprintf(STEMS->KEYS[SLOT], 32, "%s", STEM);
			return ;
		}

		if (!strcmp(STEMS->KEYS[SLOT], STEM))
			return ;
	}
}

static int
	HAS_STEM_IN_SET(const STEM_SET *STEMS, const char *SOURCE_WORD)
{
	char	STEM[32];

	WORD_STEM(SOURCE_WORD, STEM, sizeof STEM);

	uint32_t	SLOT = HASH_STEM(STEM) & 1023;
	int			PROBE_COUNT;

	for (
		PROBE_COUNT = 0;
		PROBE_COUNT < 1024;
		PROBE_COUNT++, SLOT = (SLOT + 1) & 1023
	)
	{
		if (!STEMS->USED[SLOT])
			return (0);

		if (!strcmp(STEMS->KEYS[SLOT], STEM))
			return (1);
	}

	return (0);
}

static char	SELF_DESCRIPTION[2048];
static char	(*PLAIN_TALK_LINES)[96];
static int	PLAIN_TALK_COUNT;

/* lang/plain_talk.txt: sentences Lucy may always say in chat */
static void
	LOAD_PLAIN_TALK(void)
{
	FILE	*STREAM = fopen(PLAIN_TALK_PATH, "rb");
	char	LINE[200];

	PLAIN_TALK_COUNT = 0;

	if (!STREAM)
		return ;

	if (!PLAIN_TALK_LINES)
		PLAIN_TALK_LINES = malloc(1024 * sizeof *PLAIN_TALK_LINES);

	while (
		PLAIN_TALK_LINES &&
		PLAIN_TALK_COUNT < 1024 &&
		fgets(LINE, sizeof LINE, STREAM)
	)
	{
		size_t	LENGTH = strlen(LINE);

		while (LENGTH && strchr("\r\n .!?", LINE[LENGTH - 1]))
			LINE[--LENGTH] = 0;

		if (!LENGTH || LINE[0] == '#' || LENGTH >= 96)
			continue ;

		LOWERCASE_STRING(LINE);
		snprintf(PLAIN_TALK_LINES[PLAIN_TALK_COUNT++], 96, "%s", LINE);
	}

	fclose(STREAM);
}

static void
	LOAD_SAFE_WORDS(ENGINE_STATE *ENGINE)
{
	{
		FILE	*SELF_STREAM = fopen(SELF_PATH, "rb");

		if (SELF_STREAM)
		{
			size_t	BYTES_READ = fread(
				SELF_DESCRIPTION, 1, sizeof SELF_DESCRIPTION - 1, SELF_STREAM
			);

			SELF_DESCRIPTION[BYTES_READ] = 0;
			fclose(SELF_STREAM);
		}
	}

	LOAD_PLAIN_TALK();
	ENGINE->SAFE_WORD_COUNT = 0;

	FILE	*STREAM = fopen(SAFE_PATH, "rb");

	if (!STREAM)
		return ;

	char	LINE_BUFFER[128];

	ENGINE->SAFE_WORDS = malloc(4096 * sizeof *ENGINE->SAFE_WORDS);

	while (
		fgets(LINE_BUFFER, sizeof LINE_BUFFER, STREAM) &&
		ENGINE->SAFE_WORD_COUNT < 4096
	)
	{
		if (LINE_BUFFER[0] == '#')
			continue ;

		size_t	LINE_LENGTH = strlen(LINE_BUFFER);

		while (
			LINE_LENGTH &&
			(
				LINE_BUFFER[LINE_LENGTH - 1] == '\n' ||
				LINE_BUFFER[LINE_LENGTH - 1] == '\r' ||
				LINE_BUFFER[LINE_LENGTH - 1] == ' '
			)
		)
			LINE_BUFFER[--LINE_LENGTH] = 0;

		if (LINE_LENGTH && LINE_LENGTH < 32)
			snprintf(
				ENGINE->SAFE_WORDS[ENGINE->SAFE_WORD_COUNT++], 32, "%s",
				LINE_BUFFER
			);
	}

	fclose(STREAM);
}

static void
	COLLECT_GROUNDING(
		ENGINE_STATE *ENGINE, const int32_t *SEQUENCE, int SEQUENCE_LENGTH,
		STEM_SET *STEMS, COPY_CONSTRAINT *COPY_STATE
	)
{
	LANGUAGE	*LEXICON = ENGINE->LOADED_BRAIN.LEXICON;
	int			IN_ASSISTANT_TURN = 0;
	int			POSITION;

	for (POSITION = 0; POSITION < ENGINE->SAFE_WORD_COUNT; POSITION++)
		ADD_STEM(STEMS, ENGINE->SAFE_WORDS[POSITION]);

	if (ENGINE->ASSISTANT_NAME[0])
		ADD_STEM(STEMS, ENGINE->ASSISTANT_NAME);

	for (POSITION = 0; POSITION < SEQUENCE_LENGTH; POSITION++)
	{
		int32_t	TOKEN_ID = SEQUENCE[POSITION];

		if (TOKEN_ID == TOKEN_CODE_TURN)
		{
			IN_ASSISTANT_TURN = 1;
			continue ;
		}

		if (
			TOKEN_ID == TOKEN_USER_TURN ||
			TOKEN_ID == TOKEN_MEMORY ||
			TOKEN_ID == TOKEN_YOU ||
			TOKEN_ID == TOKEN_TEXT ||
			TOKEN_ID == ENGINE->TOKEN_DO ||
			TOKEN_ID == ENGINE->TOKEN_RESULT
		)
		{
			IN_ASSISTANT_TURN = 0;
			continue ;
		}

		if (IN_ASSISTANT_TURN)
			continue ;

		if (TOKEN_ID >= TOKEN_FIRST_WORD && TOKEN_ID < LEXICON->TOKEN_COUNT)
			ADD_STEM(
				STEMS, LEXICON->STRINGS[LEXICON->TOKEN_TO_LEXEME[TOKEN_ID]]
			);
		else if (
			TOKEN_ID >= TOKEN_FIRST_CHARACTER &&
			TOKEN_ID < TOKEN_FIRST_CHARACTER + CHARACTER_COUNT
		)
		{
			char	SPELLED_WORD[33];
			int		SPELLED_LENGTH = 0;

			SPELLED_WORD[SPELLED_LENGTH++] =
				SPELLING_CHARACTERS[TOKEN_ID - TOKEN_FIRST_CHARACTER];

			while (
				POSITION + 1 < SEQUENCE_LENGTH &&
				SEQUENCE[POSITION + 1] >=
					TOKEN_FIRST_CHARACTER + CHARACTER_COUNT &&
				SEQUENCE[POSITION + 1] < TOKEN_FIRST_WORD &&
				SPELLED_LENGTH < 32
			)
				SPELLED_WORD[SPELLED_LENGTH++] = SPELLING_CHARACTERS
					[SEQUENCE[++POSITION] - TOKEN_FIRST_CHARACTER -
						CHARACTER_COUNT];

			SPELLED_WORD[SPELLED_LENGTH] = 0;
			ADD_STEM(STEMS, SPELLED_WORD);

			if (COPY_STATE && COPY_STATE->SPELLED_WORD_COUNT < 512)
				snprintf(
					COPY_STATE->SPELLED_WORDS[COPY_STATE->SPELLED_WORD_COUNT++],
					33, "%s", SPELLED_WORD
				);
		}
	}
}

static int
	IS_WORD_GROUNDED(const STEM_SET *STEMS, const char *CANDIDATE_WORD)
{
	int			ALL_DIGITS = 1;
	const char	*CURSOR;

	for (CURSOR = CANDIDATE_WORD; *CURSOR; CURSOR++)
		if (!isdigit((uint8_t)*CURSOR))
			ALL_DIGITS = 0;

	return (ALL_DIGITS || HAS_STEM_IN_SET(STEMS, CANDIDATE_WORD));
}

static int
	FIND_UNGROUNDED_WORD(
		ENGINE_STATE *ENGINE, const int32_t *SEQUENCE, int SEQUENCE_LENGTH,
		const char *REPLY_TEXT, char *BAD_WORD, int BAD_WORD_SIZE
	)
{
	STEM_SET	*STEMS = calloc(1, sizeof *STEMS);

	COLLECT_GROUNDING(ENGINE, SEQUENCE, SEQUENCE_LENGTH, STEMS, NULL);

	char		CURRENT_WORD[64];
	int			WORD_LENGTH = 0;
	int			FOUND_UNGROUNDED = 0;
	const char	*CURSOR;

	for (CURSOR = REPLY_TEXT;; CURSOR++)
	{
		if (
			isalnum((uint8_t)*CURSOR) ||
			(*CURSOR == '\'' && WORD_LENGTH && isalpha((uint8_t)CURSOR[1])) ||
			((uint8_t)*CURSOR >= 0X80)
		)
		{
			if (WORD_LENGTH < 63)
				CURRENT_WORD[WORD_LENGTH++] = *CURSOR;

			continue ;
		}

		if (WORD_LENGTH)
		{
			CURRENT_WORD[WORD_LENGTH] = 0;

			char	LOWER_WORD[64];
			int		LOWER_INDEX;

			for (LOWER_INDEX = 0; LOWER_INDEX <= WORD_LENGTH; LOWER_INDEX++)
				LOWER_WORD[LOWER_INDEX] =
					(char)tolower((uint8_t)CURRENT_WORD[LOWER_INDEX]);

			if (!IS_WORD_GROUNDED(STEMS, LOWER_WORD))
			{
				FOUND_UNGROUNDED = 1;

				if (BAD_WORD)
					snprintf(BAD_WORD, BAD_WORD_SIZE, "%s", LOWER_WORD);

				break ;
			}

			WORD_LENGTH = 0;
		}

		if (!*CURSOR)
			break ;
	}

	free(STEMS);

	return (FOUND_UNGROUNDED);
}

static int
	GENERATE_REPLY(
		ENGINE_STATE *ENGINE, int32_t *SEQUENCE, int SEQUENCE_LENGTH,
		int32_t *OUTPUT_TOKENS, int OUTPUT_CAPACITY, int GENERATION_MODE,
		double *RESULT_SCORE
	)
{
	COPY_CONSTRAINT	COPY_STATE;
	int				USE_COPY =
		GENERATION_MODE == 1 && ENGINE->COPY_CONSTRAINT_ON;

	if (USE_COPY)
		INITIALIZE_COPY(ENGINE, &COPY_STATE, SEQUENCE, SEQUENCE_LENGTH);

	int32_t			*OUTPUT_START = OUTPUT_TOKENS;
	MATH_CONTEXT	MATH_STATE;

	MATH_STATE.EXPRESSION_COUNT = 0;

	if (GENERATION_MODE == 0 && ENGINE->COPY_CONSTRAINT_ON)
		INITIALIZE_MATH_CONTEXT(ENGINE, &MATH_STATE);

	COPY_CONSTRAINT	GROUND_COPY;
	int				USE_GROUNDING =
		GENERATION_MODE == 0 && ENGINE->GROUNDING_ON && ENGINE->SAFE_WORD_COUNT;

	if (USE_GROUNDING)
	{
		INITIALIZE_COPY(ENGINE, &GROUND_COPY, SEQUENCE, 0);
		GROUND_COPY.TOKEN_REMEMBER = -1;

		STEM_SET	*STEMS = calloc(1, sizeof *STEMS);

		COLLECT_GROUNDING(
			ENGINE, SEQUENCE, SEQUENCE_LENGTH, STEMS, &GROUND_COPY
		);

		LANGUAGE	*GROUND_LEXICON = ENGINE->LOADED_BRAIN.LEXICON;
		int32_t		TOKEN_ID;

		for (
			TOKEN_ID = TOKEN_FIRST_WORD;
			TOKEN_ID < ENGINE->LOADED_BRAIN.NEURAL_WEB->WORD_COUNT &&TOKEN_ID <
				GROUND_LEXICON->TOKEN_COUNT;
			TOKEN_ID++
		)
		{
			const char	*LEXEME_STRING =
				GROUND_LEXICON
					->STRINGS[GROUND_LEXICON->TOKEN_TO_LEXEME[TOKEN_ID]];
			int			HAS_ALPHANUMERIC = 0;
			const char	*CHARACTER_CURSOR;

			for (
				CHARACTER_CURSOR = LEXEME_STRING;
				*CHARACTER_CURSOR;
				CHARACTER_CURSOR++
			)
				if (
					isalnum((uint8_t)*CHARACTER_CURSOR) ||
					(uint8_t)*CHARACTER_CURSOR >= 0X80
				)
					HAS_ALPHANUMERIC = 1;

			GROUND_COPY.IN_CONTEXT[TOKEN_ID] =
				GROUND_COPY.IN_CONTEXT[TOKEN_ID] || !HAS_ALPHANUMERIC ||
				HAS_STEM_IN_SET(STEMS, LEXEME_STRING);
		}

		free(STEMS);
	}

	WEB			*NEURAL_WEB = ENGINE->LOADED_BRAIN.NEURAL_WEB;
	LANGUAGE	*LEXICON = ENGINE->LOADED_BRAIN.LEXICON;
	int			MAX_POSITIONS = NEURAL_WEB->CONFIGURATION.MAXIMUM_LENGTH;
	int			VOCABULARY_SIZE = NEURAL_WEB->WORD_COUNT;
	float		*PROBABILITIES = malloc(VOCABULARY_SIZE * 4);
	int32_t		*CANDIDATES = malloc(VOCABULARY_SIZE * 4);
	float		*PENALTIES = calloc(VOCABULARY_SIZE, 4);
	float		*RAW_PROBABILITIES = malloc(VOCABULARY_SIZE * 4);
	double		LOG_PROBABILITY = 0;

	ENGINE->DRAFT_LOWEST = 0;

	int	STOPPED = 0;

	if (GENERATION_MODE == 0)
	{
		int	INDEX;

		for (INDEX = 0; INDEX < ENGINE->WORKING_MEMORY.SAID_COUNT; INDEX++)
		{
			int32_t	SAID_TOKENS[WORKING_MEMORY_IDS * 4];
			int		SAID_TOKEN_COUNT = WORD_IDS_TO_TOKENS(
				LEXICON, ENGINE->WORKING_MEMORY.SAID_MESSAGES[INDEX].IDS,
				ENGINE->WORKING_MEMORY.SAID_MESSAGES[INDEX].ID_COUNT,
				SAID_TOKENS, WORKING_MEMORY_IDS * 4
			);
			int		INNER_INDEX;

			for (INNER_INDEX = 0; INNER_INDEX < SAID_TOKEN_COUNT; INNER_INDEX++)
				if (
					SAID_TOKENS[INNER_INDEX] >= TOKEN_FIRST_WORD &&
					IS_CONTENT_WORD(
						ENGINE,
						LEXICON->TOKEN_TO_LEXEME[SAID_TOKENS[INNER_INDEX]]
					)
				)
					PENALTIES[SAID_TOKENS[INNER_INDEX]] = (float)0.5;
		}

		for (INDEX = 0; INDEX < ENGINE->LAST_USER_TOKEN_COUNT; INDEX++)
			if (
				ENGINE->LAST_USER_TOKENS[INDEX] >= 0 &&
				ENGINE->LAST_USER_TOKENS[INDEX] < VOCABULARY_SIZE
			)
				PENALTIES[ENGINE->LAST_USER_TOKENS[INDEX]] = 0;
	}

	int		GENERATED_COUNT = 0;
	int		SPELLED_RUN = 0;
	int		PUNCTUATION_RUN = 0;
	int32_t	*TOKEN_BUFFER;

	RUN_PREFIX(ENGINE, SEQUENCE, SEQUENCE_LENGTH);

	float	TEMPERATURE;

	if (GENERATION_MODE == 1)
		TEMPERATURE = ENGINE->TEMPERATURE * (float)0.5;
	else
		TEMPERATURE = ENGINE->TEMPERATURE;

	while (GENERATED_COUNT < OUTPUT_CAPACITY && SEQUENCE_LENGTH < MAX_POSITIONS)
	{
		int		LAST_POSITION = SEQUENCE_LENGTH - 1;
		float	MAX_LOGIT = -(float)1e30;
		int32_t	PREVIOUS_TOKEN;

		if (GENERATED_COUNT)
			PREVIOUS_TOKEN = OUTPUT_TOKENS[GENERATED_COUNT - 1];
		else
			PREVIOUS_TOKEN = SEQUENCE[SEQUENCE_LENGTH - 1];

		char	MATH_WORDS[80][24];
		int		MATH_WORD_COUNT = 0;
		int		MATH_TAIL = 0;
		int		MATH_ENDS_DIGIT = 0;
		int		PLAIN_TOKEN_ALLOWED = 1;

		if (MATH_STATE.EXPRESSION_COUNT)
		{
			char	MATH_DRAFT[1024];

			DECODE_TOKENS(
				LEXICON, OUTPUT_START, GENERATED_COUNT, MATH_DRAFT,
				sizeof MATH_DRAFT, NULL, 0
			);

			size_t	MATH_DRAFT_LENGTH = strlen(MATH_DRAFT);

			MATH_ENDS_DIGIT = MATH_DRAFT_LENGTH > 0 &&
				isdigit((uint8_t)MATH_DRAFT[MATH_DRAFT_LENGTH - 1]);
			MATH_WORD_COUNT = SPLIT_MATH_WORDS(MATH_DRAFT, MATH_WORDS, 80);
			MATH_TAIL = MATH_TAIL_START(MATH_WORDS, MATH_WORD_COUNT);
			PLAIN_TOKEN_ALLOWED = MATH_CONTEXT_ALLOWS(
				&MATH_STATE, MATH_WORDS, MATH_WORD_COUNT, MATH_TAIL,
				MATH_ENDS_DIGIT, 0, ""
			);
		}

		int	TOKEN_ID;

		for (TOKEN_ID = 0; TOKEN_ID < VOCABULARY_SIZE; TOKEN_ID++)
		{
			if (MATH_STATE.EXPRESSION_COUNT)
			{
				char	MATH_SPELLING[24];
				int		MATH_KIND =
					MATH_TOKEN_CACHED(ENGINE, TOKEN_ID, MATH_SPELLING);

				if (
					MATH_KIND ? !MATH_CONTEXT_ALLOWS(
									&MATH_STATE, MATH_WORDS, MATH_WORD_COUNT,
									MATH_TAIL, MATH_ENDS_DIGIT, MATH_KIND,
									MATH_SPELLING
								)
					: !PLAIN_TOKEN_ALLOWED
				)
				{
					PROBABILITIES[TOKEN_ID] = -(float)1e30;
					continue ;
				}
			}

			float	LOGIT = WEB_LAST_LOGITS(NEURAL_WEB)[TOKEN_ID];

			if (
				!IS_VALID_TOKEN(
					ENGINE, PREVIOUS_TOKEN, TOKEN_ID, SPELLED_RUN,
					GENERATED_COUNT, GENERATION_MODE
				) ||
				(
					USE_COPY &&
					!COPY_ALLOWS_TOKEN(ENGINE, &COPY_STATE, TOKEN_ID)
				) ||
				(
					USE_GROUNDING &&
					!COPY_ALLOWS_TOKEN(ENGINE, &GROUND_COPY, TOKEN_ID)
				)
			)
			{
				PROBABILITIES[TOKEN_ID] = -(float)1e30;
				continue ;
			}

			if (
				USE_COPY &&
				COPY_STATE.MATH_SPAN_COUNT &&
				GENERATED_COUNT >= 1 &&
				(
					OUTPUT_START[0] == COPY_STATE.TOKEN_CALC ||
					OUTPUT_START[0] == COPY_STATE.TOKEN_CALCULATE
				) &&
				!MATH_SPAN_ALLOWS(
					&COPY_STATE, OUTPUT_START + 1, GENERATED_COUNT - 1,
					TOKEN_ID, ENGINE->TOKEN_RESULT
				)
			)
			{
				PROBABILITIES[TOKEN_ID] = -(float)1e30;
				continue ;
			}

			LOGIT = LOGIT / TEMPERATURE;
			PROBABILITIES[TOKEN_ID] = LOGIT;

			if (LOGIT > MAX_LOGIT)
				MAX_LOGIT = LOGIT;
		}

		double	PROBABILITY_SUM = 0;
		double	RAW_SUM = 0;
		int		CANDIDATE_COUNT = 0;
		float	*LOGITS = WEB_LAST_LOGITS(NEURAL_WEB);
		float	RAW_MAX_LOGIT = MAX_LOGIT * TEMPERATURE;

		for (TOKEN_ID = 0; TOKEN_ID < VOCABULARY_SIZE; TOKEN_ID++)
			if (PROBABILITIES[TOKEN_ID] > -(float)1e29)
			{
				PROBABILITIES[TOKEN_ID] =
					expf(PROBABILITIES[TOKEN_ID] - MAX_LOGIT);
				PROBABILITY_SUM += PROBABILITIES[TOKEN_ID];
				RAW_PROBABILITIES[TOKEN_ID] =
					expf(LOGITS[TOKEN_ID] - RAW_MAX_LOGIT);
				RAW_SUM += RAW_PROBABILITIES[TOKEN_ID];
				CANDIDATES[CANDIDATE_COUNT++] = TOKEN_ID;
			}

		int	INDEX;

		for (INDEX = 0; INDEX < CANDIDATE_COUNT; INDEX++)
		{
			PROBABILITIES[CANDIDATES[INDEX]] /= (float)PROBABILITY_SUM;
			RAW_PROBABILITIES[CANDIDATES[INDEX]] /= (float)RAW_SUM;
		}

		if (NEURAL_WEB->COPY_ID >= 0)
		{
			int64_t	COPY_OFFSETS[10];

			COPY_HEAD_OFFSETS(NEURAL_WEB, COPY_OFFSETS);

			float	COPY_GATE = ((float *)(NEURAL_WEB->ACTIVATIONS +
				COPY_OFFSETS[3]))[LAST_POSITION];
			float	*ATTENTION_ROW = WEB_COPY_ATTENTION_ROW(
				NEURAL_WEB, NEURAL_WEB->ACTIVATIONS, LAST_POSITION
			);
			int32_t	*CONTEXT_TOKENS = (int32_t *)(NEURAL_WEB->ACTIVATIONS +
				NEURAL_WEB->TOKENS_OFFSET);
			int		INDEX;

			for (INDEX = 0; INDEX < CANDIDATE_COUNT; INDEX++)
			{
				PROBABILITIES[CANDIDATES[INDEX]] *= 1 - COPY_GATE;
				RAW_PROBABILITIES[CANDIDATES[INDEX]] *= 1 - COPY_GATE;
			}

			int	SOURCE_POSITION;

			for (
				SOURCE_POSITION = 0;
				SOURCE_POSITION <= LAST_POSITION;
				SOURCE_POSITION++
			)
				if (
					CONTEXT_TOKENS[SOURCE_POSITION] >= 0 &&
					CONTEXT_TOKENS[SOURCE_POSITION] < VOCABULARY_SIZE &&
					PROBABILITIES[CONTEXT_TOKENS[SOURCE_POSITION]] >
						-(float)1e29
				)
				{
					PROBABILITIES[CONTEXT_TOKENS[SOURCE_POSITION]] +=
						COPY_GATE * ATTENTION_ROW[SOURCE_POSITION];
					RAW_PROBABILITIES[CONTEXT_TOKENS[SOURCE_POSITION]] +=
						COPY_GATE * ATTENTION_ROW[SOURCE_POSITION];
				}
		}

		if (
			GENERATION_MODE == 0 &&
			ENGINE->NEIGHBORS_ON &&
			ENGINE->NEIGHBOR_INDEX.COUNT
		)
		{
			float	HIDDEN_STATE[2048];
			float	SIMILARITIES[8];
			int32_t	NEIGHBOR_TOKEN_IDS[8];

			WEB_HIDDEN_STATE(NEURAL_WEB, LAST_POSITION, HIDDEN_STATE);

			int	NEIGHBOR_COUNT = NEAREST_NEIGHBOR_QUERY(
				&ENGINE->NEIGHBOR_INDEX, HIDDEN_STATE, 8, NEIGHBOR_TOKEN_IDS,
				SIMILARITIES
			);

			if (NEIGHBOR_COUNT && SIMILARITIES[0] > ENGINE->NEIGHBOR_THRESHOLD)
			{
				float	NEIGHBOR_WEIGHT = ENGINE->NEIGHBOR_MIX *
					(SIMILARITIES[0] - ENGINE->NEIGHBOR_THRESHOLD) /
					((float)0.95 - ENGINE->NEIGHBOR_THRESHOLD);

				if (NEIGHBOR_WEIGHT > ENGINE->NEIGHBOR_MIX)
					NEIGHBOR_WEIGHT = ENGINE->NEIGHBOR_MIX;

				double	NEIGHBOR_NORMALIZER = 0;
				int		INNER_INDEX;

				for (
					INNER_INDEX = 0;
					INNER_INDEX < NEIGHBOR_COUNT;
					INNER_INDEX++
				)
					if (
						SIMILARITIES[INNER_INDEX] >
							ENGINE->NEIGHBOR_THRESHOLD &&
						NEIGHBOR_TOKEN_IDS[INNER_INDEX] < VOCABULARY_SIZE &&
						PROBABILITIES[NEIGHBOR_TOKEN_IDS[INNER_INDEX]] >
							-(float)1e29
					)
						NEIGHBOR_NORMALIZER += expf(
							(float)20.0 *
							(SIMILARITIES[INNER_INDEX] - SIMILARITIES[0])
						);

				if (NEIGHBOR_NORMALIZER > 0)
				{
					int	INDEX;

					for (INDEX = 0; INDEX < CANDIDATE_COUNT; INDEX++)
						PROBABILITIES[CANDIDATES[INDEX]] *= 1 - NEIGHBOR_WEIGHT;

					int	INNER_INDEX;

					for (
						INNER_INDEX = 0;
						INNER_INDEX < NEIGHBOR_COUNT;
						INNER_INDEX++
					)
						if (
							SIMILARITIES[INNER_INDEX] >
								ENGINE->NEIGHBOR_THRESHOLD &&
							NEIGHBOR_TOKEN_IDS[INNER_INDEX] < VOCABULARY_SIZE &&
							PROBABILITIES[NEIGHBOR_TOKEN_IDS[INNER_INDEX]] >
								-(float)1e29
						)
							PROBABILITIES[NEIGHBOR_TOKEN_IDS[INNER_INDEX]] +=
								(float)(NEIGHBOR_WEIGHT *
										expf(
											(float)20.0 *
											(SIMILARITIES[INNER_INDEX] -
												SIMILARITIES[0])
										) /
										NEIGHBOR_NORMALIZER);

					ENGINE->NEIGHBOR_USE_COUNT++;
				}
			}
		}

		PROBABILITY_SUM = 0;

		for (INDEX = 0; INDEX < CANDIDATE_COUNT; INDEX++)
		{
			int32_t	TOKEN_ID = CANDIDATES[INDEX];
			float	PENALTY_FACTOR = expf(-PENALTIES[TOKEN_ID]);

			if (GENERATION_MODE == 0 && IS_PUNCTUATION_TOKEN(ENGINE, TOKEN_ID))
			{
				if (
					PUNCTUATION_RUN >= 2 ||
					(GENERATED_COUNT && TOKEN_ID == PREVIOUS_TOKEN)
				)
					PENALTY_FACTOR = 0;
				else if (PUNCTUATION_RUN == 1)
					PENALTY_FACTOR *= (float)0.35;
			}

			PROBABILITIES[TOKEN_ID] *= PENALTY_FACTOR;
			PROBABILITY_SUM += PROBABILITIES[TOKEN_ID];
		}

		if (PROBABILITY_SUM <= 0)
			break ;

		for (INDEX = 0; INDEX < CANDIDATE_COUNT; INDEX++)
			PROBABILITIES[CANDIDATES[INDEX]] /= (float)PROBABILITY_SUM;

		SORT_PROBABILITIES = PROBABILITIES;

		float	PEAK_PROBABILITY = 0;

		for (INDEX = 0; INDEX < CANDIDATE_COUNT; INDEX++)
			if (PROBABILITIES[CANDIDATES[INDEX]] > PEAK_PROBABILITY)
				PEAK_PROBABILITY = PROBABILITIES[CANDIDATES[INDEX]];

		int		KEPT_COUNT = 0;
		double	KEPT_MASS = 0;

		for (INDEX = 0; INDEX < CANDIDATE_COUNT; INDEX++)
			if (
				PROBABILITIES[CANDIDATES[INDEX]] >=
					PEAK_PROBABILITY *(float)1e-4
			)
			{
				int32_t	SWAP_TOKEN = CANDIDATES[KEPT_COUNT];

				CANDIDATES[KEPT_COUNT] = CANDIDATES[INDEX];
				CANDIDATES[INDEX] = SWAP_TOKEN;
				KEPT_MASS += PROBABILITIES[CANDIDATES[KEPT_COUNT]];
				KEPT_COUNT++;
			}

		if (KEPT_MASS < ENGINE->TOP_PROBABILITY)
			KEPT_COUNT = CANDIDATE_COUNT;

		qsort(CANDIDATES, KEPT_COUNT, sizeof(int32_t), BY_PROBABILITY);

		double	CUMULATIVE_MASS = 0;
		double	NUCLEUS_MASS = 0;
		int		NUCLEUS_SIZE = 0;

		while (
			NUCLEUS_SIZE < KEPT_COUNT &&
			CUMULATIVE_MASS < ENGINE->TOP_PROBABILITY
		)
		{
			CUMULATIVE_MASS += PROBABILITIES[CANDIDATES[NUCLEUS_SIZE]];
			NUCLEUS_SIZE++;
		}

		if (NUCLEUS_SIZE < 1)
			NUCLEUS_SIZE = 1;

		for (INDEX = 0; INDEX < NUCLEUS_SIZE; INDEX++)
			NUCLEUS_MASS += PROBABILITIES[CANDIDATES[INDEX]];

		double	RANDOM_DRAW =
			(double)(RANDOM_NEXT(&ENGINE->RANDOM_STATE) >> 11) /
			9007199254740992.0 * NUCLEUS_MASS;
		int32_t	PICKED_TOKEN = CANDIDATES[NUCLEUS_SIZE - 1];

		for (INDEX = 0; INDEX < NUCLEUS_SIZE; INDEX++)
		{
			RANDOM_DRAW -= PROBABILITIES[CANDIDATES[INDEX]];

			if (RANDOM_DRAW <= 0)
			{
				PICKED_TOKEN = CANDIDATES[INDEX];
				break ;
			}
		}

		{
			double	TOKEN_LOG =
				log(RAW_PROBABILITIES[PICKED_TOKEN] > (float)1e-30
						? RAW_PROBABILITIES[PICKED_TOKEN]
						: (float)1e-30);

			LOG_PROBABILITY += TOKEN_LOG;

			if (TOKEN_LOG < ENGINE->DRAFT_LOWEST)
				ENGINE->DRAFT_LOWEST = TOKEN_LOG;
		}

		if (
			PICKED_TOKEN == TOKEN_USER_TURN ||
			PICKED_TOKEN == ENGINE->TOKEN_RESULT
		)
		{
			STOPPED = 1;
			break ;
		}

		if (
			PICKED_TOKEN >= TOKEN_FIRST_CHARACTER + CHARACTER_COUNT &&
			PICKED_TOKEN < TOKEN_FIRST_WORD
		)
			SPELLED_RUN++;
		else if (
			PICKED_TOKEN >= TOKEN_FIRST_CHARACTER &&
			PICKED_TOKEN < TOKEN_FIRST_CHARACTER + CHARACTER_COUNT
		)
			SPELLED_RUN = 1;
		else
			SPELLED_RUN = 0;

		if (IS_PUNCTUATION_TOKEN(ENGINE, PICKED_TOKEN))
			PUNCTUATION_RUN = PUNCTUATION_RUN + 1;
		else
			PUNCTUATION_RUN = 0;

		if (USE_COPY)
			COPY_PUSH_TOKEN(&COPY_STATE, PICKED_TOKEN);

		if (USE_GROUNDING)
			COPY_PUSH_TOKEN(&GROUND_COPY, PICKED_TOKEN);

		if (
			GENERATION_MODE == 0 &&
			PICKED_TOKEN >= TOKEN_FIRST_WORD &&
			IS_CONTENT_WORD(ENGINE, LEXICON->TOKEN_TO_LEXEME[PICKED_TOKEN])
		)
			PENALTIES[PICKED_TOKEN] += (float)0.5;

		OUTPUT_TOKENS[GENERATED_COUNT++] = PICKED_TOKEN;
		TOKEN_BUFFER =
			(int32_t *)(NEURAL_WEB->ACTIVATIONS + NEURAL_WEB->TOKENS_OFFSET);
		TOKEN_BUFFER[SEQUENCE_LENGTH] = PICKED_TOKEN;
		SEQUENCE[SEQUENCE_LENGTH++] = PICKED_TOKEN;
		NEURAL_WEB->KERNEL_STATE->START_POSITION = SEQUENCE_LENGTH - 1;
		NEURAL_WEB->KERNEL_STATE->SEQUENCE_LENGTH = SEQUENCE_LENGTH;
		WEB_RUN(NEURAL_WEB, MODE_INFER);
		ENGINE->PREFIX_CACHE_VALID = SEQUENCE_LENGTH;
	}

	free(PROBABILITIES);
	free(CANDIDATES);
	free(PENALTIES);
	free(RAW_PROBABILITIES);

	if (USE_COPY)
	{
		free(COPY_STATE.IN_CONTEXT);
		free(COPY_STATE.SPELLED_WORDS);
		free(COPY_STATE.IN_USER_TURN);
		free(COPY_STATE.USER_SPELLED_WORDS);
	}

	if (USE_GROUNDING)
	{
		free(GROUND_COPY.IN_CONTEXT);
		free(GROUND_COPY.SPELLED_WORDS);
		free(GROUND_COPY.IN_USER_TURN);
		free(GROUND_COPY.USER_SPELLED_WORDS);
	}

	if (!STOPPED)
		LOG_PROBABILITY += log(1e-3);

	if (RESULT_SCORE)
		*RESULT_SCORE = LOG_PROBABILITY / pow(GENERATED_COUNT + 1, 0.7);

	ENGINE->DRAFT_MEAN = LOG_PROBABILITY / (GENERATED_COUNT + 1);

	return (GENERATED_COUNT);
}

static void
	LOG_MIND(
		ENGINE_STATE *ENGINE, const char *FORMAT_STRING,
		const char *FORMAT_ARGUMENT
	)
{
	char		LOG_LINE[240];
	time_t		CURRENT_TIME = time(NULL);
	struct tm	*LOCAL_TIME = localtime(&CURRENT_TIME);
	int			STAMP_LENGTH =
		(int)strftime(LOG_LINE, sizeof LOG_LINE, "%H:%M:%S ", LOCAL_TIME);

	snprintf(
		LOG_LINE + STAMP_LENGTH, sizeof LOG_LINE - STAMP_LENGTH, FORMAT_STRING,
		FORMAT_ARGUMENT ? FORMAT_ARGUMENT : ""
	);

	if (ENGINE->MIND_LOG_COUNT == 24)
	{
		memmove(
			ENGINE->MIND_LOG[0], ENGINE->MIND_LOG[1],
			23 * sizeof ENGINE->MIND_LOG[0]
		);
		ENGINE->MIND_LOG_COUNT = 23;
	}

	snprintf(
		ENGINE->MIND_LOG[ENGINE->MIND_LOG_COUNT++], sizeof ENGINE->MIND_LOG[0],
		"%s", LOG_LINE
	);
}

static double
	SEQUENCE_LOG_PROBABILITY(
		ENGINE_STATE *ENGINE, int32_t *PREFIX_TOKENS, int PREFIX_LENGTH,
		const int32_t *TOKENS, int TOKEN_COUNT
	)
{
	WEB		*NEURAL_WEB = ENGINE->LOADED_BRAIN.NEURAL_WEB;
	int		VOCABULARY_SIZE = NEURAL_WEB->WORD_COUNT;
	int		SEQUENCE_LENGTH = PREFIX_LENGTH;
	double	LOG_PROBABILITY = 0;

	RUN_PREFIX(ENGINE, PREFIX_TOKENS, SEQUENCE_LENGTH);

	int	TOKEN_INDEX;

	for (
		TOKEN_INDEX = 0;
		TOKEN_INDEX <= TOKEN_COUNT &&SEQUENCE_LENGTH <
			NEURAL_WEB->CONFIGURATION.MAXIMUM_LENGTH;
		TOKEN_INDEX++
	)
	{
		int32_t	WANTED_TOKEN;

		if (TOKEN_INDEX < TOKEN_COUNT)
			WANTED_TOKEN = TOKENS[TOKEN_INDEX];
		else
			WANTED_TOKEN = TOKEN_USER_TURN;

		float	*LOGITS = WEB_LAST_LOGITS(NEURAL_WEB);
		double	MAX_LOGIT = -1e30;
		double	EXPONENT_SUM = 0;
		int		VOCABULARY_INDEX;

		for (
			VOCABULARY_INDEX = 0;
			VOCABULARY_INDEX < VOCABULARY_SIZE;
			VOCABULARY_INDEX++
		)
			if (LOGITS[VOCABULARY_INDEX] > MAX_LOGIT)
				MAX_LOGIT = LOGITS[VOCABULARY_INDEX];

		for (
			VOCABULARY_INDEX = 0;
			VOCABULARY_INDEX < VOCABULARY_SIZE;
			VOCABULARY_INDEX++
		)
			EXPONENT_SUM += exp(LOGITS[VOCABULARY_INDEX] - MAX_LOGIT);

		double	TOKEN_PROBABILITY =
			exp(LOGITS[WANTED_TOKEN] - MAX_LOGIT) / EXPONENT_SUM;

		if (NEURAL_WEB->COPY_ID >= 0)
		{
			int64_t	COPY_OFFSETS[10];

			COPY_HEAD_OFFSETS(NEURAL_WEB, COPY_OFFSETS);

			double	COPY_GATE =
				((float *)(NEURAL_WEB->ACTIVATIONS + COPY_OFFSETS[3])
				)[SEQUENCE_LENGTH - 1];
			double	COPY_MASS = 0;
			float	*ATTENTION_ROW = WEB_COPY_ATTENTION_ROW(
				NEURAL_WEB, NEURAL_WEB->ACTIVATIONS, SEQUENCE_LENGTH - 1
			);
			int32_t	*CONTEXT_TOKENS = (int32_t *)(NEURAL_WEB->ACTIVATIONS +
				NEURAL_WEB->TOKENS_OFFSET);
			int		SOURCE_POSITION;

			for (
				SOURCE_POSITION = 0;
				SOURCE_POSITION < SEQUENCE_LENGTH;
				SOURCE_POSITION++
			)
				if (CONTEXT_TOKENS[SOURCE_POSITION] == WANTED_TOKEN)
					COPY_MASS += ATTENTION_ROW[SOURCE_POSITION];

			TOKEN_PROBABILITY =
				(1 - COPY_GATE) * TOKEN_PROBABILITY + COPY_GATE * COPY_MASS;
		}

		LOG_PROBABILITY +=
			log(TOKEN_PROBABILITY > 1e-30 ? TOKEN_PROBABILITY : 1e-30);

		if (TOKEN_INDEX == TOKEN_COUNT)
			break ;

		int32_t	*TOKEN_BUFFER =
			(int32_t *)(NEURAL_WEB->ACTIVATIONS + NEURAL_WEB->TOKENS_OFFSET);

		TOKEN_BUFFER[SEQUENCE_LENGTH] = WANTED_TOKEN;
		PREFIX_TOKENS[SEQUENCE_LENGTH++] = WANTED_TOKEN;
		NEURAL_WEB->KERNEL_STATE->START_POSITION = SEQUENCE_LENGTH - 1;
		NEURAL_WEB->KERNEL_STATE->SEQUENCE_LENGTH = SEQUENCE_LENGTH;
		WEB_RUN(NEURAL_WEB, MODE_INFER);
		ENGINE->PREFIX_CACHE_VALID = SEQUENCE_LENGTH;
	}

	return (LOG_PROBABILITY / pow(TOKEN_COUNT + 1, 0.7));
}

static int
	ENDS_WITH_QUESTION(const char *INPUT_STRING)
{
	size_t	STRING_LENGTH = strlen(INPUT_STRING);

	while (
		STRING_LENGTH &&
		(
			INPUT_STRING[STRING_LENGTH - 1] == ' ' ||
			INPUT_STRING[STRING_LENGTH - 1] == '"'
		)
	)
		STRING_LENGTH--;

	return (STRING_LENGTH && INPUT_STRING[STRING_LENGTH - 1] == '?');
}

static int
	DID_ACTION(ENGINE_STATE *ENGINE, const char *ALLOWED_VERBS)
{
	int	ACTION_INDEX;

	for (ACTION_INDEX = 0; ACTION_INDEX < ENGINE->ACTION_COUNT; ACTION_INDEX++)
	{
		char	ACTION_VERB[32];
		int		VERB_LENGTH = 0;

		while (
			ENGINE->ACTION_LOG[ACTION_INDEX][VERB_LENGTH] &&
			ENGINE->ACTION_LOG[ACTION_INDEX][VERB_LENGTH] != ' ' &&
			VERB_LENGTH < 31
		)
		{
			ACTION_VERB[VERB_LENGTH] = (char
			)tolower((uint8_t)ENGINE->ACTION_LOG[ACTION_INDEX][VERB_LENGTH]);
			VERB_LENGTH++;
		}

		ACTION_VERB[VERB_LENGTH] = 0;

		const char	*ACTION_RESULT = ENGINE->ACTION_RESULTS[ACTION_INDEX];
		int			ACTION_FAILED =
			!*ACTION_RESULT || strstr(ACTION_RESULT, "error") ||
				strstr(ACTION_RESULT, "no such") ||
				strstr(ACTION_RESULT, "unknown") ||
				strstr(ACTION_RESULT, "not allowed") ||
				strstr(ACTION_RESULT, "bad name") ||
				strstr(ACTION_RESULT, "cannot") ||
				strstr(ACTION_RESULT, "exists") ||
				strstr(ACTION_RESULT, "nothing");

		if (ACTION_FAILED)
			continue ;

		char	VERB_PATTERN[40];

		snprintf(VERB_PATTERN, sizeof VERB_PATTERN, " %s ", ACTION_VERB);

		char	PADDED_VERBS[128];

		snprintf(PADDED_VERBS, sizeof PADDED_VERBS, " %s ", ALLOWED_VERBS);

		if (strstr(PADDED_VERBS, VERB_PATTERN))
			return (1);
	}

	return (0);
}

/* "count words in the quick brown fox -> 5" is not said as "It has 5
 * letters": a number in the reply is counted in what was counted */
static int
	COUNT_UNITS_MATCH(ENGINE_STATE *ENGINE, const char *PADDED_REPLY)
{
	static const char	*UNITS[15] = {
		"letter", "letters", "character", "characters", "word", "words",
		"vowel", "vowels", "consonant", "consonants", "sentence", "sentences",
		"line", "lines", NULL
	};
	int					ENTRY_INDEX;

	for (ENTRY_INDEX = 0; ENTRY_INDEX < ENGINE->ACTION_COUNT; ENTRY_INDEX++)
	{
		const char	*ACTION = ENGINE->ACTION_LOG[ENTRY_INDEX];
		char		COUNTED[24] = "";
		const char	*CURSOR;

		if (strncmp(ACTION, "count ", 6))
			continue ;

		sscanf(ACTION + 6, "%23s", COUNTED);

		/* "count r in strawberry": a letter, said as "3 r's" */
		int	ONE_LETTER = strlen(COUNTED) == 1;

		for (CURSOR = PADDED_REPLY; *CURSOR; CURSOR++)
		{
			char	UNIT[24];
			int		INDEX;
			int		FOUND = 0;

			if (
				!isdigit((uint8_t)*CURSOR) ||
				(CURSOR > PADDED_REPLY && !isspace((uint8_t)CURSOR[-1]))
			)
				continue ;

			while (isdigit((uint8_t)*CURSOR))
				CURSOR++;

			if (*CURSOR != ' ' || sscanf(CURSOR, " %23s", UNIT) != 1)
				continue ;

			for (INDEX = 0; UNITS[INDEX]; INDEX++)
				if (!strcmp(UNIT, UNITS[INDEX]))
					FOUND = 1;

			if (!FOUND)
				continue ;

			/* "letters" for letters, "words" for words; a counted letter is
			 * never said as letters or words */
			if (ONE_LETTER)
				return (0);

			if (
				strncmp(
					UNIT, COUNTED,
					strlen(UNIT) - (UNIT[strlen(UNIT) - 1] == 's' ? 1 : 0)
				)
			)
				return (0);
		}
	}

	return (1);
}

static int
	CLAIMS_MATCH_ACTIONS(ENGINE_STATE *ENGINE, const char *REPLY_TEXT)
{
	char	NORMALIZED[1024];

	REFLEX_NORMALIZE(REPLY_TEXT, NORMALIZED, sizeof NORMALIZED);

	static const struct
	{
		const char	*CLAIM;
		const char	*VERBS;
	} CLAIM_RULES[27] = {
		{ "i forgot", "forget" }, { "forgotten", "forget" },
		{ "i removed", "forget delete" },
		{ "i saved", "remember write append export" },
		{ "i will remember", "remember" }, { "ill remember", "remember" },
		{ "i remembered", "remember" }, { "i created", "write mkdir" },
		{ "i made", "write mkdir" }, { "i wrote", "write append" },
		{ "folder is ready", "mkdir" }, { "moved", "move delete" },
		{ "renamed", "rename" }, { "its called", "rename" },
		{ "deleted", "delete forget" }, { "trash", "delete" },
		{ "i added", "append remember" }, { "added it", "append" },
		{ "i updated", "forget remember" },
		{ "i changed it", "forget remember" },
		{ "saved it", "remember write append" },
		{ "here they are", "files memories formulas topics topic" },
		{ "here it is", "read files recall lookup topic" },
		{ "it says", "read lookup" }, { "today is", "date" },
		{ "the date is", "date" }, { "the time is", "time" },
	};
	size_t	RULE_INDEX;

	for (
		RULE_INDEX = 0;
		RULE_INDEX < sizeof CLAIM_RULES / sizeof CLAIM_RULES[0];
		RULE_INDEX++
	)
		if (
			strstr(NORMALIZED, CLAIM_RULES[RULE_INDEX].CLAIM) &&
			!DID_ACTION(ENGINE, CLAIM_RULES[RULE_INDEX].VERBS)
		)
			return (0);

	{
		/* "it's done", "all set": a finished task needs an action this turn; "I
		 * sent it", "I booked it": texts, calls, bookings and orders never
		 * happen here */
		static const char	*DONE_PHRASES[21] = {
			"its done", "all done", "all set", "its ready", "its all ready",
			"done it", "i did it", "i finished", "i have done", "ive done",
			"i took care", "taken care of", "consider it done", "i set",
			"i searched", "i looked it up", "i checked", "i fixed",
			"i did that", "i did what", NULL
		};
		static const char	*NEVER_PHRASES[30] = {
			"i sent", "sent it", "i booked", "i ordered", "i called",
			"i texted", "i emailed", "i messaged", "i turned off",
			"i turned on", "i turned the", "i turned your", "i reminded",
			"i bought", "i paid", "i printed", "i posted", "i uploaded",
			"i googled", "i checked online", "i rang", "i phoned", "i mailed",
			"i delivered", "i dialed", "i locked", "i unlocked", "i cancelled",
			"i canceled", NULL
		};
		static const char	*NEGATION_WORDS[15] = {
			"not", "no", "never", "cant", "cannot", "didnt", "dont", "wont",
			"havent", "hasnt", "couldnt", "unable", "nothing", "wasnt", NULL
		};
		int					ACTED_THIS_TURN = DID_ACTION(
			ENGINE,
			"write mkdir append remember forget move rename delete export "
			"formula goal calc count reverse random range recall memories "
			"files read topic topics lookup"
		);
		const char			*SENTENCE_START = REPLY_TEXT;

		while (*SENTENCE_START)
		{
			const char	*SENTENCE_END = SENTENCE_START;

			while (
				*SENTENCE_END &&
				*SENTENCE_END != '.' &&
				*SENTENCE_END != '!' &&
				*SENTENCE_END != '?'
			)
				SENTENCE_END++;

			char	SENTENCE[600];
			char	NORMALIZED_SENTENCE[620];
			char	PADDED_SENTENCE[640];

			snprintf(
				SENTENCE, sizeof SENTENCE, "%.*s",
				(int)(SENTENCE_END - SENTENCE_START), SENTENCE_START
			);
			REFLEX_NORMALIZE(
				SENTENCE, NORMALIZED_SENTENCE, sizeof NORMALIZED_SENTENCE
			);
			snprintf(
				PADDED_SENTENCE, sizeof PADDED_SENTENCE, " %s ",
				NORMALIZED_SENTENCE
			);

			int	NEGATED = 0;
			int	PHRASE_INDEX;

			for (PHRASE_INDEX = 0; NEGATION_WORDS[PHRASE_INDEX]; PHRASE_INDEX++)
			{
				char	NEGATION_PATTERN[24];

				snprintf(
					NEGATION_PATTERN, sizeof NEGATION_PATTERN, " %s ",
					NEGATION_WORDS[PHRASE_INDEX]
				);

				if (strstr(PADDED_SENTENCE, NEGATION_PATTERN))
					NEGATED = 1;
			}

			if (!NEGATED)
			{
				int	PHRASE_INDEX;

				for (
					PHRASE_INDEX = 0;
					NEVER_PHRASES[PHRASE_INDEX];
					PHRASE_INDEX++
				)
				{
					char	PHRASE_PATTERN[48];

					snprintf(
						PHRASE_PATTERN, sizeof PHRASE_PATTERN, " %s ",
						NEVER_PHRASES[PHRASE_INDEX]
					);

					if (strstr(PADDED_SENTENCE, PHRASE_PATTERN))
						return (0);
				}

				if (!ACTED_THIS_TURN)
				{
					int	PHRASE_INDEX;

					for (
						PHRASE_INDEX = 0;
						DONE_PHRASES[PHRASE_INDEX];
						PHRASE_INDEX++
					)
					{
						char	PHRASE_PATTERN[48];

						snprintf(
							PHRASE_PATTERN, sizeof PHRASE_PATTERN, " %s ",
							DONE_PHRASES[PHRASE_INDEX]
						);

						if (strstr(PADDED_SENTENCE, PHRASE_PATTERN))
							return (0);
					}
				}
			}

			if (*SENTENCE_END)
				SENTENCE_START = SENTENCE_END + 1;
			else
				SENTENCE_START = SENTENCE_END;
		}
	}

	char	PADDED_REPLY[1030];

	snprintf(PADDED_REPLY, sizeof PADDED_REPLY, " %s ", NORMALIZED);

	char	*SAVED_POSITION = strstr(PADDED_REPLY, " saved ");

	if (
		SAVED_POSITION &&
		!DID_ACTION(ENGINE, "remember write append export formula")
	)
	{
		int					NEGATED = 0;
		static const char	*SAVED_NEGATIONS[10] = {
			" not ", " nothing ", " havent ", " haven't ", " hasnt ", " never ",
			" no ", " didnt ", " wasnt ", NULL
		};
		int					PHRASE_INDEX;

		for (PHRASE_INDEX = 0; SAVED_NEGATIONS[PHRASE_INDEX]; PHRASE_INDEX++)
		{
			char	*NEGATION_POSITION =
				strstr(PADDED_REPLY, SAVED_NEGATIONS[PHRASE_INDEX]);

			if (NEGATION_POSITION && NEGATION_POSITION < SAVED_POSITION)
				NEGATED = 1;
		}

		if (!NEGATED)
			return (0);
	}

	if (!COUNT_UNITS_MATCH(ENGINE, PADDED_REPLY))
		return (0);

	return (1);
}

static void
	LOWERCASE_STRING(char *STRING_CURSOR)
{
	for (; *STRING_CURSOR; STRING_CURSOR++)
		*STRING_CURSOR = (char)tolower((uint8_t)*STRING_CURSOR);
}

static int
	USER_CLAIMS_MATCH(ENGINE_STATE *ENGINE, const char *REPLY_TEXT)
{
	if (!ENGINE->SENSE_ON)
		return (1);

	char	PADDED_REPLY[2048];

	snprintf(PADDED_REPLY, sizeof PADDED_REPLY, " %s ", REPLY_TEXT);
	LOWERCASE_STRING(PADDED_REPLY);

	static const char	*CLAIM_PHRASES[7] = {
		"you asked me", "you told me", "you said", "you wanted me",
		"you asked for", "as you asked", NULL
	};
	int					HAS_CLAIM = 0;
	int					INDEX;

	for (INDEX = 0; CLAIM_PHRASES[INDEX]; INDEX++)
		if (strstr(PADDED_REPLY, CLAIM_PHRASES[INDEX]))
			HAS_CLAIM = 1;

	if (!HAS_CLAIM)
		return (1);

	for (INDEX = 0; INDEX < ENGINE->ACTION_COUNT; INDEX++)
	{
		char	ACTION_LINE[64];

		snprintf(
			ACTION_LINE, sizeof ACTION_LINE, "%s", ENGINE->ACTION_LOG[INDEX]
		);
		LOWERCASE_STRING(ACTION_LINE);

		if (
			!strncmp(ACTION_LINE, "your", 4) ||
			!strncmp(ACTION_LINE, "you", 3) ||
			!strncmp(ACTION_LINE, "why", 3) ||
			!strncmp(ACTION_LINE, "goal", 4) ||
			!strncmp(ACTION_LINE, "my words when", 13) ||
			!strncmp(ACTION_LINE, "mistake", 7) ||
			!strncmp(ACTION_LINE, "remember", 8) ||
			!strncmp(ACTION_LINE, "recall", 6)
		)
			return (1);

		if (strchr(ACTION_LINE, ' ') && !strncmp(ACTION_LINE, "need", 4))
			return (1);
	}

	for (INDEX = 0; INDEX < ENGINE->ACTION_COUNT; INDEX++)
	{
		char	ACTION_VERB[32] = "";

		sscanf(ENGINE->ACTION_LOG[INDEX], "%31s", ACTION_VERB);
		LOWERCASE_STRING(ACTION_VERB);

		if (
			strcmp(ACTION_VERB, "my") &&
			strcmp(ACTION_VERB, "know") &&
			strcmp(ACTION_VERB, "can") &&
			strcmp(ACTION_VERB, "check") &&
			strcmp(ACTION_VERB, "find") &&
			strcmp(ACTION_VERB, "did")
		)
			return (1);
	}

	return (0);
}

static int
	CONTAINS_WHOLE_WORD(const char *HAYSTACK, const char *NEEDLE_WORD)
{
	size_t	NEEDLE_LENGTH = strlen(NEEDLE_WORD);

	if (!NEEDLE_LENGTH)
		return (0);

	const char	*MATCH;

	for (MATCH = HAYSTACK; (MATCH = strstr(MATCH, NEEDLE_WORD)); MATCH++)
		if (
			(MATCH == HAYSTACK || !isalnum((uint8_t)MATCH[-1])) &&
			!isalnum((uint8_t)MATCH[NEEDLE_LENGTH]) &&
			MATCH[NEEDLE_LENGTH] != '.'
		)
			return (1);

	return (0);
}

static int
	NAMES_ARE_KNOWN(ENGINE_STATE *ENGINE, const char *REPLY_TEXT)
{
	char	LOWER_REPLY[4096];
	char	KNOWN_TEXT[8192];

	snprintf(LOWER_REPLY, sizeof LOWER_REPLY, "%s", REPLY_TEXT);
	LOWERCASE_STRING(LOWER_REPLY);
	KNOWN_TEXT[0] = 0;

	int	INDEX;

	for (INDEX = 0; INDEX < ENGINE->ACTION_COUNT; INDEX++)
	{
		strncat(
			KNOWN_TEXT, ENGINE->ACTION_LOG[INDEX],
			sizeof KNOWN_TEXT - strlen(KNOWN_TEXT) - 2
		);
		strcat(KNOWN_TEXT, " ");
		strncat(
			KNOWN_TEXT, ENGINE->ACTION_RESULTS[INDEX],
			sizeof KNOWN_TEXT - strlen(KNOWN_TEXT) - 2
		);
		strcat(KNOWN_TEXT, " ");
	}

	for (INDEX = 0; INDEX < ENGINE->USER_WINDOW_COUNT; INDEX++)
	{
		strncat(
			KNOWN_TEXT, ENGINE->USER_WINDOW[INDEX],
			sizeof KNOWN_TEXT - strlen(KNOWN_TEXT) - 2
		);
		strcat(KNOWN_TEXT, " ");
	}

	LOWERCASE_STRING(KNOWN_TEXT);

	char	*NAME_START;

	for (NAME_START = LOWER_REPLY; *NAME_START; NAME_START++)
	{
		if (
			!isalnum((uint8_t)*NAME_START) ||
			(
				NAME_START > LOWER_REPLY &&
				(
					isalnum((uint8_t)NAME_START[-1]) ||
					strchr("_-/.", NAME_START[-1])
				)
			)
		)
			continue ;

		char	*DOT_POSITION = NAME_START;

		while (isalnum((uint8_t)*DOT_POSITION) || strchr("_-", *DOT_POSITION))
			DOT_POSITION++;

		if (*DOT_POSITION != '.' || !isalpha((uint8_t)DOT_POSITION[1]))
			continue ;

		char	*EXTENSION_END = DOT_POSITION + 1;

		while (isalnum((uint8_t)*EXTENSION_END))
			EXTENSION_END++;

		if (
			EXTENSION_END - DOT_POSITION > 6 ||
			isalnum((uint8_t)*EXTENSION_END)
		)
			continue ;

		char	FILE_NAME[160];

		snprintf(
			FILE_NAME, sizeof FILE_NAME, "%.*s",
			(int)(EXTENSION_END - NAME_START), NAME_START
		);

		if (!strstr(KNOWN_TEXT, FILE_NAME))
			return (0);
	}

	return (1);
}

