/* the message is about Lucy: "you", "your", "yourself" */
static int
	TALKS_ABOUT_LUCY(ENGINE_STATE *ENGINE)
{
	const char	*TEXT = ENGINE->CURRENT_PART;
	char		PLAIN[1100];
	int			POSITION = 0;

	if (!TEXT)
		return (0);

	PLAIN[POSITION++] = ' ';

	for (; *TEXT && POSITION < 1097; TEXT++)
	{
		if (isalnum((uint8_t)*TEXT) || *TEXT == '\'')
			PLAIN[POSITION++] = (char)tolower((uint8_t)*TEXT);
		else if (PLAIN[POSITION - 1] != ' ')
			PLAIN[POSITION++] = ' ';
	}

	PLAIN[POSITION++] = ' ';
	PLAIN[POSITION] = 0;

	return (
		strstr(PLAIN, " you ") != NULL ||
		strstr(PLAIN, " your ") != NULL ||
		strstr(PLAIN, " yourself ") != NULL ||
		strstr(PLAIN, " you're ") != NULL ||
		strstr(PLAIN, " u ") != NULL ||
		strstr(PLAIN, " ur ") != NULL
	);
}

static void	SAVED_WORDS(ENGINE_STATE *ENGINE, char *OUTPUT, int OUTPUT_SIZE);

/* the message asks about what was saved: "do you remember what I like?",
 * "what did I say my name was?" */
static int
	ASKS_ABOUT_MEMORY(ENGINE_STATE *ENGINE)
{
	static const char	*CUES[12] = {
		" remember ", " told you ", " tell you ", " said ", " say ", " my ",
		" what do i ", " do i ", " did i ", " saved ", " memory ", NULL
	};
	char				PLAIN[1100];
	const char			*TEXT =
		ENGINE->CURRENT_PART ? ENGINE->CURRENT_PART : "";
	int					POSITION = 0;
	int					INDEX;

	PLAIN[POSITION++] = ' ';

	for (; *TEXT && POSITION < 1097; TEXT++)
	{
		if (isalnum((uint8_t)*TEXT) || *TEXT == '\'')
			PLAIN[POSITION++] = (char)tolower((uint8_t)*TEXT);
		else if (PLAIN[POSITION - 1] != ' ')
			PLAIN[POSITION++] = ' ';
	}

	PLAIN[POSITION++] = ' ';
	PLAIN[POSITION] = 0;

	for (INDEX = 0; CUES[INDEX]; INDEX++)
		if (strstr(PLAIN, CUES[INDEX]))
			return (1);

	/* "does Ava like cats?": a question about someone known */
	if (strchr(ENGINE->CURRENT_PART ? ENGINE->CURRENT_PART : "", '?'))
		for (INDEX = 0; INDEX < ENGINE->NAME_COUNT; INDEX++)
		{
			char	PADDED[80];

			snprintf(PADDED, sizeof PADDED, " %s ", ENGINE->NAMES[INDEX]);
			LOWERCASE_STRING(PADDED);

			if (strlen(PADDED) > 3 && strstr(PLAIN, PADDED))
				return (1);
		}

	/* "does Ava like cats?" with "Ava likes cats." known */
	if (strchr(ENGINE->CURRENT_PART ? ENGINE->CURRENT_PART : "", '?'))
	{
		const char	*READ = ENGINE->CURRENT_PART;
		static char	SAVED[16000];
		int			HAVE_SAVED = 0;

		for (; *READ; READ++)
			if (
				isupper((uint8_t)*READ) &&
				READ > ENGINE->CURRENT_PART &&
				READ[-1] == ' '
			)
			{
				char	WORD[64];
				int		LENGTH = 0;

				while (isalpha((uint8_t)READ[LENGTH]) && LENGTH < 62)
				{
					WORD[LENGTH] = (char)tolower((uint8_t)READ[LENGTH]);
					LENGTH++;
				}

				WORD[LENGTH] = 0;

				if (LENGTH < 2)
					continue ;

				if (!HAVE_SAVED)
				{
					SAVED_WORDS(ENGINE, SAVED, sizeof SAVED);
					HAVE_SAVED = 1;
				}

				char	PADDED[70];

				snprintf(PADDED, sizeof PADDED, " %s ", WORD);

				if (strstr(SAVED, PADDED))
					return (1);
			}
	}

	return (0);
}

