/* what is saved about the user and in this chat, said back: "You asked me to
 * remember that you have a cat named Mjolnir." */
static int
	SAY_MEMORIES_FROM(
		ENGINE_STATE *ENGINE, const char *WORDS, char *OUTPUT, int OUTPUT_SIZE,
		const char *JOIN, int INCLUDE_SAID, int LIMIT
	)
{
	MEMORY_FILE	*FILES[2] = { &ENGINE->PEOPLE, &ENGINE->FACTS };
	char		WANTED[700] = "";
	int			FOUND = 0;
	int			POSITION = 0;
	int			FILE_INDEX;

	OUTPUT[0] = 0;

	if (WORDS)
		PLAIN_LOWER_WORDS(WORDS, WANTED, sizeof WANTED);

	for (FILE_INDEX = 0; FILE_INDEX < 2; FILE_INDEX++)
	{
		MEMORY_FILE	*MEMORY = FILES[FILE_INDEX];
		int			RECORD;

		for (
			RECORD = MEMORY->COUNT - 1;
			RECORD >= 0 && FOUND < LIMIT && POSITION < OUTPUT_SIZE - 1;
			RECORD--
		)
		{
			char	LINE[1024];
			char	FLIPPED[1100];
			char	LINE_WORDS[1100];

			/* what people only mentioned in passing is kept with the turn
			 * number; what they asked to keep (or answered) with the time;
			 * asked about one thing, what was said counts too ("I have
			 * three apples." ... "How many apples do I have?") */
			if (
				MEMORY->RECORDS[RECORD].TIMESTAMP < (unsigned int)1000000000 &&
				!INCLUDE_SAID
			)
				continue ;

			/* passing mentions are about the user, from the people file */
			if (
				MEMORY->RECORDS[RECORD].TIMESTAMP < (unsigned int)1000000000 &&
				FILE_INDEX != 0
			)
				continue ;

			WORD_IDS_TO_TEXT(
				ENGINE, MEMORY->RECORDS[RECORD].IDS,
				(int)MEMORY->RECORDS[RECORD].ID_COUNT, LINE, sizeof LINE
			);

			/* something said in passing counts when it is a short fact about
			 * the user ("I have three apples."), not a long talk about it */
			if (MEMORY->RECORDS[RECORD].TIMESTAMP < (unsigned int)1000000000)
			{
				char		SAID[1100];
				int			SAID_WORDS = 0;
				const char	*SCAN;

				PLAIN_LOWER_WORDS(LINE, SAID, sizeof SAID);

				for (SCAN = SAID; *SCAN; SCAN++)
					if (SCAN[0] == ' ' && SCAN[1])
						SAID_WORDS++;

				if (
					SAID_WORDS > 14 ||
					strchr(LINE, '"') ||
					strstr(SAID, " you ") ||
					strstr(SAID, " think ") ||
					(
						strncmp(SAID, " i ", 3) &&
						strncmp(SAID, " my ", 4) &&
						strncmp(SAID, " i've ", 6) &&
						strncmp(SAID, " i'm ", 5)
					)
				)
					continue ;
			}

			/* only lines holding the asked word ("cat" in "cats") */
			if (WANTED[0])
			{
				char	*CURSOR = WANTED;
				int		HAS_ALL = 1;

				PLAIN_LOWER_WORDS(LINE, LINE_WORDS, sizeof LINE_WORDS);

				while (*CURSOR)
				{
					char	WORD[64];
					char	PATTERN[70];
					int		LENGTH = 0;

					while (*CURSOR == ' ')
						CURSOR++;

					while (
						CURSOR[LENGTH] &&
						CURSOR[LENGTH] != ' ' &&
						LENGTH < 63
					)
					{
						WORD[LENGTH] = CURSOR[LENGTH];
						LENGTH++;
					}

					WORD[LENGTH] = 0;
					CURSOR += LENGTH;

					if (!LENGTH)
						break ;

					if (LENGTH > 3 && WORD[LENGTH - 1] == 's')
						WORD[LENGTH - 1] = 0;

					snprintf(PATTERN, sizeof PATTERN, " %s", WORD);

					if (!strstr(LINE_WORDS, PATTERN))
						HAS_ALL = 0;
				}

				if (!HAS_ALL)
					continue ;
			}

			FLIP_PERSON(LINE, FLIPPED, sizeof FLIPPED);

			{
				int	LENGTH = (int)strlen(FLIPPED);

				while (LENGTH && strchr(".!", FLIPPED[LENGTH - 1]))
					FLIPPED[--LENGTH] = 0;
			}

			POSITION += snprintf(
				OUTPUT + POSITION, OUTPUT_SIZE - POSITION, "%s%s",
				FOUND ? JOIN : "", FLIPPED
			);
			FOUND++;
		}
	}

	return (FOUND);
}

static int
	SAY_MEMORIES(
		ENGINE_STATE *ENGINE, const char *WORDS, char *OUTPUT, int OUTPUT_SIZE,
		const char *JOIN
	)
{
	return (SAY_MEMORIES_FROM(ENGINE, WORDS, OUTPUT, OUTPUT_SIZE, JOIN, 0, 4));
}

