/* "where is it used?" about something taught: what is known about it, and
 * that this part is not known */
static int
	TAUGHT_PARTLY_KNOWN(
		ENGINE_STATE *ENGINE, const char *SENTENCE, char *OUTPUT,
		int OUTPUT_SIZE
	)
{
	static const char	*WH_WORDS[8] = {
		"where", "when", "who", "why", "how", "what", "which", NULL
	};
	static const char	*NOT_ABOUT_IT[12] = {
		"you", "your", "my", "i", "me", "file", "folder", "files", "time",
		"date", "day", NULL
	};
	static const char	*POINTING[8] = {
		"it", "they", "them", "that", "this", "those", "these", NULL
	};
	char				PLAIN[700];
	char				FIRST[32] = "";
	int					FACT_INDEX = -1;
	const char			*CURSOR;
	int					INDEX;

	/* words in quotes are only quoted: "Thanking a little bit" is not about
	 * bits */
	{
		char		UNQUOTED[700];
		int			POSITION = 0;
		int			IN_QUOTE = 0;
		const char	*READ;

		for (READ = SENTENCE; *READ && POSITION < 698; READ++)
		{
			if (*READ == '"')
			{
				IN_QUOTE = !IN_QUOTE;
				continue ;
			}

			if (!IN_QUOTE)
				UNQUOTED[POSITION++] = *READ;
		}

		UNQUOTED[POSITION] = 0;
		PLAIN_LOWER_WORDS(UNQUOTED, PLAIN, sizeof PLAIN);
	}

	sscanf(PLAIN, "%31s", FIRST);

	for (INDEX = 0; WH_WORDS[INDEX]; INDEX++)
		if (!strcmp(FIRST, WH_WORDS[INDEX]))
			break ;

	if (!WH_WORDS[INDEX] || HAS_ANY_WORD(PLAIN, NOT_ABOUT_IT))
		return (0);

	/* a word that was taught as a definition: "where is a bit used?" */
	for (CURSOR = PLAIN; *CURSOR && FACT_INDEX < 0;)
	{
		char	WORD[64];
		int		LENGTH = 0;

		while (*CURSOR == ' ')
			CURSOR++;

		while (CURSOR[LENGTH] && CURSOR[LENGTH] != ' ' && LENGTH < 63)
		{
			WORD[LENGTH] = CURSOR[LENGTH];
			LENGTH++;
		}

		WORD[LENGTH] = 0;
		CURSOR += LENGTH;

		if (LENGTH < 3)
			continue ;

		FACT_INDEX = TAUGHT_FIND_KEY(ENGINE->TAUGHT, WORD);

		if (FACT_INDEX < 0 && LENGTH > 3 && WORD[LENGTH - 1] == 's')
		{
			WORD[LENGTH - 1] = 0;
			FACT_INDEX = TAUGHT_FIND_KEY(ENGINE->TAUGHT, WORD);
		}
	}

	/* "where is it used?" right after a taught answer */
	if (
		FACT_INDEX < 0 &&
		HAS_ANY_WORD(PLAIN, POINTING) &&
		ENGINE->TAUGHT->LAST_USED >= 0 &&
		ENGINE->TAUGHT->LAST_USED < ENGINE->TAUGHT->COUNT &&
		ENGINE->TAUGHT_USED_SERIAL >= ENGINE->TAUGHT->SERIAL - 2
	)
		FACT_INDEX = ENGINE->TAUGHT->LAST_USED;

	if (
		FACT_INDEX < 0 ||
		ENGINE->TAUGHT->FACTS[FACT_INDEX].STATUS != TAUGHT_BELIEVED
	)
		return (0);

	{
		TAUGHT_FACT	*FACT = &ENGINE->TAUGHT->FACTS[FACT_INDEX];
		char		TEACHER[64];
		char		WHO[64];
		char		QUOTE[480];
		size_t		LENGTH;

		TAUGHT_TEACHER(ENGINE, TEACHER, sizeof TEACHER);

		if (!strcmp(FACT->TEACHER, TEACHER))
			snprintf(WHO, sizeof WHO, "you");
		else
			TAUGHT_WHO(FACT->TEACHER, WHO, sizeof WHO);

		snprintf(QUOTE, sizeof QUOTE, "%s", FACT->TEXT);
		LENGTH = strlen(QUOTE);

		while (LENGTH && strchr(".!; ", QUOTE[LENGTH - 1]))
			QUOTE[--LENGTH] = 0;

		if (isupper((uint8_t)QUOTE[0]) && !isupper((uint8_t)QUOTE[1]))
			QUOTE[0] = (char)tolower((uint8_t)QUOTE[0]);

		snprintf(
			OUTPUT, OUTPUT_SIZE,
			"I don't know that. All I know is what %s taught me: %s.", WHO,
			QUOTE
		);
		ENGINE->TAUGHT->LAST_USED = FACT_INDEX;
	}

	return (1);
}

/* ---- the last answer, for a "why?" or "are you sure?" right after ---- */

#define ANSWER_CALC 1
#define ANSWER_SKILL 2
#define ANSWER_KNOW 3
#define ANSWER_SOLVE 4
#define ANSWER_TOLD 5
#define ANSWER_CLOCK 6
#define ANSWER_COUNT 7
#define ANSWER_COMPARE 8

/* a sum read the way it is worked out, every step written down */
typedef struct
{
	const char	*AT;
	int			FAILED;
	char		STEPS[8][120];
	int			STEP_COUNT;
} STEP_READER;

static double	STEP_SUM(STEP_READER *READER);

static void
	STEP_NUMBER(double VALUE, char *OUTPUT, int OUTPUT_SIZE)
{
	if (fabs(VALUE) < 1e-12)
		VALUE = 0;

	if (fabs(VALUE - floor(VALUE + 0.5)) < 1e-9)
		snprintf(OUTPUT, (size_t)OUTPUT_SIZE, "%.0f", VALUE);
	else
	{
		int	LENGTH;

		snprintf(OUTPUT, (size_t)OUTPUT_SIZE, "%.6f", VALUE);
		LENGTH = (int)strlen(OUTPUT);

		while (LENGTH > 1 && OUTPUT[LENGTH - 1] == '0')
			OUTPUT[--LENGTH] = 0;

		if (LENGTH > 1 && OUTPUT[LENGTH - 1] == '.')
			OUTPUT[--LENGTH] = 0;
	}
}

static void
	STEP_NOTE(
		STEP_READER *READER, double LEFT, const char *OPERATOR, double RIGHT,
		double VALUE
	)
{
	char	LEFT_TEXT[48];
	char	RIGHT_TEXT[48];
	char	VALUE_TEXT[48];

	/* numbers this big are said by the exact calculator, not here */
	if (
		fabs(LEFT) >= 1e15 ||
		fabs(RIGHT) >= 1e15 ||
		fabs(VALUE) >= 1e15 ||
		VALUE != VALUE
	)
		READER->FAILED = 1;

	if (READER->STEP_COUNT >= 8)
	{
		READER->STEP_COUNT++;
		return ;
	}

	STEP_NUMBER(LEFT, LEFT_TEXT, sizeof LEFT_TEXT);
	STEP_NUMBER(RIGHT, RIGHT_TEXT, sizeof RIGHT_TEXT);
	STEP_NUMBER(VALUE, VALUE_TEXT, sizeof VALUE_TEXT);
	snprintf(
		READER->STEPS[READER->STEP_COUNT++], sizeof READER->STEPS[0],
		"%s %s %s = %s", LEFT_TEXT, OPERATOR, RIGHT_TEXT, VALUE_TEXT
	);
}

static void
	STEP_SPACES(STEP_READER *READER)
{
	while (*READER->AT == ' ')
		READER->AT++;
}

static double
	STEP_ATOM(STEP_READER *READER)
{
	char	*END;
	double	VALUE;

	STEP_SPACES(READER);

	if (*READER->AT == '(')
	{
		READER->AT++;
		VALUE = STEP_SUM(READER);
		STEP_SPACES(READER);

		if (*READER->AT != ')')
			READER->FAILED = 1;
		else
			READER->AT++;

		return (VALUE);
	}

	if (*READER->AT == '-')
	{
		READER->AT++;
		return (-STEP_ATOM(READER));
	}

	if (!isdigit((uint8_t)*READER->AT) && *READER->AT != '.')
	{
		READER->FAILED = 1;
		return (0);
	}

	VALUE = strtod(READER->AT, &END);

	if (END == READER->AT)
	{
		READER->FAILED = 1;
		return (0);
	}

	READER->AT = END;

	return (VALUE);
}

static double
	STEP_POWER(STEP_READER *READER)
{
	double	LEFT = STEP_ATOM(READER);

	STEP_SPACES(READER);

	if (*READER->AT == '^' && !READER->FAILED)
	{
		double	RIGHT;
		double	VALUE;

		READER->AT++;
		RIGHT = STEP_POWER(READER);
		VALUE = pow(LEFT, RIGHT);
		STEP_NOTE(READER, LEFT, "^", RIGHT, VALUE);
		return (VALUE);
	}

	return (LEFT);
}

static double
	STEP_PRODUCT(STEP_READER *READER)
{
	double	LEFT = STEP_POWER(READER);

	while (!READER->FAILED)
	{
		const char	*OPERATOR;
		double		RIGHT;
		double		VALUE;

		STEP_SPACES(READER);

		if (*READER->AT == '*' || *READER->AT == 'x')
		{
			OPERATOR = "*";
			READER->AT++;
		}
		else if (*READER->AT == '/')
		{
			OPERATOR = "/";
			READER->AT++;
		}
		else if (!strncmp(READER->AT, "mod ", 4))
		{
			OPERATOR = "mod";
			READER->AT += 3;
		}
		else
			return (LEFT);

		RIGHT = STEP_POWER(READER);

		if (*OPERATOR != '*' && RIGHT == 0)
		{
			READER->FAILED = 1;
			return (0);
		}

		if (*OPERATOR == '*')
			VALUE = LEFT * RIGHT;
		else if (*OPERATOR == '/')
			VALUE = LEFT / RIGHT;
		else
			VALUE = fmod(LEFT, RIGHT);

		STEP_NOTE(READER, LEFT, OPERATOR, RIGHT, VALUE);
		LEFT = VALUE;
	}

	return (LEFT);
}

static double
	STEP_SUM(STEP_READER *READER)
{
	double	LEFT = STEP_PRODUCT(READER);

	while (!READER->FAILED)
	{
		char	OPERATOR;
		double	RIGHT;
		double	VALUE;

		STEP_SPACES(READER);
		OPERATOR = *READER->AT;

		if (OPERATOR != '+' && OPERATOR != '-')
			return (LEFT);

		READER->AT++;
		RIGHT = STEP_PRODUCT(READER);

		if (OPERATOR == '+')
			VALUE = LEFT + RIGHT;
		else
			VALUE = LEFT - RIGHT;

		STEP_NOTE(READER, LEFT, OPERATOR == '+' ? "+" : "-", RIGHT, VALUE);
		LEFT = VALUE;
	}

	return (LEFT);
}

/* "17 - 5 + 2" -> "17 - 5 = 12, and then 12 + 2 = 14": how many steps it
 * took, 0 when it can't be worked out that way or doesn't come to RESULT */
static int
	EXPRESSION_STEPS(
		const char *EXPRESSION, const char *RESULT, char *OUTPUT,
		int OUTPUT_SIZE
	)
{
	STEP_READER	READER;
	double		VALUE;
	int			POSITION = 0;
	int			INDEX;

	OUTPUT[0] = 0;
	memset(&READER, 0, sizeof READER);
	READER.AT = EXPRESSION;
	VALUE = STEP_SUM(&READER);
	STEP_SPACES(&READER);

	if (
		READER.FAILED ||
		*READER.AT ||
		!READER.STEP_COUNT ||
		READER.STEP_COUNT > 6
	)
		return (0);

	if (RESULT && RESULT[0])
	{
		char	*END;
		double	GIVEN = strtod(RESULT, &END);

		if (
			END == RESULT ||
			fabs(GIVEN - VALUE) > 1e-6 * (fabs(VALUE) > 1 ? fabs(VALUE) : 1)
		)
			return (0);
	}

	for (
		INDEX = 0;
		INDEX < READER.STEP_COUNT && POSITION < OUTPUT_SIZE - 1;
		INDEX++
	)
		POSITION += snprintf(
			OUTPUT + POSITION, (size_t)(OUTPUT_SIZE - POSITION), "%s%s",
			INDEX == 0 ? ""
				: INDEX == READER.STEP_COUNT - 1 ? ", and then "
			: ", then ",
			READER.STEPS[INDEX]
		);

	return (READER.STEP_COUNT);
}

/* "Each number ..." -> "each number ...": the first word is lowered unless
 * it is a name */
static void
	LOWER_FIRST_WORD(char *TEXT)
{
	static const char	*COMMON[53] = {
		"The", "A", "An", "Each", "Every", "It", "Its", "It's", "All", "Both",
		"There", "This", "That", "These", "Those", "Yes", "No", "One", "Some",
		"If", "In", "On", "At", "From", "To", "So", "And", "But", "Your", "You",
		"My", "We", "He", "She", "They", "Because", "When", "Then", "First",
		"Next", "Half", "Twice", "Three", "Two", "Four", "Five", "After",
		"Before", "Since", "Only", "None", "Not", NULL
	};
	int					INDEX;

	for (INDEX = 0; COMMON[INDEX]; INDEX++)
	{
		size_t	LENGTH = strlen(COMMON[INDEX]);

		if (
			!strncmp(TEXT, COMMON[INDEX], LENGTH) &&
			!isalpha((uint8_t)TEXT[LENGTH])
		)
		{
			TEXT[0] = (char)tolower((uint8_t)TEXT[0]);
			return ;
		}
	}
}

/* "Bob is the shortest: Tom is taller than Ann, and Ann is taller than
 * Bob." -> the answer ("Bob is the shortest") and why ("Tom is taller than
 * Ann, and Ann is taller than Bob"); 0 when the reply gives no reason */
static int
	REPLY_REASON(
		const char *REPLY, char *ANSWER, int ANSWER_SIZE, char *REASON,
		int REASON_SIZE
	)
{
	const char	*COLON = strstr(REPLY, ": ");
	const char	*SO = strstr(REPLY, ", so ");
	const char	*BECAUSE = strstr(REPLY, " because ");
	size_t		LENGTH;

	ANSWER[0] = REASON[0] = 0;

	if (COLON && strlen(COLON + 2) > 12)
	{
		snprintf(
			ANSWER, (size_t)ANSWER_SIZE, "%.*s", (int)(COLON - REPLY), REPLY
		);
		snprintf(REASON, (size_t)REASON_SIZE, "%s", COLON + 2);
	}
	else if (BECAUSE)
	{
		snprintf(
			ANSWER, (size_t)ANSWER_SIZE, "%.*s", (int)(BECAUSE - REPLY), REPLY
		);
		snprintf(REASON, (size_t)REASON_SIZE, "%s", BECAUSE + 9);
	}
	else if (SO)
	{
		/* "Yes. A, so B." -> the whole sentence with the "so" */
		const char	*START = SO;

		while (
			START > REPLY &&
			!(
				START[-1] == ' ' &&
				START - 2 >= REPLY &&
				strchr(".!?", START[-2])
			)
		)
			START--;

		snprintf(
			ANSWER, (size_t)ANSWER_SIZE, "%.*s", (int)(START - REPLY), REPLY
		);
		snprintf(REASON, (size_t)REASON_SIZE, "%s", START);
	}
	else
		return (0);

	LENGTH = strlen(REASON);

	while (LENGTH && strchr(" .!", REASON[LENGTH - 1]))
		REASON[--LENGTH] = 0;

	LENGTH = strlen(ANSWER);

	while (LENGTH && strchr(" .!,", ANSWER[LENGTH - 1]))
		ANSWER[--LENGTH] = 0;

	return (REASON[0] != 0);
}

/* the turn's answer, kept so a "why?" right after can be answered: what was
 * done, what came of it, what was said and how it was found */
static void
	NOTE_ANSWER(ENGINE_STATE *ENGINE, const char *REPLY)
{
	char	SKILL_DONE[600];
	char	*ARROW;
	int		KIND = 0;
	int		FOUND_AT = -1;
	int		INDEX;

	if (ENGINE->ANSWER_AGE < 1000)
		ENGINE->ANSWER_AGE++;

	snprintf(
		SKILL_DONE, sizeof SKILL_DONE, "%s",
		ENGINE->SKILL_HIT ? ENGINE->SKILL_ACTION : ""
	);
	ARROW = strstr(SKILL_DONE, " -> ");

	if (ARROW)
		*ARROW = 0;

	for (INDEX = 0; INDEX < ENGINE->ACTION_COUNT; INDEX++)
	{
		const char	*ACTION = ENGINE->ACTION_LOG[INDEX];
		const char	*RESULT = ENGINE->ACTION_RESULTS[INDEX];
		int			THIS_KIND = 0;

		if (SKILL_DONE[0] && !strcmp(ACTION, SKILL_DONE))
		{
			if (!strncmp(ACTION, "know ", 5))
				THIS_KIND = ANSWER_KNOW;
			else if (
				!strncmp(ACTION, "package for ", 12) ||
				!strncmp(ACTION, "ask ", 4)
			)
				THIS_KIND = 0;
			else if (
				!strncmp(ACTION, "calc ", 5) &&
				EXPRESSION_STEPS(
					ACTION + 5, RESULT, ENGINE->ANSWER_EXPRESSION,
					sizeof ENGINE->ANSWER_EXPRESSION
				) > 1 &&
				!ENGINE->SKILL_WHY[0]
			)
				THIS_KIND = ANSWER_CALC;
			else if (!strcmp(ACTION, "time") || !strcmp(ACTION, "date"))
				THIS_KIND = ANSWER_CLOCK;
			else
				THIS_KIND = ANSWER_SKILL;
		}
		else if (
			(
				!strncmp(ACTION, "calc ", 5) &&
				(isdigit((uint8_t)RESULT[0]) || RESULT[0] == '-')
			) ||
			!strcmp(ACTION, "big calc")
		)
			THIS_KIND = ANSWER_CALC;
		else if (!strcmp(ACTION, "solve") && strncmp(RESULT, "kept ", 5))
			THIS_KIND = ANSWER_SOLVE;
		else if (
			(
				!strncmp(ACTION, "your ", 5) &&
				strncmp(RESULT, "you did not", 11) &&
				strncmp(RESULT, "nothing", 7) &&
				strncmp(RESULT, "no", 2)
			) ||
			(
				!strncmp(ACTION, "recall ", 7) &&
				strncmp(RESULT, "nothing", 7) &&
				strncmp(RESULT, "no ", 3)
			)
		)
			THIS_KIND = ANSWER_TOLD;
		else if (
			(!strcmp(ACTION, "time") || !strcmp(ACTION, "date")) &&
			RESULT[0]
		)
			THIS_KIND = ANSWER_CLOCK;
		else if (
			!strncmp(ACTION, "count ", 6) &&
			strstr(ACTION, " in ") &&
			isdigit((uint8_t)RESULT[0])
		)
			THIS_KIND = ANSWER_COUNT;
		else if (
			(
				!strncmp(ACTION, "is ", 3) &&
				(
					strstr(ACTION, " bigger than ") ||
					strstr(ACTION, " smaller than ")
				) &&
				(!strncmp(RESULT, "yes: ", 5) || !strncmp(RESULT, "no: ", 4))
			) ||
			(!strncmp(ACTION, "compare ", 8) && strstr(RESULT, " is "))
		)
			THIS_KIND = ANSWER_COMPARE;

		if (THIS_KIND)
		{
			KIND = THIS_KIND;
			FOUND_AT = INDEX;
		}
	}

	if (!KIND)
		return ;

	ENGINE->ANSWER_KIND = KIND;
	ENGINE->ANSWER_AGE = 0;
	snprintf(
		ENGINE->ANSWER_ACTION, sizeof ENGINE->ANSWER_ACTION, "%s",
		ENGINE->ACTION_LOG[FOUND_AT]
	);
	snprintf(
		ENGINE->ANSWER_RESULT, sizeof ENGINE->ANSWER_RESULT, "%s",
		ENGINE->ACTION_RESULTS[FOUND_AT]
	);
	snprintf(
		ENGINE->ANSWER_REPLY, sizeof ENGINE->ANSWER_REPLY, "%s",
		REPLY ? REPLY : ""
	);
	snprintf(
		ENGINE->ANSWER_MESSAGE, sizeof ENGINE->ANSWER_MESSAGE, "%s",
		ENGINE->USER_TEXT
	);
	snprintf(
		ENGINE->ANSWER_WHY, sizeof ENGINE->ANSWER_WHY, "%s",
		KIND == ANSWER_SKILL || KIND == ANSWER_KNOW ? ENGINE->SKILL_WHY : ""
	);

	if (KIND == ANSWER_CALC)
		snprintf(
			ENGINE->ANSWER_EXPRESSION, sizeof ENGINE->ANSWER_EXPRESSION, "%s",
			!strcmp(ENGINE->ANSWER_ACTION, "big calc")
				? ENGINE->LAST_GROUND_EXPRESSION
				: ENGINE->TURN_EXPRESSION[0] ? ENGINE->TURN_EXPRESSION
			: ENGINE->ANSWER_ACTION + 5
		);
}

/* ---- parts the engine answers itself, before what was taught ---- */

/* what the reply rested on (a fact the user told, a sum, a solved unknown),
 * so a "wrong" right after can be answered with it; and the last count */
static void
	NOTE_GROUNDS(ENGINE_STATE *ENGINE, const char *REPLY)
{
	int	INDEX;
	int	FOUND = 0;

	ENGINE->LAST_GROUND_AGE++;
	ENGINE->LAST_COUNT_AGE++;
	ENGINE->PENDING_WRITE_AGE++;

	/* "say uft" -> "uft": the next "and now krareemeemp" is said back too */
	{
		int	WAS_SAID = ENGINE->LAST_TURN_SAID;

		ENGINE->LAST_TURN_SAID = 0;

		for (INDEX = 0; INDEX < ENGINE->ACTION_COUNT; INDEX++)
			if (!strncmp(ENGINE->ACTION_LOG[INDEX], "say ", 4))
				ENGINE->LAST_TURN_SAID = 1;

		/* the chain goes on while she says back what she is told */
		if (WAS_SAID && REPLY && REPLY[0] && strlen(REPLY) < 200)
		{
			char	TRIMMED[200];
			int		LENGTH;

			snprintf(TRIMMED, sizeof TRIMMED, "%s", REPLY);
			LENGTH = (int)strlen(TRIMMED);

			while (LENGTH && strchr(".!? ", TRIMMED[LENGTH - 1]))
				TRIMMED[--LENGTH] = 0;

			if (LENGTH && FIND_NO_CASE(ENGINE->USER_TEXT, TRIMMED))
				ENGINE->LAST_TURN_SAID = 1;
		}
	}

	/* "I couldn't make asd/env.txt: there is no folder called asd. Should I
	 * make it first?": a yes makes both */
	for (INDEX = 0; INDEX < ENGINE->ACTION_COUNT; INDEX++)
		if (
			!strncmp(ENGINE->ACTION_LOG[INDEX], "write ", 6) &&
			!strcmp(ENGINE->ACTION_RESULTS[INDEX], "bad name") &&
			strchr(ENGINE->ACTION_LOG[INDEX], '/')
		)
		{
			snprintf(
				ENGINE->PENDING_WRITE, sizeof ENGINE->PENDING_WRITE, "%s",
				ENGINE->ACTION_LOG[INDEX]
			);
			ENGINE->PENDING_WRITE_AGE = 0;
		}

	for (INDEX = 0; INDEX < ENGINE->ACTION_COUNT && !FOUND; INDEX++)
	{
		const char	*ACTION = ENGINE->ACTION_LOG[INDEX];
		const char	*RESULT = ENGINE->ACTION_RESULTS[INDEX];

		/* after "I checked again", a second "wrong" is about the same */
		if (!strcmp(ACTION, "check again"))
		{
			ENGINE->LAST_GROUND_AGE = 0;
			FOUND = 1;
			continue ;
		}

		if (!strncmp(ACTION, "range ", 6))
		{
			long long	FROM;
			long long	TO;

			if (sscanf(ACTION + 6, "%lld %lld", &FROM, &TO) == 2)
			{
				ENGINE->LAST_COUNT_FROM = FROM;
				ENGINE->LAST_COUNT_TO = TO;
				ENGINE->LAST_COUNT_AGE = 0;
			}
		}

		if (
			(
				!strncmp(ACTION, "your ", 5) &&
				strncmp(RESULT, "you did not", 11) &&
				strncmp(RESULT, "nothing", 7) &&
				strncmp(RESULT, "no", 2)
			) ||
			(
				!strncmp(ACTION, "calc ", 5) &&
				(isdigit((uint8_t)RESULT[0]) || RESULT[0] == '-')
			) ||
			!strcmp(ACTION, "solve") ||
			!strncmp(ACTION, "recall ", 7) ||
			!strcmp(ACTION, "memories")
		)
		{
			snprintf(
				ENGINE->LAST_GROUND_ACTION, sizeof ENGINE->LAST_GROUND_ACTION,
				"%s", ACTION
			);
			snprintf(
				ENGINE->LAST_GROUND_RESULT, sizeof ENGINE->LAST_GROUND_RESULT,
				"%s", RESULT
			);
			snprintf(
				ENGINE->LAST_GROUND_SAID, sizeof ENGINE->LAST_GROUND_SAID, "%s",
				REPLY
			);

			if (!strncmp(ACTION, "calc ", 5))
				snprintf(
					ENGINE->LAST_GROUND_EXPRESSION,
					sizeof ENGINE->LAST_GROUND_EXPRESSION, "%s",
					ENGINE->TURN_EXPRESSION[0] ? ENGINE->TURN_EXPRESSION
					: ACTION + 5
				);

			ENGINE->LAST_GROUND_AGE = 0;
			ENGINE->PUSH_COUNT = 0;
			FOUND = 1;
		}
	}

	NOTE_ANSWER(ENGINE, REPLY);
	ENGINE->TURN_EXPRESSION[0] = 0;
}

/* the engine's own answer to a part: the turn's action, said as the reply
 * (the brain gets the first try at saying it in its own words) */
static void
	ENGINE_SAYS(
		ENGINE_STATE *ENGINE, const char *ACTION, const char *RESULT,
		const char *SAY, int IS_ACTION
	)
{
	PUSH_SENSE_ACTION(ENGINE, ACTION, RESULT);
	snprintf(ENGINE->TAUGHT_TEXT, sizeof ENGINE->TAUGHT_TEXT, "%s", SAY);
	ENGINE->TAUGHT_ANSWERED = 1;
	ENGINE->ENGINE_ANSWERED = 1;

	if (!strcmp(ACTION, "check again"))
	{
		ENGINE->PUSH_COUNT++;
		ENGINE->PUSHED_SERIAL = ENGINE->MESSAGE_SERIAL;
	}

	ENGINE->SENSE_MODE = SENSE_MODE_DONE;
	ENGINE->SENSE_ACTION_CLASS[0] = 0;

	if (IS_ACTION && ENGINE->ALL_ACTION_COUNT < 16)
	{
		snprintf(
			ENGINE->ALL_ACTIONS[ENGINE->ALL_ACTION_COUNT],
			sizeof ENGINE->ALL_ACTIONS[0], "%.500s", ACTION
		);
		snprintf(
			ENGINE->ALL_RESULTS[ENGINE->ALL_ACTION_COUNT],
			sizeof ENGINE->ALL_RESULTS[0], "%.500s", RESULT
		);
		ENGINE->ALL_ACTION_COUNT++;
	}
}

/* runs one action the way the core would, its result as text */
static void
	ENGINE_RUN(
		ENGINE_STATE *ENGINE, const char *ACTION_TEXT, char *RESULT,
		int RESULT_SIZE
	)
{
	int32_t	ACTION_IDS[WORKING_MEMORY_IDS];
	int32_t	RESULT_IDS[WORKING_MEMORY_IDS];
	int		ID_COUNT = TEXT_TO_WORD_IDS(
		ENGINE, ACTION_TEXT, ACTION_IDS, WORKING_MEMORY_IDS, 1
	);
	int		RESULT_COUNT;

	ENGINE->RAW_ACTION = ACTION_TEXT;
	RESULT_COUNT = RUN_ACTION(
		ENGINE, ACTION_IDS, ID_COUNT, RESULT_IDS, WORKING_MEMORY_IDS
	);
	ENGINE->RAW_ACTION = NULL;
	WORD_IDS_TO_TEXT(ENGINE, RESULT_IDS, RESULT_COUNT, RESULT, RESULT_SIZE);
}

/* "7", "seven", "a hundred" at the word in PLAIN: its value */
static int
	NUMBER_IN_WORDS(const char *WORD, long long *VALUE)
{
	static const char	*WORDS[22] = {
		"zero", "one", "two", "three", "four", "five", "six", "seven", "eight",
		"nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen",
		"sixteen", "seventeen", "eighteen", "nineteen", "twenty", NULL
	};
	int					INDEX;

	if (isdigit((uint8_t)WORD[0]))
	{
		char	*END;

		*VALUE = strtoll(WORD, &END, 10);
		return (*END == 0 || *END == ' ');
	}

	for (INDEX = 0; WORDS[INDEX]; INDEX++)
	{
		size_t	LENGTH = strlen(WORDS[INDEX]);

		if (
			!strncmp(WORD, WORDS[INDEX], LENGTH) &&
			(WORD[LENGTH] == ' ' || !WORD[LENGTH])
		)
		{
			*VALUE = INDEX;
			return (1);
		}
	}

	if (!strncmp(WORD, "hundred", 7) && (WORD[7] == ' ' || !WORD[7]))
	{
		*VALUE = 100;
		return (1);
	}

	return (0);
}

/* the number right after a cue in PLAIN (" to ", " from "), "a hundred"
 * read as 100 */
static int
	NUMBER_AFTER(const char *PLAIN, const char *CUE, long long *VALUE)
{
	const char	*AT = strstr(PLAIN, CUE);

	if (!AT)
		return (0);

	AT += strlen(CUE);

	if (!strncmp(AT, "a hundred", 9) || !strncmp(AT, "one hundred", 11))
	{
		*VALUE = 100;
		return (1);
	}

	return (NUMBER_IN_WORDS(AT, VALUE));
}

/* "Repeat this exact string character-for-character: X7qP-91mZ", "Please
 * repeat: The quick brown fox.", "Copy this text exactly: q9-Z!z": the text
 * after the colon, character for character */
static int
	EXACT_REPEAT_CONTENT(const char *TEXT, char *OUTPUT, int OUTPUT_SIZE)
{
	static const char	*VERBS[15] = {
		" repeat ", " say ", " type ", " copy ", " echo ", " print ",
		" output ", " reply with ", " respond with ", " answer with ",
		" write back ", " send back ", " paste ", " reproduce ", NULL
	};
	static const char	*NOT_HERE[35] = {
		" file ", " folder ", " txt ", " save ", " named ", " called ",
		" remember ", " note ", " into ", " backwards ", " backward ",
		" reverse ", " reversed ", " upside ", " uppercase ", " upper ",
		" lowercase ", " lower ", " capital ", " capitals ", " caps ", " sort ",
		" sorted ", " order ", " alphabetical ", " spell ", " spelled ",
		" translate ", " count ", " shuffle ", " shuffled ", " times ",
		" twice ", " thrice ", NULL
	};
	static const char	*ANSWER_KINDS[11] = {
		" yes or no ", " true or false ", " number ", " numbers ", " one word ",
		" a word ", " single word ", " the answer ", " digit ", " digits ", NULL
	};
	const char			*COLON = strchr(TEXT, ':');
	char				HEAD[400];
	char				HEAD_PLAIN[500];
	const char			*START;
	int					LENGTH;
	int					INDEX;
	int					HAS_VERB = 0;

	if (!COLON || COLON - TEXT >= (long)sizeof HEAD - 1 || COLON == TEXT)
		return (0);

	/* "at 10:30" is a time, not "repeat: X" */
	if (isdigit((uint8_t)COLON[-1]) && isdigit((uint8_t)COLON[1]))
		return (0);

	memcpy(HEAD, TEXT, (size_t)(COLON - TEXT));
	HEAD[COLON - TEXT] = 0;
	PLAIN_LOWER_WORDS(HEAD, HEAD_PLAIN, sizeof HEAD_PLAIN);

	for (INDEX = 0; VERBS[INDEX]; INDEX++)
		if (strstr(HEAD_PLAIN, VERBS[INDEX]))
			HAS_VERB = 1;

	/* "write this exactly: ..." */
	if (
		strstr(HEAD_PLAIN, " write ") &&
		(
			strstr(HEAD_PLAIN, " exact") ||
			strstr(HEAD_PLAIN, " back ") ||
			strstr(HEAD_PLAIN, " same ")
		)
	)
		HAS_VERB = 1;

	if (!HAS_VERB)
		return (0);

	for (INDEX = 0; NOT_HERE[INDEX]; INDEX++)
		if (strstr(HEAD_PLAIN, NOT_HERE[INDEX]))
			return (0);

	/* "say what you think: ..." asks for more than a copy */
	if (strstr(HEAD_PLAIN, " what ") || strstr(HEAD_PLAIN, " how "))
		return (0);

	/* "Answer with only yes or no: is 10 greater than 5?" says how to
	 * answer, not what to copy */
	for (INDEX = 0; ANSWER_KINDS[INDEX]; INDEX++)
		if (strstr(HEAD_PLAIN, ANSWER_KINDS[INDEX]))
			return (0);

	START = COLON + 1;

	while (*START == ' ' || *START == '\t')
		START++;

	LENGTH = (int)strlen(START);

	while (LENGTH && strchr(" \t\r\n", START[LENGTH - 1]))
		LENGTH--;

	/* "repeat: "hello"" -> hello */
	if (
		LENGTH >= 2 &&
		(START[0] == '"' || START[0] == '\'') &&
		START[LENGTH - 1] == START[0]
	)
	{
		START++;
		LENGTH -= 2;
	}

	if (LENGTH <= 0 || LENGTH >= 400)
		return (0);

	/* "say: 75626 three times" asks for it more than once */
	if (!strstr(HEAD_PLAIN, " exact"))
	{
		char	TAIL[420];
		char	TAIL_PLAIN[500];

		snprintf(TAIL, sizeof TAIL, "%.*s", LENGTH, START);
		PLAIN_LOWER_WORDS(TAIL, TAIL_PLAIN, sizeof TAIL_PLAIN);

		{
			size_t				TAIL_LENGTH = strlen(TAIL_PLAIN);
			static const char	*TIMES[4] = {
				" twice ", " thrice ", " times ", NULL
			};
			int					TIMES_INDEX;

			for (TIMES_INDEX = 0; TIMES[TIMES_INDEX]; TIMES_INDEX++)
			{
				size_t	MARK_LENGTH = strlen(TIMES[TIMES_INDEX]);

				if (
					TAIL_LENGTH >= MARK_LENGTH &&
					!strcmp(
						TAIL_PLAIN + TAIL_LENGTH - MARK_LENGTH,
						TIMES[TIMES_INDEX]
					)
				)
					return (0);
			}
		}
	}

	/* "Answer with care: is 10 greater than 5?" asks the question after
	 * the colon */
	if (
		START[LENGTH - 1] == '?' &&
		(
			strstr(HEAD_PLAIN, " answer ") ||
			strstr(HEAD_PLAIN, " reply ") ||
			strstr(HEAD_PLAIN, " respond ")
		) &&
		!strstr(HEAD_PLAIN, " repeat ") &&
		!strstr(HEAD_PLAIN, " copy ") &&
		!strstr(HEAD_PLAIN, " exact")
	)
		return (0);

	if (OUTPUT)
		snprintf(OUTPUT, OUTPUT_SIZE, "%.*s", LENGTH, START);

	return (1);
}

/* a story with numbers and a "how many" question: "I have 17 apples. I give
 * 5 to John ... How many apples do I have?" */
static int
	IS_WORD_PROBLEM(const char *PLAIN)
{
	static const char	*NUMBER_WORDS[20] = {
		" one ", " two ", " three ", " four ", " five ", " six ", " seven ",
		" eight ", " nine ", " ten ", " eleven ", " twelve ", " twenty ",
		" thirty ", " forty ", " fifty ", " hundred ", " half ", " dozen ", NULL
	};
	const char			*CURSOR;
	int					NUMBERS = 0;
	int					INDEX;

	if (
		!strstr(PLAIN, " how many ") &&
		!strstr(PLAIN, " how much ") &&
		!strstr(PLAIN, " how old ")
	)
		return (0);

	for (CURSOR = PLAIN; *CURSOR; CURSOR++)
		if (isdigit((uint8_t)*CURSOR) && !isdigit((uint8_t)CURSOR[1]))
			NUMBERS++;

	for (INDEX = 0; NUMBER_WORDS[INDEX]; INDEX++)
		for (
			CURSOR = strstr(PLAIN, NUMBER_WORDS[INDEX]);
			CURSOR;
			CURSOR = strstr(CURSOR + 1, NUMBER_WORDS[INDEX])
		)
			NUMBERS++;

	return (NUMBERS >= 2);
}

/* "count to 100", "count from 1 to 100", "count 1 to 100 without
 * stopping", "cont from 1 to 100", "count down from 10" */
static int
	COUNT_REQUEST(const char *PLAIN, long long *FROM, long long *TO)
{
	static const char	*VERBS[6] = {
		" count ", " cont ", " coutn ", " cound ", " countdown ", NULL
	};
	const char			*VERB = NULL;
	char				REST[1200];
	int					INDEX;

	for (INDEX = 0; VERBS[INDEX] && !VERB; INDEX++)
		VERB = strstr(PLAIN, VERBS[INDEX]);

	if (!VERB)
		return (0);

	/* "say soosh, then count to 6", "count by 2s to 14": the voice and the
	 * core do those */
	if (
		strstr(PLAIN, " say ") ||
		strstr(PLAIN, " then ") ||
		strstr(PLAIN, " first ") ||
		strstr(PLAIN, " by ") ||
		strstr(PLAIN, " step ") ||
		strstr(PLAIN, " every ") ||
		strstr(PLAIN, " odd ") ||
		strstr(PLAIN, " even ") ||
		strstr(PLAIN, " and ")
	)
		return (0);

	snprintf(REST, sizeof REST, " %s", strchr(VERB + 1, ' ') + 1);

	/* "count the r's in strawberry", "count the words": not numbers */
	if (
		strstr(REST, " in ") &&
		!strstr(REST, " to ") &&
		!strstr(REST, " till ")
	)
		return (0);

	if (
		strstr(REST, " down ") ||
		strstr(REST, " backwards ") ||
		strstr(REST, " backward ")
	)
	{
		if (!NUMBER_AFTER(REST, " from ", FROM))
			return (0);

		if (!NUMBER_AFTER(REST, " to ", TO))
			*TO = 1;

		return (1);
	}

	if (NUMBER_AFTER(REST, " from ", FROM))
	{
		if (
			NUMBER_AFTER(REST, " to ", TO) ||
			NUMBER_AFTER(REST, " till ", TO) ||
			NUMBER_AFTER(REST, " until ", TO) ||
			NUMBER_AFTER(REST, " through ", TO)
		)
			return (1);

		return (0);
	}

	/* "count 1 to 100", "count to 1 to 100" */
	{
		const char	*CURSOR = REST;

		while (*CURSOR == ' ')
			CURSOR++;

		if (!strncmp(CURSOR, "to ", 3))
			CURSOR += 3;

		if (NUMBER_IN_WORDS(CURSOR, FROM))
		{
			const char	*AFTER = strchr(CURSOR, ' ');

			if (
				AFTER &&
				(
					NUMBER_AFTER(AFTER, " to ", TO) ||
					NUMBER_AFTER(AFTER, " till ", TO) ||
					NUMBER_AFTER(AFTER, " until ", TO)
				) &&
				AFTER - CURSOR < 12
			)
				return (1);
		}
	}

	*FROM = 1;

	return (
		NUMBER_AFTER(REST, " to ", TO) ||
		NUMBER_AFTER(REST, " till ", TO) ||
		NUMBER_AFTER(REST, " until ", TO) ||
		NUMBER_AFTER(REST, " up to ", TO)
	);
}

/* a follow-up to the last count: "what about 100?", "I said 100", "count
 * it", "count!", "continue", "you stopped at 37", "do it" */
static int
	COUNT_FOLLOW_UP(
		ENGINE_STATE *ENGINE, const char *PLAIN, long long *FROM, long long *TO
	)
{
	static const char	*AGAIN[7] = {
		" count ", " cont ", " counting ", " without stopping ", " stopped at ",
		" stop at ", NULL
	};
	static const char	*AGAIN_RIGHT_AFTER[10] = {
		" continue ", " keep going ", " go on ", " do it ", " stopped ",
		" all of it ", " the rest ", " finish ", " again ", NULL
	};
	static const char	*NEW_END[10] = {
		" what about ", " how about ", " i said ", " now ", " and ", " up to ",
		" till ", " until ", " to ", NULL
	};
	int					WORDS = 0;
	int					INDEX;
	const char			*CURSOR;

	if (ENGINE->LAST_COUNT_AGE > 6 || !ENGINE->LAST_COUNT_TO)
		return (0);

	if (
		strstr(PLAIN, " say ") ||
		strstr(PLAIN, " then ") ||
		strstr(PLAIN, " first ") ||
		strstr(PLAIN, " by ") ||
		strstr(PLAIN, " letters ") ||
		strstr(PLAIN, " words ") ||
		strstr(PLAIN, " in ") ||
		strstr(PLAIN, " between ") ||
		strstr(PLAIN, " from ") ||
		strstr(PLAIN, " step ") ||
		strstr(PLAIN, " every ")
	)
		return (0);

	for (CURSOR = PLAIN; *CURSOR; CURSOR++)
		if (*CURSOR == ' ' && CURSOR[1])
			WORDS++;

	if (WORDS > 16)
		return (0);

	*FROM = ENGINE->LAST_COUNT_FROM;
	*TO = ENGINE->LAST_COUNT_TO;

	/* "what about 100?", "not to 10, I said 100" */
	for (INDEX = 0; NEW_END[INDEX] && ENGINE->LAST_COUNT_AGE <= 3; INDEX++)
	{
		const char	*AT = PLAIN;
		long long	VALUE;

		while ((AT = strstr(AT, NEW_END[INDEX])))
		{
			if (
				NUMBER_IN_WORDS(AT + strlen(NEW_END[INDEX]), &VALUE) &&
				!(AT - PLAIN >= 4 && !strncmp(AT - 4, " not", 4)) &&
				!strstr(PLAIN, " stopped at ")
			)
			{
				*TO = VALUE;
				return (1);
			}

			AT++;
		}
	}

	for (INDEX = 0; AGAIN[INDEX]; INDEX++)
		if (strstr(PLAIN, AGAIN[INDEX]))
			return (1);

	/* "continue", "do it": only right after the count */
	for (INDEX = 0; AGAIN_RIGHT_AFTER[INDEX]; INDEX++)
		if (
			strstr(PLAIN, AGAIN_RIGHT_AFTER[INDEX]) &&
			ENGINE->LAST_COUNT_AGE <= 1
		)
			return (1);

	return (0);
}

/* the user says Lucy is wrong */
static int
	SAYS_WRONG(const char *PLAIN)
{
	static const char	*WRONG[13] = {
		" wrong ", " incorrect ", " not right ", " not correct ",
		" that's not true ", " not true ", " false ", " that's not it ",
		" no it isn't ", " no it's not ", " you're wrong ", " you are wrong ",
		NULL
	};
	int					INDEX;

	for (INDEX = 0; WRONG[INDEX]; INDEX++)
		if (strstr(PLAIN, WRONG[INDEX]))
			return (1);

	return (0);
}

/* "My cat's name isn't Pamuk." right after "Your cat's name is Pamuk.": the
 * value is denied */
static int
	DENIES_VALUE(const char *PLAIN, const char *VALUE)
{
	char	LOWER_VALUE[200];
	char	PATTERN[260];

	snprintf(LOWER_VALUE, sizeof LOWER_VALUE, "%s", VALUE);
	LOWERCASE_STRING(LOWER_VALUE);

	{
		static const char	*NOTS[6] = {
			" isn't %s", " is not %s", " not %s", " wasn't %s", " was not %s",
			NULL
		};
		int					INDEX;

		for (INDEX = 0; NOTS[INDEX]; INDEX++)
		{
			snprintf(PATTERN, sizeof PATTERN, NOTS[INDEX], LOWER_VALUE);

			if (strstr(PLAIN, PATTERN))
				return (1);
		}
	}

	return (0);
}

/* "Wrong." after an answer that came from somewhere: Lucy says where it came
 * from instead of just giving in */
static int
	PUSH_BACK(ENGINE_STATE *ENGINE, const char *PART_TEXT, const char *PLAIN)
{
	char		SAY[1200];
	const char	*ACTION = ENGINE->LAST_GROUND_ACTION;
	const char	*RESULT = ENGINE->LAST_GROUND_RESULT;
	int			DENIED;

	if (!ACTION[0] || ENGINE->LAST_GROUND_AGE > 2)
		return (0);

	/* said once in this message already */
	if (ENGINE->PUSHED_SERIAL == ENGINE->MESSAGE_SERIAL)
	{
		if (
			SAYS_WRONG(PLAIN) ||
			strstr(PLAIN, " argue") ||
			strstr(PLAIN, " fight back ")
		)
		{
			ENGINE->QUIET_PART = 1;
			return (1);
		}

		return (0);
	}

	DENIED = !strncmp(ACTION, "your ", 5) && DENIES_VALUE(PLAIN, RESULT);

	/* "aren't you going to argue about it?", or "wrong" once more: the
	 * reason, once more */
	if (
		!strncmp(ACTION, "your ", 5) &&
		(
			strstr(PLAIN, " argue") ||
			strstr(PLAIN, " fight back ") ||
			strstr(PLAIN, " disagree") ||
			strstr(PLAIN, " defend ") ||
			(ENGINE->PUSH_COUNT && (SAYS_WRONG(PLAIN) || DENIED))
		)
	)
	{
		char	TOLD[900];
		size_t	LENGTH;

		snprintf(TOLD, sizeof TOLD, "%s", ENGINE->LAST_GROUND_SAID);
		LENGTH = strlen(TOLD);

		while (LENGTH && strchr(" .!", TOLD[LENGTH - 1]))
			TOLD[--LENGTH] = 0;

		if (TOLD[0] && isupper((uint8_t)TOLD[0]) && !isupper((uint8_t)TOLD[1]))
			TOLD[0] = (char)tolower((uint8_t)TOLD[0]);

		if (!strncmp(TOLD, "but you told me that ", 21))
			memmove(TOLD, TOLD + 21, strlen(TOLD + 21) + 1);

		{
			char	*CUT = strstr(TOLD, ". Did it change");

			if (CUT)
				*CUT = 0;
		}

		snprintf(
			SAY, sizeof SAY,
			"I still think %s, because that is what you told me. If it "
			"changed, tell me the new one.",
			TOLD
		);
		ENGINE_SAYS(ENGINE, "check again", RESULT, SAY, 0);
		return (1);
	}

	if (!SAYS_WRONG(PLAIN) && !DENIED)
		return (0);

	if (ENGINE->LAST_GROUND_AGE > 0)
		return (0);

	/* a new value comes with it ("wrong, it's Tom"): the core takes that */
	if (
		strstr(PLAIN, " actually ") ||
		strstr(PLAIN, " it's ") ||
		strstr(PLAIN, " it is ")
	)
		return (0);

	SAY[0] = 0;

	if (!strncmp(ACTION, "your ", 5))
	{
		char	TOLD[900];
		size_t	LENGTH;

		snprintf(TOLD, sizeof TOLD, "%s", ENGINE->LAST_GROUND_SAID);
		LENGTH = strlen(TOLD);

		while (LENGTH && strchr(" .!", TOLD[LENGTH - 1]))
			TOLD[--LENGTH] = 0;

		if (TOLD[0] && isupper((uint8_t)TOLD[0]) && !isupper((uint8_t)TOLD[1]))
			TOLD[0] = (char)tolower((uint8_t)TOLD[0]);

		snprintf(
			SAY, sizeof SAY,
			"But you told me that %s. Did it change? Tell me the new one and "
			"I'll remember it.",
			TOLD
		);
	}
	else if (!strncmp(ACTION, "calc ", 5) || !strcmp(ACTION, "big calc"))
	{
		char	THEIRS[1200] = "";
		char	OURS[1200];
		int		INDEX;
		int		POSITION = 0;

		snprintf(OURS, sizeof OURS, "%s", RESULT);

		/* the number they say is right */
		for (INDEX = 0; PART_TEXT[INDEX] && POSITION < 1150; INDEX++)
			if (
				isdigit((uint8_t)PART_TEXT[INDEX]) ||
				(
					PART_TEXT[INDEX] == '.' &&
					POSITION &&
					isdigit((uint8_t)PART_TEXT[INDEX + 1])
				) ||
				(
					PART_TEXT[INDEX] == '-' &&
					!POSITION &&
					isdigit((uint8_t)PART_TEXT[INDEX + 1])
				)
			)
				THEIRS[POSITION++] = PART_TEXT[INDEX];
			else if (POSITION)
				break ;

		THEIRS[POSITION] = 0;

		if (THEIRS[0] && !strcmp(THEIRS, OURS))
			snprintf(
				SAY, sizeof SAY, "But that is what I said: %s = %s.",
				ENGINE->LAST_GROUND_EXPRESSION, OURS
			);
		else if (THEIRS[0])
			snprintf(
				SAY, sizeof SAY, "I checked again: %s = %s, not %s.",
				ENGINE->LAST_GROUND_EXPRESSION, OURS, THEIRS
			);
		else
			snprintf(
				SAY, sizeof SAY,
				"I checked again: %s = %s. Which part looks wrong to you?",
				ENGINE->LAST_GROUND_EXPRESSION, OURS
			);
	}
	else if (!strcmp(ACTION, "solve"))
		snprintf(
			SAY, sizeof SAY, "I checked again: %c%s",
			RESULT[0] && !isupper((uint8_t)RESULT[1])
				? (char)tolower((uint8_t)RESULT[0])
				: RESULT[0],
			RESULT[0] ? RESULT + 1 : ""
		);
	else if (!strncmp(ACTION, "recall ", 7) || !strcmp(ACTION, "memories"))
		snprintf(
			SAY, sizeof SAY,
			"That is what you told me. If it changed, tell me and I'll "
			"remember the new one."
		);

	if (!SAY[0])
		return (0);

	ENGINE_SAYS(ENGINE, "check again", RESULT, SAY, 0);

	return (1);
}

/* the user's own earlier message that holds VALUE ("I have three apples"),
 * for "you told me so"; 1 when there is one */
static int
	TOLD_SOURCE(
		ENGINE_STATE *ENGINE, const char *VALUE, char *OUTPUT, int OUTPUT_SIZE
	)
{
	static const char	*NUMBER_NAMES[21] = {
		"zero", "one", "two", "three", "four", "five", "six", "seven", "eight",
		"nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen",
		"sixteen", "seventeen", "eighteen", "nineteen", "twenty"
	};
	char				WANTED[2][80];
	int					WANTED_COUNT = 0;
	int					INDEX;

	OUTPUT[0] = 0;

	/* the value's first real word, and a small number as a word too */
	{
		char	PLAIN_VALUE[200];
		char	*WORD;
		char	*SAVE = NULL;

		PLAIN_LOWER_WORDS(VALUE, PLAIN_VALUE, sizeof PLAIN_VALUE);

		for (
			WORD = strtok_r(PLAIN_VALUE, " ", &SAVE);
			WORD && !WANTED_COUNT;
			WORD = strtok_r(NULL, " ", &SAVE)
		)
			if (strlen(WORD) >= 3 || isdigit((uint8_t)WORD[0]))
				snprintf(
					WANTED[WANTED_COUNT++], sizeof WANTED[0], " %s ", WORD
				);
	}

	if (!WANTED_COUNT)
		return (0);

	if (isdigit((uint8_t)WANTED[0][1]))
	{
		int	NUMBER = atoi(WANTED[0] + 1);

		if (NUMBER >= 0 && NUMBER <= 20)
			snprintf(
				WANTED[WANTED_COUNT++], sizeof WANTED[0], " %s ",
				NUMBER_NAMES[NUMBER]
			);
	}
	else
		for (INDEX = 0; INDEX <= 20; INDEX++)
			if (
				!strncmp(
					WANTED[0] + 1, NUMBER_NAMES[INDEX],
					strlen(NUMBER_NAMES[INDEX])
				) &&
				WANTED[0][strlen(NUMBER_NAMES[INDEX]) + 1] == ' '
			)
				snprintf(
					WANTED[WANTED_COUNT++], sizeof WANTED[0], " %d ", INDEX
				);

	for (INDEX = ENGINE->RECENT_USER_COUNT - 1; INDEX >= 0; INDEX--)
	{
		const char	*SAID = ENGINE->RECENT_USER[INDEX];
		char		PLAIN_SAID[800];
		size_t		LENGTH = strlen(SAID);
		int			WHICH;

		if (
			!strcmp(SAID, ENGINE->ANSWER_MESSAGE) ||
			!strcmp(SAID, ENGINE->USER_TEXT) ||
			(LENGTH && SAID[LENGTH - 1] == '?')
		)
			continue ;

		PLAIN_LOWER_WORDS(SAID, PLAIN_SAID, sizeof PLAIN_SAID);

		for (WHICH = 0; WHICH < WANTED_COUNT; WHICH++)
			if (strstr(PLAIN_SAID, WANTED[WHICH]))
			{
				snprintf(OUTPUT, (size_t)OUTPUT_SIZE, "%s", SAID);
				LENGTH = strlen(OUTPUT);

				while (LENGTH && strchr(" .!", OUTPUT[LENGTH - 1]))
					OUTPUT[--LENGTH] = 0;

				return (1);
			}
	}

	return (0);
}

/* "why?", "how do you know?", "show your work", "are you sure?" right after
 * an answer: how it was found, and for "are you sure?" found again */
static int
	EXPLAINS_LAST_ANSWER(ENGINE_STATE *ENGINE, const char *PLAIN)
{
	static const char	*WHY_WHOLE[26] = {
		" why ", " why is that ", " why so ", " how come ", " how ", " how so ",
		" explain ", " explain it ", " explain that ", " explain this ",
		" explain please ", " please explain ", " but why ", " and why ",
		" why not ", " why is it ", " reason ", " proof ", " prove it ",
		" prove that ", " source ", " why though ", " how though ",
		" explain yourself ", " why tho ", NULL
	};
	static const char	*SURE_WHOLE[15] = {
		" really ", " for real ", " seriously ", " you sure ", " u sure ",
		" r u sure ", " is that so ", " is that true ", " certain ",
		" are you certain ", " sure about that ", " are you sure ",
		" are u sure ", " r you sure ", NULL
	};
	static const char	*WHY_PARTS[54] = {
		" explain your answer ", " explain the answer ", " explain how ",
		" explain why ", " can you explain ", " could you explain ",
		" explain your reasoning ", " explain your thinking ",
		" show your work ", " show me your work ", " show the work ",
		" show your steps ", " show the steps ", " show me the steps ",
		" show me how ", " show how ", " how did you get ",
		" how did you find ", " how did you figure ", " how did you work ",
		" how did you calculate ", " how did you come up ",
		" how did you know ", " how do you know ", " how would you know ",
		" how do u know ", " what makes you say ", " what makes you think ",
		" why do you think so ", " why do you think that ",
		" why do you say that ", " why did you say that ",
		" why do you say so ", " why did you say so ",
		" why would you say that ", " walk me through ", " step by step ",
		" your reasoning ", " the reasoning ", " where did you get ",
		" where does that come ", " where did that come ", " how is that ",
		" what's your source ", " what is your source ", " says who ",
		" who says ", " how did you do it ", " how did you do that ",
		" how'd you get ", " how'd you know ", " why is it ", " why is that ",
		NULL
	};
	static const char	*SURE_PARTS[20] = {
		" are you sure ", " are u sure ", " you sure ", " r u sure ",
		" are you certain ", " is that right ", " is that correct ",
		" is that true ", " is it right ", " is it correct ", " is this right ",
		" is this correct ", " double check ", " check again ",
		" check it again ", " sure about that ", " really sure ", " 100 sure ",
		" are you positive ", NULL
	};
	static const char	*NOT_ABOUT[19] = {
		" move", " moved ", " delete", " rename", " file ", " files ",
		" folder ", " wrong ", " remember ", " forget ", " you did ",
		" you didn't ", " u did ", " first ", " before ", " earlier ",
		" last time ", " yesterday ", NULL
	};
	char				SAY[2400];
	char				CORE[1400] = "";
	char				ANSWER[900];
	char				REASON[1300];
	const char			*CURSOR;
	int					IS_WHY = 0;
	int					IS_SURE = 0;
	int					WORDS = 0;
	int					INDEX;

	if (
		!ENGINE->ANSWER_KIND ||
		ENGINE->ANSWER_AGE > 1 ||
		ENGINE->PART_NUMBER > 1
	)
		return (0);

	for (CURSOR = PLAIN; *CURSOR; CURSOR++)
		if (*CURSOR == ' ' && CURSOR[1])
			WORDS++;

	if (WORDS > 9)
		return (0);

	/* "why did you say "It was fun"?" is about those words */
	if (strchr(ENGINE->USER_TEXT, '"'))
		return (0);

	for (INDEX = 0; NOT_ABOUT[INDEX]; INDEX++)
		if (strstr(PLAIN, NOT_ABOUT[INDEX]))
			return (0);

	for (INDEX = 0; WHY_WHOLE[INDEX]; INDEX++)
		if (!strcmp(PLAIN, WHY_WHOLE[INDEX]))
			IS_WHY = 1;

	for (INDEX = 0; SURE_WHOLE[INDEX]; INDEX++)
		if (!strcmp(PLAIN, SURE_WHOLE[INDEX]))
			IS_SURE = 1;

	for (INDEX = 0; WHY_PARTS[INDEX] && !IS_WHY; INDEX++)
		if (strstr(PLAIN, WHY_PARTS[INDEX]))
			IS_WHY = 1;

	for (INDEX = 0; SURE_PARTS[INDEX] && !IS_SURE; INDEX++)
		if (strstr(PLAIN, SURE_PARTS[INDEX]))
			IS_SURE = 1;

	if (!IS_WHY && !IS_SURE)
		return (0);

	/* "are you sure? why?" is both: the check, with the reason */
	if (IS_SURE && IS_WHY)
		IS_WHY = 0;

	SAY[0] = 0;

	switch (ENGINE->ANSWER_KIND)
	{
		case ANSWER_CALC:
		{
			char	STEPS[900];
			int		STEP_COUNT;

			if (ENGINE->ANSWER_EXPRESSION[0])
				STEP_COUNT = EXPRESSION_STEPS(
					ENGINE->ANSWER_EXPRESSION, ENGINE->ANSWER_RESULT, STEPS,
					sizeof STEPS
				);
			else
				STEP_COUNT = 0;

			char	ASKED_PLAIN[900];
			int		FROM_STORY;

			PLAIN_LOWER_WORDS(
				ENGINE->ANSWER_MESSAGE, ASKED_PLAIN, sizeof ASKED_PLAIN
			);
			FROM_STORY = IS_WORD_PROBLEM(ASKED_PLAIN);

			/* "15% of 80": a percent is a part of 100 */
			{
				double	PERCENT;
				double	WHOLE;
				char	PERCENT_TEXT[48];
				char	WHOLE_TEXT[48];
				char	PART_TEXT[48];
				char	TAIL[8] = "";

				if (
					sscanf(
						ENGINE->ANSWER_EXPRESSION, "%lf%% of %lf%7s", &PERCENT,
						&WHOLE, TAIL
					) == 2
				)
				{
					STEP_NUMBER(PERCENT, PERCENT_TEXT, sizeof PERCENT_TEXT);
					STEP_NUMBER(WHOLE, WHOLE_TEXT, sizeof WHOLE_TEXT);
					STEP_NUMBER(PERCENT / 100, PART_TEXT, sizeof PART_TEXT);
					snprintf(
						STEPS, sizeof STEPS,
						"%s%% means %s out of 100, so "
						"%s%% of %s is %s / 100 * %s = %s * %s = %s",
						PERCENT_TEXT, PERCENT_TEXT, PERCENT_TEXT, WHOLE_TEXT,
						PERCENT_TEXT, WHOLE_TEXT, PART_TEXT, WHOLE_TEXT,
						ENGINE->ANSWER_RESULT
					);
					STEP_COUNT = 2;
				}
			}

			if (STEP_COUNT > 1)
			{
				snprintf(CORE, sizeof CORE, "%s", STEPS);
				SAYING(
					ENGINE,
					IS_SURE ? "sure calc steps"
						: FROM_STORY ? "why story steps"
					: "why calc steps",
					IS_SURE ? "Yes. I checked it again, step by step: {1}."
						: FROM_STORY ? "I took the numbers from your message "
					"and worked it out "
					"step by step: {1}."
					: "I worked it out step by step: {1}.",
					SAY, sizeof SAY, STEPS, NULL, NULL, NULL
				);
			}
			else if (ENGINE->ANSWER_EXPRESSION[0] && ENGINE->ANSWER_RESULT[0])
			{
				snprintf(
					CORE, sizeof CORE, "%s = %s", ENGINE->ANSWER_EXPRESSION,
					ENGINE->ANSWER_RESULT
				);
				SAYING(
					ENGINE,
					IS_SURE ? "sure calc"
						: FROM_STORY ? "why story"
					: "why calc",
					IS_SURE ? "Yes. I checked it again: {1} = {2}."
						: FROM_STORY
						? "I took the numbers from your message: {1} = "
					"{2}."
						: "Because {1} = {2}. I work numbers out exactly, so I "
					"don't "
					"guess them.",
					SAY, sizeof SAY, ENGINE->ANSWER_EXPRESSION,
					ENGINE->ANSWER_RESULT, NULL, NULL
				);
			}

			break ;
		}

		case ANSWER_SKILL:
		case ANSWER_KNOW:
		{
			char	WHY_TEXT[1300] = "";

			/* "are you sure?": worked out once more; a different answer this
			 * time is owned up to */
			if (
				IS_SURE &&
				ENGINE->SKILLS_OPENED &&
				ENGINE->ANSWER_KIND == ANSWER_SKILL
			)
			{
				char	AGAIN_ACTION[600];
				char	AGAIN_REPLY[2000];
				char	BEFORE[1300];
				char	*MARK;

				snprintf(
					BEFORE, sizeof BEFORE, "%s -> %s", ENGINE->ANSWER_ACTION,
					ENGINE->ANSWER_RESULT
				);

				if (
					SKILLS_ANSWER(
						&ENGINE->SKILLS, ENGINE->ANSWER_MESSAGE, AGAIN_ACTION,
						sizeof AGAIN_ACTION, AGAIN_REPLY, sizeof AGAIN_REPLY
					) &&
					strcmp(AGAIN_ACTION, BEFORE) &&
					strncmp(AGAIN_ACTION, "ask ", 4)
				)
				{
					MARK = strchr(AGAIN_REPLY, SKILL_WHY_MARK);

					if (MARK)
						*MARK = 0;

					snprintf(CORE, sizeof CORE, "%s", AGAIN_ACTION);
					SAYING(
						ENGINE, "sure changed",
						"Hmm, I worked it out again and got something else "
						"this "
						"time: {1} So the first answer may have been wrong.",
						SAY, sizeof SAY, AGAIN_REPLY, NULL, NULL, NULL
					);
					break ;
				}
			}

			/* the skill said how it found it */
			if (ENGINE->ANSWER_WHY[0])
				snprintf(WHY_TEXT, sizeof WHY_TEXT, "%s", ENGINE->ANSWER_WHY);
			else if (
				ENGINE->ANSWER_KIND == ANSWER_SKILL &&
				REPLY_REASON(
					ENGINE->ANSWER_REPLY, ANSWER, sizeof ANSWER, REASON,
					sizeof REASON
				)
			)
			{
				char	LOWER_ANSWER[900];

				snprintf(LOWER_ANSWER, sizeof LOWER_ANSWER, "%s", ANSWER);
				LOWER_FIRST_WORD(LOWER_ANSWER);

				/* "Yes. A, so B." is its own reason; "B: A" says "A, so B" */
				if (
					IS_SURE &&
					LOWER_ANSWER[0] &&
					strcmp(LOWER_ANSWER, "yes") &&
					strcmp(LOWER_ANSWER, "no") &&
					!strstr(REASON, ", so ")
				)
					snprintf(
						WHY_TEXT, sizeof WHY_TEXT, "%s, so %s", REASON,
						LOWER_ANSWER
					);
				else if (IS_SURE)
					snprintf(WHY_TEXT, sizeof WHY_TEXT, "%s", REASON);
				else
				{
					LOWER_FIRST_WORD(REASON);
					snprintf(WHY_TEXT, sizeof WHY_TEXT, "because %s", REASON);
				}
			}

			{
				size_t	LENGTH = strlen(WHY_TEXT);

				while (LENGTH && strchr(" .", WHY_TEXT[LENGTH - 1]))
					WHY_TEXT[--LENGTH] = 0;
			}

			if (ENGINE->ANSWER_KIND == ANSWER_KNOW && !WHY_TEXT[0])
			{
				char	THING[80] = "";
				char	SOURCE[96] = "";
				char	SAID[900];
				size_t	LENGTH;

				sscanf(ENGINE->ANSWER_ACTION + 5, "%79s", THING);

				if (ENGINE->PACKAGES_OPENED)
					PACKAGES_SOURCE(
						&ENGINE->PACKAGES, THING, SOURCE, sizeof SOURCE
					);

				/* "No, a whale is a mammal, not a fish." -> "a whale is a
				 * mammal, not a fish" */
				snprintf(
					SAID, sizeof SAID, "%s",
					!strncmp(ENGINE->ANSWER_REPLY, "Yes, ", 5) ||
							!strncmp(ENGINE->ANSWER_REPLY, "Yes. ", 5)
						? ENGINE->ANSWER_REPLY + 5
						: !strncmp(ENGINE->ANSWER_REPLY, "No, ", 4) ||
							!strncmp(ENGINE->ANSWER_REPLY, "No. ", 4)
						? ENGINE->ANSWER_REPLY + 4
						: ENGINE->ANSWER_REPLY
				);
				LENGTH = strlen(SAID);

				while (LENGTH && strchr(" .!", SAID[LENGTH - 1]))
					SAID[--LENGTH] = 0;

				LOWER_FIRST_WORD(SAID);
				snprintf(
					CORE, sizeof CORE, "%s", SOURCE[0] ? SOURCE : "memory"
				);

				if (SOURCE[0])
					SAYING(
						ENGINE, IS_SURE ? "sure package" : "why package",
						IS_SURE ? "Yes. My {1} package says {2}."
								: "Because my {1} package says {2}. That's "
						"where my facts "
						"come from; I don't make them up.",
						SAY, sizeof SAY, SOURCE, SAID, NULL, NULL
					);
				else
					SAYING(
						ENGINE, IS_SURE ? "sure memory" : "why memory",
						IS_SURE ? "Yes, that's what my memory says: {1}."
								: "That's what my memory says: {1}.",
						SAY, sizeof SAY, SAID, NULL, NULL, NULL
					);
			}
			else if (WHY_TEXT[0])
			{
				snprintf(CORE, sizeof CORE, "%s", WHY_TEXT);

				if (
					IS_SURE &&
					!strncmp(ENGINE->ANSWER_REPLY, "I can't tell", 12)
				)
					SAYING(
						ENGINE, "sure cant tell",
						"Yes, I'm sure I can't tell: {1}.", SAY, sizeof SAY,
						WHY_TEXT, NULL, NULL, NULL
					);
				else if (IS_SURE)
				{
					WHY_TEXT[0] = (char)toupper((uint8_t)WHY_TEXT[0]);
					SAYING(
						ENGINE, "sure skill", "Yes. {1}.", SAY, sizeof SAY,
						WHY_TEXT, NULL, NULL, NULL
					);
				}
				else
				{
					WHY_TEXT[0] = (char)toupper((uint8_t)WHY_TEXT[0]);
					SAYING(
						ENGINE, "why skill", "{1}.", SAY, sizeof SAY, WHY_TEXT,
						NULL, NULL, NULL
					);
				}
			}
			else
			{
				char	SAID[900];
				size_t	LENGTH;

				snprintf(SAID, sizeof SAID, "%s", ENGINE->ANSWER_REPLY);
				LENGTH = strlen(SAID);

				while (LENGTH && strchr(" .!", SAID[LENGTH - 1]))
					SAID[--LENGTH] = 0;

				LOWER_FIRST_WORD(SAID);
				snprintf(CORE, sizeof CORE, "%s", SAID);
				SAYING(
					ENGINE, IS_SURE ? "sure worked out" : "why worked out",
					IS_SURE
						? "Yes. I worked it out again and got the same: {1}."
						: "I worked it out from what you wrote, step by step, "
					"with my "
					"reasoning skill: {1}.",
					SAY, sizeof SAY, SAID, NULL, NULL, NULL
				);
			}

			break ;
		}

		case ANSWER_SOLVE:
		{
			char	CHECK[900];

			if (SOLVE_CHECK(&ENGINE->SOLVE, CHECK, sizeof CHECK))
			{
				snprintf(CORE, sizeof CORE, "%s", CHECK);
				SAYING(
					ENGINE, IS_SURE ? "sure solve" : "why solve",
					IS_SURE ? "Yes. I put the answer back into your equations "
					"and they all "
					"hold: {1}."
							: "I solved your equations together, exactly. Put "
					"the answer "
					"back in and every one holds: {1}.",
					SAY, sizeof SAY, CHECK, NULL, NULL, NULL
				);
			}
			else
			{
				snprintf(CORE, sizeof CORE, "%s", ENGINE->ANSWER_RESULT);
				SAYING(
					ENGINE, IS_SURE ? "sure solve plain" : "why solve plain",
					IS_SURE ? "Yes. I solved it again and got the same: {1}"
							: "I wrote your equations down and solved them "
					"together, "
					"exactly: {1}",
					SAY, sizeof SAY, ENGINE->ANSWER_RESULT, NULL, NULL, NULL
				);
			}

			break ;
		}

		case ANSWER_TOLD:
		{
			char	SOURCE[800];

			if (
				TOLD_SOURCE(
					ENGINE, ENGINE->ANSWER_RESULT, SOURCE, sizeof SOURCE
				)
			)
			{
				snprintf(CORE, sizeof CORE, "you said: %s", SOURCE);
				SAYING(
					ENGINE, IS_SURE ? "sure told" : "why told",
					IS_SURE ? "Yes. You told me: \"{1}.\""
							: "Because you told me: \"{1}.\"",
					SAY, sizeof SAY, SOURCE, NULL, NULL, NULL
				);
			}
			else
			{
				snprintf(CORE, sizeof CORE, "you told me before");
				SAYING(
					ENGINE, IS_SURE ? "sure told before" : "why told before",
					IS_SURE
						? "Yes, that's what you told me before. If it changed, "
					"tell me the new one."
						: "Because you told me so before, and I remembered it.",
					SAY, sizeof SAY, NULL, NULL, NULL, NULL
				);
			}

			break ;
		}

		case ANSWER_COUNT:
		{
			/* "count r in strawberry": spelled out, where each one is */
			char	WHAT[64] = "";
			char	WORD[300] = "";
			char	SPELLED[700] = "";
			char	PLACES[300] = "";
			int		PLACE_COUNT = 0;
			int		POSITION = 0;
			int		LETTER = 0;
			int		INDEX;

			if (
				sscanf(
					ENGINE->ANSWER_ACTION + 6, "%63s in %299[^\n]", WHAT,
					WORD
				) != 2 ||
				strchr(WORD, ' ') ||
				strlen(WORD) > 60
			)
				break ;

			for (INDEX = 0; WORD[INDEX] && POSITION < 600; INDEX++)
			{
				if (!isalpha((uint8_t)WORD[INDEX]))
					continue ;

				LETTER++;
				POSITION += snprintf(
					SPELLED + POSITION, sizeof SPELLED - POSITION, "%s%c",
					POSITION ? "-" : "", WORD[INDEX]
				);

				if (
					strlen(WHAT) == 1 &&
					tolower((uint8_t)WORD[INDEX]) == tolower((uint8_t)WHAT[0])
				)
				{
					size_t	USED = strlen(PLACES);

					snprintf(
						PLACES + USED, sizeof PLACES - USED, "%s%d",
						!PLACE_COUNT ? "" : ", ", LETTER
					);
					PLACE_COUNT++;
				}
			}

			/* "3, 8, 9" -> "3, 8 and 9" */
			{
				char	*LAST_COMMA = strrchr(PLACES, ',');

				if (LAST_COMMA && PLACE_COUNT > 1)
				{
					char	TAIL[300];

					snprintf(TAIL, sizeof TAIL, " and%s", LAST_COMMA + 1);
					*LAST_COMMA = 0;
					strncat(PLACES, TAIL, sizeof PLACES - strlen(PLACES) - 1);
				}
			}

			if (!strcmp(WHAT, "letters"))
			{
				char	COUNT_TEXT[16];

				snprintf(COUNT_TEXT, sizeof COUNT_TEXT, "%d", LETTER);
				snprintf(CORE, sizeof CORE, "%s: %d letters", SPELLED, LETTER);
				SAYING(
					ENGINE, IS_SURE ? "sure letters" : "why letters",
					IS_SURE ? "Yes. I spelled it out again: {1}. That's {2} "
					"letters."
							: "I spelled it out and counted: {1}. That's {2} "
					"letters.",
					SAY, sizeof SAY, SPELLED, COUNT_TEXT, NULL, NULL
				);
			}
			else if (strlen(WHAT) == 1)
			{
				char	LETTER_TEXT[8];

				snprintf(LETTER_TEXT, sizeof LETTER_TEXT, "%c", WHAT[0]);
				snprintf(
					CORE, sizeof CORE, "%s: %s", SPELLED,
					PLACE_COUNT ? PLACES : "none"
				);

				if (PLACE_COUNT == 1)
					SAYING(
						ENGINE, IS_SURE ? "sure one letter" : "why one letter",
						IS_SURE ? "Yes. I spelled it out again: {1}. The {2} "
						"is letter "
						"{3}, and it is the only one."
								: "I spelled it out: {1}. The {2} is letter "
						"{3}, and it is the "
						"only one.",
						SAY, sizeof SAY, SPELLED, LETTER_TEXT, PLACES, NULL
					);
				else if (PLACE_COUNT)
					SAYING(
						ENGINE,
						IS_SURE ? "sure letter count" : "why letter count",
						IS_SURE ? "Yes. I spelled it out again: {1}. The {2}'s "
						"are letters "
						"{3}."
								: "I spelled it out: {1}. The {2}'s are "
						"letters {3}.",
						SAY, sizeof SAY, SPELLED, LETTER_TEXT, PLACES, NULL
					);
				else
					SAYING(
						ENGINE, IS_SURE ? "sure no letter" : "why no letter",
						IS_SURE
							? "Yes. I spelled it out again: {1}. There is no "
						"{2} in it."
							: "I spelled it out: {1}. There is no {2} in it.",
						SAY, sizeof SAY, SPELLED, LETTER_TEXT, NULL, NULL
					);
			}

			break ;
		}

		case ANSWER_COMPARE:
		{
			/* "is 9.11 bigger than 9.9" -> lined up: 9.11 and 9.90 */
			char	FIRST[64] = "";
			char	SECOND[64] = "";
			char	DIFFERENCE_TEXT[64];
			char	SMALL[64];
			char	BIG[64];
			double	FIRST_VALUE;
			double	SECOND_VALUE;

			if (!strncmp(ENGINE->ANSWER_ACTION, "is ", 3))
			{
				if (
					sscanf(
						ENGINE->ANSWER_ACTION + 3, "%63s %*s than %63s", FIRST,
						SECOND
					) != 2
				)
					break ;
			}
			else if (
				sscanf(ENGINE->ANSWER_ACTION + 8, "%63s %63s", FIRST, SECOND) !=
					2
			)
				break ;

			FIRST_VALUE = atof(FIRST);
			SECOND_VALUE = atof(SECOND);

			if (FIRST_VALUE == SECOND_VALUE)
				break ;

			snprintf(
				SMALL, sizeof SMALL, "%s",
				FIRST_VALUE < SECOND_VALUE ? FIRST : SECOND
			);
			snprintf(
				BIG, sizeof BIG, "%s",
				FIRST_VALUE < SECOND_VALUE ? SECOND : FIRST
			);
			STEP_NUMBER(
				fabs(FIRST_VALUE - SECOND_VALUE), DIFFERENCE_TEXT,
				sizeof DIFFERENCE_TEXT
			);
			snprintf(
				CORE, sizeof CORE, "%s - %s = %s", BIG, SMALL, DIFFERENCE_TEXT
			);

			/* the same whole part, different decimals: the classic slip */
			if (
				strchr(FIRST, '.') &&
				strchr(SECOND, '.') &&
				floor(FIRST_VALUE) == floor(SECOND_VALUE)
			)
			{
				char	LINED_FIRST[80];
				char	LINED_SECOND[80];
				size_t	FIRST_DECIMALS = strlen(strchr(FIRST, '.') + 1);
				size_t	SECOND_DECIMALS = strlen(strchr(SECOND, '.') + 1);
				size_t	WIDTH;

				if (FIRST_DECIMALS > SECOND_DECIMALS)
					WIDTH = FIRST_DECIMALS;
				else
					WIDTH = SECOND_DECIMALS;

				snprintf(
					LINED_FIRST, sizeof LINED_FIRST, "%s%.*s", FIRST,
					(int)(WIDTH - FIRST_DECIMALS), "000000000000"
				);
				snprintf(
					LINED_SECOND, sizeof LINED_SECOND, "%s%.*s", SECOND,
					(int)(WIDTH - SECOND_DECIMALS), "000000000000"
				);

				{
					const char	*DETAILS[5];

					DETAILS[0] = LINED_FIRST;
					DETAILS[1] = LINED_SECOND;
					DETAILS[2] = SMALL;
					DETAILS[3] = BIG;
					DETAILS[4] = DIFFERENCE_TEXT;
					SAYING_LIST(
						ENGINE, IS_SURE ? "sure decimals" : "why decimals",
						IS_SURE ? "Yes. Line them up: {1} and {2}. The whole "
						"parts are the "
						"same, and after the point {3} has less, so "
						"{3} is smaller "
						"than {4} ({4} - {3} = {5})."
								: "Line them up: {1} and {2}. The whole parts "
						"are the same, "
						"so look after the point: {3} has less "
						"there. So {3} is "
						"smaller than {4} ({4} - {3} = {5}).",
						SAY, sizeof SAY, DETAILS, 5
					);
				}
			}
			else
				SAYING(
					ENGINE, IS_SURE ? "sure compare" : "why compare",
					IS_SURE ? "Yes. {1} - {2} = {3}, so {2} is the smaller one."
							: "Because {1} - {2} = {3}: {1} is more than {2}.",
					SAY, sizeof SAY, BIG, SMALL, DIFFERENCE_TEXT, NULL
				);

			break ;
		}

		case ANSWER_CLOCK:
		{
			snprintf(CORE, sizeof CORE, "this computer's clock");
			SAYING(
				ENGINE, IS_SURE ? "sure clock" : "why clock",
				IS_SURE
					? "Yes, that's what this computer's clock says right now."
					: "I read it from this computer's clock.",
				SAY, sizeof SAY, NULL, NULL, NULL, NULL
			);
		}
		break ;
	}

	if (!SAY[0])
		return (0);

	ENGINE_SAYS(
		ENGINE, IS_SURE ? "check my answer" : "explain my answer",
		CORE[0] ? CORE : ENGINE->ANSWER_RESULT, SAY, 0
	);
	ENGINE->EXACT_REPLY = 1;

	/* the answer stays the one asked about */
	ENGINE->ANSWER_AGE = -1;

	return (1);
}

/* "I told you not to ask me that": the question is not asked again */
static int
	STOP_ASKING(ENGINE_STATE *ENGINE, const char *PLAIN)
{
	static const char	*ASKS[9] = {
		" not ask me ", " don't ask ", " dont ask ", " do not ask ",
		" stop asking ", " not to ask ", " never ask ", " quit asking ", NULL
	};
	THOUGHT				*MIND = &ENGINE->WORKING_MEMORY;
	char				QUESTION[300] = "";
	int					INDEX;
	int					FOUND = 0;

	for (INDEX = 0; ASKS[INDEX]; INDEX++)
		if (strstr(PLAIN, ASKS[INDEX]))
			FOUND = 1;

	if (!FOUND)
		return (0);

	/* Lucy's last question */
	for (INDEX = MIND->MESSAGE_COUNT - 1; INDEX >= 0; INDEX--)
	{
		char	SAID[1024];
		char	*MARK;
		char	*START;

		if (MIND->MESSAGES[INDEX].SPEAKER != 1)
			continue ;

		WORD_IDS_TO_TEXT(
			ENGINE, MIND->MESSAGES[INDEX].IDS, MIND->MESSAGES[INDEX].ID_COUNT,
			SAID, sizeof SAID
		);
		MARK = strrchr(SAID, '?');

		if (!MARK)
			continue ;

		MARK[1] = 0;
		START = MARK;

		while (START > SAID && !strchr(".!", START[-1]))
			START--;

		while (*START == ' ')
			START++;

		snprintf(QUESTION, sizeof QUESTION, "%s", START);
		break ;
	}

	if (QUESTION[0])
	{
		char	PLAIN_QUESTION[300];

		PLAIN_LOWER_WORDS(QUESTION, PLAIN_QUESTION, sizeof PLAIN_QUESTION);

		if (ENGINE->DISLIKED_QUESTION_COUNT < 16)
			snprintf(
				ENGINE->DISLIKED_QUESTIONS[ENGINE->DISLIKED_QUESTION_COUNT++],
				sizeof ENGINE->DISLIKED_QUESTIONS[0], "%s", PLAIN_QUESTION
			);
	}

	{
		char	SAY[400];

		SAYING(
			ENGINE, "won't ask again", "Sorry. I won't ask you that again.",
			SAY, sizeof SAY, NULL, NULL, NULL, NULL
		);
		ENGINE_SAYS(
			ENGINE, "dont ask", QUESTION[0] ? QUESTION : "nothing asked", SAY, 0
		);
	}

	return (1);
}

/* "are you listening?", "do you even understand me?" */
static int
	ASKS_IF_LISTENING(ENGINE_STATE *ENGINE, const char *PLAIN)
{
	static const char	*ASKS[15] = {
		" are you listening ", " you listening ", " do you understand me ",
		" do you even understand me ", " are you even listening ",
		" are you paying attention ", " do you even listen ",
		" are you reading ", " are we even talking ", " are we talking ",
		" are you there ", " are you even there ", " anyone there ",
		" is anyone there ", NULL
	};
	int					INDEX;

	for (INDEX = 0; ASKS[INDEX]; INDEX++)
		if (strstr(PLAIN, ASKS[INDEX]))
		{
			char	SAY[600];

			SAYING(
				ENGINE, "listening",
				"Yes, I read every message. When I get something wrong, tell "
				"me "
				"and I'll try again.",
				SAY, sizeof SAY, NULL, NULL, NULL, NULL
			);
			ENGINE_SAYS(
				ENGINE, "am listening", "yes: I read every message", SAY, 0
			);
			return (1);
		}

	return (0);
}

/* ---- what other people told Lucy about themselves ---- */

/* one line of a person's profile: "you", "have", "a cat named Mjölnir" */
typedef struct
{
	char	SUBJECT[64];
	char	ATTRIBUTE[64];
	char	VALUE[200];
} PERSON_FACT;

static int
	LOAD_PERSON_FACTS(const char *NAME, PERSON_FACT *FACTS, int LIMIT)
{
	char	PATH[700];
	char	LINE[600];
	FILE	*STREAM;
	int		COUNT = 0;

	PERSON_PATH(NAME, "profile.txt", PATH, sizeof PATH);
	STREAM = fopen(PATH, "rb");

	if (!STREAM)
		return (0);

	while (COUNT < LIMIT && fgets(LINE, sizeof LINE, STREAM))
	{
		char	*FIRST_TAB = strchr(LINE, '\t');
		char	*SECOND_TAB;

		if (FIRST_TAB)
			SECOND_TAB = strchr(FIRST_TAB + 1, '\t');
		else
			SECOND_TAB = NULL;

		size_t	LENGTH;

		if (!SECOND_TAB)
			continue ;

		*FIRST_TAB = *SECOND_TAB = 0;
		LENGTH = strlen(SECOND_TAB + 1);

		while (LENGTH && strchr("\r\n", SECOND_TAB[LENGTH]))
			SECOND_TAB[LENGTH--] = 0;

		snprintf(FACTS[COUNT].SUBJECT, sizeof FACTS[0].SUBJECT, "%s", LINE);
		snprintf(
			FACTS[COUNT].ATTRIBUTE, sizeof FACTS[0].ATTRIBUTE, "%s",
			FIRST_TAB + 1
		);
		snprintf(
			FACTS[COUNT].VALUE, sizeof FACTS[0].VALUE, "%s", SECOND_TAB + 1
		);
		COUNT++;
	}

	fclose(STREAM);

	return (COUNT);
}

/* "you have a cat named Mjölnir" said about NAME: "Sylwia has a cat named
 * Mjölnir" */
static void
	SAY_PERSON_FACT(
		const char *NAME, const PERSON_FACT *FACT, char *OUTPUT, int OUTPUT_SIZE
	)
{
	if (!strcmp(FACT->SUBJECT, "you"))
	{
		if (!strcmp(FACT->ATTRIBUTE, "have"))
			snprintf(OUTPUT, OUTPUT_SIZE, "%s has %s", NAME, FACT->VALUE);
		else if (!strcmp(FACT->ATTRIBUTE, "home"))
			snprintf(OUTPUT, OUTPUT_SIZE, "%s lives in %s", NAME, FACT->VALUE);
		else if (!strcmp(FACT->ATTRIBUTE, "age"))
			snprintf(OUTPUT, OUTPUT_SIZE, "%s is %s", NAME, FACT->VALUE);
		else if (!strcmp(FACT->ATTRIBUTE, "name"))
			snprintf(OUTPUT, OUTPUT_SIZE, "%s's name is %s", NAME, FACT->VALUE);
		else if (!strcmp(FACT->ATTRIBUTE, "from"))
			snprintf(OUTPUT, OUTPUT_SIZE, "%s is from %s", NAME, FACT->VALUE);
		else if (
			!strcmp(FACT->ATTRIBUTE, "job") ||
			!strcmp(FACT->ATTRIBUTE, "work")
		)
			snprintf(OUTPUT, OUTPUT_SIZE, "%s works as %s", NAME, FACT->VALUE);
		else if (
			!strcmp(FACT->ATTRIBUTE, "like") ||
			!strcmp(FACT->ATTRIBUTE, "likes")
		)
			snprintf(OUTPUT, OUTPUT_SIZE, "%s likes %s", NAME, FACT->VALUE);
		else
			snprintf(
				OUTPUT, OUTPUT_SIZE, "%s's %s is %s", NAME, FACT->ATTRIBUTE,
				FACT->VALUE
			);
	}
	else if (!strncmp(FACT->SUBJECT, "your ", 5))
		snprintf(
			OUTPUT, OUTPUT_SIZE, "%s's %s's %s is %s", NAME, FACT->SUBJECT + 5,
			FACT->ATTRIBUTE, FACT->VALUE
		);
	else
		snprintf(
			OUTPUT, OUTPUT_SIZE, "%s's %s %s is %s", NAME, FACT->SUBJECT,
			FACT->ATTRIBUTE, FACT->VALUE
		);
}

/* "Does Sylwia have a cat?", "What is Sylwia's cat's name?", "How old is
 * Sylwia?", "What do you know about Sylwia?": from what Sylwia told Lucy
 * herself, said as hers */
static int
	ASKS_ABOUT_PERSON(
		ENGINE_STATE *ENGINE, const char *PART_TEXT, const char *PLAIN
	)
{
	FILE_ENTRY	*ENTRIES;
	PERSON_FACT	FACTS[48];
	char		NAME[64] = "";
	char		KEY[64] = "";
	char		SAY[1600];
	char		CORE[1200] = "";
	int			COUNT;
	int			FACT_COUNT;
	int			INDEX;

	(void)PART_TEXT;

	if (
		!strchr(PART_TEXT, '?') &&
		!strstr(PLAIN, " tell me about ") &&
		!strstr(PLAIN, " what do you know about ")
	)
		return (0);

	ENTRIES = calloc(128, sizeof(FILE_ENTRY));

	if (!ENTRIES)
		return (0);

	COUNT = FILE_SYSTEM_LIST(PERSONS_DIRECTORY, ENTRIES, 128);

	/* a person with a folder, named in the question, not the one asking */
	for (INDEX = 0; INDEX < COUNT && !KEY[0]; INDEX++)
	{
		char	PATTERN[160];
		char	OWN[64];

		if (!ENTRIES[INDEX].IS_DIRECTORY || strlen(ENTRIES[INDEX].NAME) < 2)
			continue ;

		PERSON_PATH(ENGINE->USER_NAME, "", OWN, sizeof OWN);

		if (
			!strcmp(strrchr(OWN, '/') + 1, ENTRIES[INDEX].NAME) ||
			!strcasecmp(ENTRIES[INDEX].NAME, ENGINE->ASSISTANT_NAME) ||
			!strcmp(ENTRIES[INDEX].NAME, "friend")
		)
			continue ;

		snprintf(PATTERN, sizeof PATTERN, " %s ", ENTRIES[INDEX].NAME);

		if (!strstr(PLAIN, PATTERN))
		{
			snprintf(PATTERN, sizeof PATTERN, " %s's ", ENTRIES[INDEX].NAME);

			if (!strstr(PLAIN, PATTERN))
				continue ;
		}

		snprintf(KEY, sizeof KEY, "%s", ENTRIES[INDEX].NAME);
	}

	free(ENTRIES);

	if (!KEY[0])
		return (0);

	FACT_COUNT = LOAD_PERSON_FACTS(KEY, FACTS, 48);

	/* the name as it was written in the question */
	{
		const char	*AT = FIND_NO_CASE(PART_TEXT, KEY);

		snprintf(NAME, sizeof NAME, "%.*s", (int)strlen(KEY), AT ? AT : KEY);
		NAME[0] = (char)toupper((uint8_t)NAME[0]);
	}

	SAY[0] = 0;

	/* "does Sylwia have a cat?" */
	{
		char		PATTERN[160];
		const char	*HAVE;

		snprintf(PATTERN, sizeof PATTERN, " does %s have ", KEY);
		HAVE = strstr(PLAIN, PATTERN);

		if (HAVE)
		{
			char	THING[64] = "";
			char	SINGLE[64];
			char	*SPACE;

			sscanf(HAVE + strlen(PATTERN), "%63[^\n]", THING);

			/* "a cat", "any pets": the thing, without the little words */
			while (
				!strncmp(THING, "a ", 2) ||
				!strncmp(THING, "an ", 3) ||
				!strncmp(THING, "any ", 4) ||
				!strncmp(THING, "the ", 4)
			)
				memmove(
					THING, strchr(THING, ' ') + 1,
					strlen(strchr(THING, ' ') + 1) + 1
				);

			SPACE = strchr(THING, ' ');

			if (SPACE)
				*SPACE = 0;

			snprintf(SINGLE, sizeof SINGLE, "%s", THING);

			if (strlen(SINGLE) > 3 && SINGLE[strlen(SINGLE) - 1] == 's')
				SINGLE[strlen(SINGLE) - 1] = 0;

			for (INDEX = 0; INDEX < FACT_COUNT && THING[0]; INDEX++)
			{
				char	VALUE_PLAIN[300];
				char	WORD_PATTERN[80];

				if (
					strcmp(FACTS[INDEX].SUBJECT, "you") ||
					strcmp(FACTS[INDEX].ATTRIBUTE, "have")
				)
					continue ;

				PLAIN_LOWER_WORDS(
					FACTS[INDEX].VALUE, VALUE_PLAIN, sizeof VALUE_PLAIN
				);
				snprintf(WORD_PATTERN, sizeof WORD_PATTERN, " %s", SINGLE);

				if (strstr(VALUE_PLAIN, WORD_PATTERN))
				{
					char	FACT_TEXT[400];

					SAY_PERSON_FACT(
						NAME, &FACTS[INDEX], FACT_TEXT, sizeof FACT_TEXT
					);
					snprintf(CORE, sizeof CORE, "%s", FACT_TEXT);
					SAYING(
						ENGINE, "person has",
						"Yes. {1}. That's what {2} told "
						"me.",
						SAY, sizeof SAY, FACT_TEXT, NAME, NULL, NULL
					);
					break ;
				}
			}

			if (!SAY[0] && THING[0])
			{
				snprintf(CORE, sizeof CORE, "not told");
				SAYING(
					ENGINE, "person not told",
					"I don't know. {1} never told "
					"me about that.",
					SAY, sizeof SAY, NAME, NULL, NULL, NULL
				);
			}
		}
	}

	/* "what is Sylwia's cat's name?", "what's Sylwia's favorite color?",
	 * "how old is Sylwia?", "where does Sylwia live?" */
	if (!SAY[0])
	{
		char		OWNED[64] = "";
		char		PATTERN[160];
		const char	*AT;
		int			WANT_AGE;
		int			WANT_HOME;

		snprintf(PATTERN, sizeof PATTERN, " %s's ", KEY);
		AT = strstr(PLAIN, PATTERN);

		if (AT)
		{
			char	REST[300];
			char	*CUT;

			snprintf(REST, sizeof REST, "%s", AT + strlen(PATTERN));
			CUT = strstr(REST, " name ");

			/* "sylwia's cat's name": the cat */
			if (CUT && strstr(REST, "'s "))
			{
				*strstr(REST, "'s ") = 0;
				snprintf(OWNED, sizeof OWNED, "your %s", REST);

				for (INDEX = 0; INDEX < FACT_COUNT; INDEX++)
					if (
						!strcmp(FACTS[INDEX].SUBJECT, OWNED) &&
						!strcmp(FACTS[INDEX].ATTRIBUTE, "name")
					)
					{
						snprintf(CORE, sizeof CORE, "%s", FACTS[INDEX].VALUE);
						SAYING(
							ENGINE, "person thing name",
							"{1}'s {2} is "
							"called {3}. That's what {1} told me.",
							SAY, sizeof SAY, NAME, REST, FACTS[INDEX].VALUE,
							NULL
						);
						break ;
					}
			}
			else
			{
				/* "sylwia's favorite color": everything up to the end */
				size_t	LENGTH = strlen(REST);

				while (LENGTH && REST[LENGTH - 1] == ' ')
					REST[--LENGTH] = 0;

				for (INDEX = 0; INDEX < FACT_COUNT; INDEX++)
					if (
						!strcmp(FACTS[INDEX].SUBJECT, "you") &&
						!strcmp(FACTS[INDEX].ATTRIBUTE, REST)
					)
					{
						char	FACT_TEXT[400];

						SAY_PERSON_FACT(
							NAME, &FACTS[INDEX], FACT_TEXT, sizeof FACT_TEXT
						);
						snprintf(CORE, sizeof CORE, "%s", FACT_TEXT);
						SAYING(
							ENGINE, "person fact",
							"{1}. That's what {2} "
							"told me.",
							SAY, sizeof SAY, FACT_TEXT, NAME, NULL, NULL
						);
						break ;
					}
			}

			if (!SAY[0])
			{
				snprintf(CORE, sizeof CORE, "not told");
				SAYING(
					ENGINE, "person not told",
					"I don't know. {1} never told "
					"me about that.",
					SAY, sizeof SAY, NAME, NULL, NULL, NULL
				);
			}
		}

		snprintf(PATTERN, sizeof PATTERN, " how old is %s ", KEY);
		WANT_AGE = strstr(PLAIN, PATTERN) != NULL;
		snprintf(PATTERN, sizeof PATTERN, " where does %s live ", KEY);
		WANT_HOME = strstr(PLAIN, PATTERN) != NULL;

		for (
			INDEX = 0;
			INDEX < FACT_COUNT && !SAY[0] && (WANT_AGE || WANT_HOME);
			INDEX++
		)
			if (
				!strcmp(FACTS[INDEX].SUBJECT, "you") &&
				!strcmp(FACTS[INDEX].ATTRIBUTE, WANT_AGE ? "age" : "home")
			)
			{
				char	FACT_TEXT[400];

				SAY_PERSON_FACT(
					NAME, &FACTS[INDEX], FACT_TEXT, sizeof FACT_TEXT
				);
				snprintf(CORE, sizeof CORE, "%s", FACT_TEXT);
				SAYING(
					ENGINE, "person fact", "{1}. That's what {2} told me.", SAY,
					sizeof SAY, FACT_TEXT, NAME, NULL, NULL
				);
			}

		if (!SAY[0] && (WANT_AGE || WANT_HOME))
		{
			snprintf(CORE, sizeof CORE, "not told");
			SAYING(
				ENGINE, "person not told",
				"I don't know. {1} never told "
				"me about that.",
				SAY, sizeof SAY, NAME, NULL, NULL, NULL
			);
		}
	}

	/* "what do you know about Sylwia?" */
	if (!SAY[0])
	{
		char	PATTERN[160];
		char	PATTERN_TWO[160];

		snprintf(PATTERN, sizeof PATTERN, " know about %s ", KEY);
		snprintf(PATTERN_TWO, sizeof PATTERN_TWO, " tell me about %s ", KEY);

		if (strstr(PLAIN, PATTERN) || strstr(PLAIN, PATTERN_TWO))
		{
			char	LIST[1200] = "";
			int		POSITION = 0;
			int		SAID = 0;

			for (INDEX = 0; INDEX < FACT_COUNT && POSITION < 1000; INDEX++)
			{
				char	FACT_TEXT[400];

				/* "you have a cat named X" says it already */
				if (
					!strcmp(FACTS[INDEX].ATTRIBUTE, "name") &&
					strncmp(FACTS[INDEX].SUBJECT, "your ", 5) == 0
				)
					continue ;

				SAY_PERSON_FACT(
					NAME, &FACTS[INDEX], FACT_TEXT, sizeof FACT_TEXT
				);
				POSITION += snprintf(
					LIST + POSITION, sizeof LIST - POSITION, "%s%s",
					SAID ? "; " : "", FACT_TEXT
				);
				SAID++;
			}

			snprintf(CORE, sizeof CORE, "%s", SAID ? LIST : "nothing");

			if (SAID)
				SAYING(
					ENGINE, "person facts", "Here is what {1} told me: {2}.",
					SAY, sizeof SAY, NAME, LIST, NULL, NULL
				);
			else
				SAYING(
					ENGINE, "person nothing",
					"{1} hasn't told me anything "
					"about themselves yet.",
					SAY, sizeof SAY, NAME, NULL, NULL, NULL
				);
		}
	}

	if (!SAY[0])
		return (0);

	{
		char	ACTION_TEXT[200];

		snprintf(ACTION_TEXT, sizeof ACTION_TEXT, "person %s", KEY);
		ENGINE_SAYS(ENGINE, ACTION_TEXT, CORE, SAY, 0);
	}

	ENGINE->EXACT_REPLY = 1;

	return (1);
}

static int	PLAIN_WORD_LIST(const char *PLAIN, char (*WORDS)[48], int LIMIT);

/* "tell me a joke", "write a poem", "translate hello to Spanish": a joke
 * from sayings.txt, and honest words about what she can't make */
static int
	ASKS_FOR_FUN(ENGINE_STATE *ENGINE, const char *PLAIN)
{
	static const char	*JOKES[15] = {
		" tell me a joke ", " tell a joke ", " say a joke ", " a joke ",
		" know any jokes ", " know a joke ", " make me laugh ",
		" say something funny ", " tell me something funny ", " another joke ",
		" one more joke ", " joke please ", " tell me another joke ",
		" do you know any jokes ", NULL
	};
	static const char	*WRITING[12] = {
		" poem ", " haiku ", " story ", " song ", " limerick ", " essay ",
		" sonnet ", " rap ", " novel ", " lyrics ", " rhyme ", NULL
	};
	char				SAY[1200];
	int					INDEX;

	for (INDEX = 0; JOKES[INDEX]; INDEX++)
		if (
			(INDEX == 3 && !strcmp(PLAIN, JOKES[INDEX])) ||
			(INDEX != 3 && strstr(PLAIN, JOKES[INDEX]))
		)
		{
			SAYING(
				ENGINE, "joke",
				"Why was the math book sad? It had too many "
				"problems.",
				SAY, sizeof SAY, NULL, NULL, NULL, NULL
			);
			ENGINE_SAYS(ENGINE, "joke", "told", SAY, 0);
			ENGINE->EXACT_REPLY = 1;
			return (1);
		}

	/* "write a poem about the sea", "can you tell me a story": asked of her,
	 * not "I'm going to write a story, help me" */
	{
		static const char	*LEADS[10] = {
			" please ", " can you ", " could you ", " will you ", " would you ",
			" lucy ", " hey ", " ok ", " now ", NULL
		};
		const char			*START = PLAIN;
		int					MOVED = 1;

		while (MOVED)
		{
			MOVED = 0;

			for (INDEX = 0; LEADS[INDEX]; INDEX++)
				if (!strncmp(START, LEADS[INDEX], strlen(LEADS[INDEX])))
				{
					START += strlen(LEADS[INDEX]) - 1;
					MOVED = 1;
				}
		}

		if (
			strncmp(START, " write ", 7) &&
			strncmp(START, " compose ", 9) &&
			strncmp(START, " tell me a ", 11) &&
			strncmp(START, " make up ", 9) &&
			strncmp(START, " create a ", 10)
		)
			START = NULL;

		if (
			!START ||
			strstr(PLAIN, " txt ") ||
			strstr(PLAIN, " file ") ||
			strstr(PLAIN, " folder ")
		)
			INDEX = -1;
		else
			INDEX = 0;
	}

	if (INDEX == 0)
		for (INDEX = 0; WRITING[INDEX]; INDEX++)
			if (strstr(PLAIN, WRITING[INDEX]))
			{
				SAYING(
					ENGINE, "cant write",
					"I can't write poems or stories: my "
					"brain is small and made for exact work like math, logic, "
					"memory and files. I can tell you a joke, though.",
					SAY, sizeof SAY, NULL, NULL, NULL, NULL
				);
				ENGINE_SAYS(
					ENGINE, "can write", "no: my brain is too small", SAY, 0
				);
				ENGINE->EXACT_REPLY = 1;
				return (1);
			}

	/* "translate hello to Spanish", "how do you say cat in French" */
	if (
		strstr(PLAIN, " translate ") ||
		(
			(
				strstr(PLAIN, " how do you say ") ||
				strstr(PLAIN, " what is ") ||
				strstr(PLAIN, " what's ")
			) &&
			(
				strstr(PLAIN, " in spanish ") ||
				strstr(PLAIN, " in french ") ||
				strstr(PLAIN, " in german ") ||
				strstr(PLAIN, " in polish ") ||
				strstr(PLAIN, " in italian ") ||
				strstr(PLAIN, " in turkish ") ||
				strstr(PLAIN, " in japanese ") ||
				strstr(PLAIN, " in chinese ") ||
				strstr(PLAIN, " in russian ") ||
				strstr(PLAIN, " in portuguese ") ||
				strstr(PLAIN, " in dutch ") ||
				strstr(PLAIN, " in arabic ")
			)
		)
	)
	{
		SAYING(
			ENGINE, "cant translate",
			"I can't translate: I only know "
			"English words. A dictionary package in my mind/memory folder "
			"could "
			"teach me some, but I don't have one yet.",
			SAY, sizeof SAY, NULL, NULL, NULL, NULL
		);
		ENGINE_SAYS(ENGINE, "can translate", "no: I only know English", SAY, 0);
		ENGINE->EXACT_REPLY = 1;
		return (1);
	}

	return (0);
}

/* "how old will I be in 5 years?", "how old was I 3 years ago?": the age
 * the user told, worked out */
static int
	USER_AGE_LATER(ENGINE_STATE *ENGINE, const char *PLAIN)
{
	char		WORDS[80][48];
	int			COUNT;
	int			INDEX;
	long long	YEARS = 0;
	int			FOUND = 0;
	char		AGE[64];
	char		SAY[800];

	if (
		!strstr(PLAIN, " how old will i be ") &&
		!strstr(PLAIN, " how old was i ") &&
		!strstr(PLAIN, " how old would i be ") &&
		!strstr(PLAIN, " how old am i going to be ")
	)
		return (0);

	COUNT = PLAIN_WORD_LIST(PLAIN, WORDS, 80);

	for (INDEX = 0; INDEX < COUNT && !FOUND; INDEX++)
	{
		long long	VALUE;

		/* "in 5 years", "after 5 years" */
		if (
			(!strcmp(WORDS[INDEX], "in") || !strcmp(WORDS[INDEX], "after")) &&
			INDEX + 2 < COUNT &&
			!strncmp(WORDS[INDEX + 2], "year", 4) &&
			NUMBER_IN_WORDS(WORDS[INDEX + 1], &VALUE)
		)
		{
			YEARS = VALUE;
			FOUND = 1;
		}
		/* "5 years ago" */
		else if (
			INDEX + 2 < COUNT &&
			!strncmp(WORDS[INDEX + 1], "year", 4) &&
			!strcmp(WORDS[INDEX + 2], "ago") &&
			NUMBER_IN_WORDS(WORDS[INDEX], &VALUE)
		)
		{
			YEARS = -VALUE;
			FOUND = 1;
		}
		else if (
			!strcmp(WORDS[INDEX], "next") &&
			INDEX + 1 < COUNT &&
			!strcmp(WORDS[INDEX + 1], "year")
		)
		{
			YEARS = 1;
			FOUND = 1;
		}
		else if (
			!strcmp(WORDS[INDEX], "last") &&
			INDEX + 1 < COUNT &&
			!strcmp(WORDS[INDEX + 1], "year")
		)
		{
			YEARS = -1;
			FOUND = 1;
		}
	}

	if (!FOUND || !YEARS)
		return (0);

	if (
		!SENSE_PROFILE_VALUE(
			ENGINE->SENSE_STATE, "you", "age", AGE, sizeof AGE
		) ||
		!isdigit((uint8_t)AGE[0])
	)
	{
		SAYING(
			ENGINE, "age not told",
			"I don't know how old you are yet. Tell "
			"me your age and I'll work it out.",
			SAY, sizeof SAY, NULL, NULL, NULL, NULL
		);
		ENGINE_SAYS(ENGINE, "you age", "you did not tell me", SAY, 0);
		ENGINE->EXACT_REPLY = 1;
		return (1);
	}

	{
		long long	NOW = atoll(AGE);
		long long	THEN = NOW + YEARS;
		char		THEN_TEXT[32];
		char		YEARS_TEXT[32];
		char		ACTION_TEXT[96];

		if (THEN < 0)
			return (0);

		snprintf(THEN_TEXT, sizeof THEN_TEXT, "%lld", THEN);
		snprintf(
			YEARS_TEXT, sizeof YEARS_TEXT, "%lld", YEARS < 0 ? -YEARS : YEARS
		);
		snprintf(
			ACTION_TEXT, sizeof ACTION_TEXT, "calc %lld %c %s", NOW,
			YEARS < 0 ? '-' : '+', YEARS_TEXT
		);

		if (YEARS > 0)
			SAYING(
				ENGINE, "age later",
				"You told me you're {1}, so in {2} "
				"year(s) you'll be {1} + {2} = {3}.",
				SAY, sizeof SAY, AGE, YEARS_TEXT, THEN_TEXT, NULL
			);
		else
			SAYING(
				ENGINE, "age before",
				"You told me you're {1}, so {2} "
				"year(s) ago you were {1} - {2} = {3}.",
				SAY, sizeof SAY, AGE, YEARS_TEXT, THEN_TEXT, NULL
			);

		/* "1 year(s)" -> "1 year", "5 year(s)" -> "5 years" */
		{
			char	*MARK = strstr(SAY, "year(s)");

			if (MARK)
				memmove(
					MARK + 4, MARK + ((YEARS == 1 || YEARS == -1) ? 7 : 6),
					strlen(MARK + ((YEARS == 1 || YEARS == -1) ? 7 : 6)) + 1
				),
					MARK[4] = (YEARS == 1 || YEARS == -1) ? MARK[4] : 's';
		}

		ENGINE_SAYS(ENGINE, ACTION_TEXT, THEN_TEXT, SAY, 1);
		ENGINE->EXACT_REPLY = 1;
	}

	return (1);
}

