static int
	KNOWLEDGE_COMMAND(KNOWLEDGE *KNOWLEDGE_BASE, const char *COMMAND_LINE)
{
	char	BUFFER[65536];

	if (!strncmp(COMMAND_LINE, "/facts", 6))
	{
		KNOWLEDGE_LIST(KNOWLEDGE_BASE, BUFFER, sizeof BUFFER);
		printf("%s", BUFFER);
		return (1);
	}

	if (!strncmp(COMMAND_LINE, "/think", 6))
	{
		printf(
			"  [last thought] %s\n",
			KNOWLEDGE_BASE->LAST_REPLY[0] ? KNOWLEDGE_BASE->LAST_REPLY
			: "nothing yet"
		);
		return (1);
	}

	if (!strncmp(COMMAND_LINE, "/forget-facts", 13))
	{
		KNOWLEDGE_RESET(KNOWLEDGE_BASE);
		MAKE_DIRECTORY_PATH(GLOBAL_DIRECTORY);
		KNOWLEDGE_SAVE(KNOWLEDGE_BASE, KNOW_PATH);
		printf("  [know] all facts forgotten\n");
		return (1);
	}

	return (0);
}

static int
	KNOWLEDGE_LOOP(void)
{
	KNOWLEDGE	*KNOWLEDGE_BASE = KNOWLEDGE_NEW();

	KNOWLEDGE_LOAD(KNOWLEDGE_BASE, KNOW_PATH);
	printf("Code knowledge core (no neural brain loaded). Teach facts, ask "
		"questions. /facts /think /forget-facts /quit\n");

	char	INPUT_LINE[4096];
	char	OUTPUT[8192];

	for (;;)
	{
		printf("know> ");
		fflush(stdout);

		if (!fgets(INPUT_LINE, sizeof INPUT_LINE, stdin))
			break ;

		size_t	LINE_LENGTH = strlen(INPUT_LINE);

		while (
			LINE_LENGTH &&
			(
				INPUT_LINE[LINE_LENGTH - 1] == '\n' ||
				INPUT_LINE[LINE_LENGTH - 1] == '\r' ||
				INPUT_LINE[LINE_LENGTH - 1] == ' '
			)
		)
			INPUT_LINE[--LINE_LENGTH] = 0;

		char	*LINE_START = INPUT_LINE;

		while (*LINE_START == ' ')
			LINE_START++;

		if (!*LINE_START)
			continue ;

		if (
			!strncmp(LINE_START, "/quit", 5) ||
			!strncmp(LINE_START, "/exit", 5)
		)
			break ;

		if (*LINE_START == '/')
		{
			if (!KNOWLEDGE_COMMAND(KNOWLEDGE_BASE, LINE_START))
				printf("  commands: /facts /think /forget-facts /quit\n");

			continue ;
		}

		int	HEARD_KIND =
			KNOWLEDGE_HEAR(KNOWLEDGE_BASE, LINE_START, OUTPUT, sizeof OUTPUT);

		if (HEARD_KIND == HEAR_NONE)
			printf("  (not a fact or question I can read yet)\n");
		else
		{
			char	*CURSOR = OUTPUT;

			while (*CURSOR)
			{
				char	*LINE_END = strchr(CURSOR, '\n');

				printf(
					"  %.*s\n",
					LINE_END ? (int)(LINE_END - CURSOR) : (int)strlen(CURSOR),
					CURSOR
				);

				if (!LINE_END)
					break ;

				CURSOR = LINE_END + 1;
			}
		}

		if (KNOWLEDGE_BASE->IS_DIRTY)
		{
			MAKE_DIRECTORY_PATH(GLOBAL_DIRECTORY);
			KNOWLEDGE_SAVE(KNOWLEDGE_BASE, KNOW_PATH);
		}
	}

	KNOWLEDGE_FREE(KNOWLEDGE_BASE);

	return (0);
}

int
	main(int ARGUMENT_COUNT, char **ARGUMENTS)
{
	ENGINE_STATE	ENGINE;

	memset(&ENGINE, 0, sizeof ENGINE);
	SESSION_START_TIME = (long)time(NULL);

	/* the folders of an older Lucy move into mind and mind_original */
	{
		char	MOVED[2000];

		if (MIND_MIGRATE(MOVED, sizeof MOVED))
			fprintf(stderr, "[mind] moved to the new folders: %s\n", MOVED);
	}

	snprintf(ENGINE.CHAT_NAME, sizeof ENGINE.CHAT_NAME, "main");

	const char	*USER_NAME = getenv("USERNAME");

	if (!USER_NAME)
		USER_NAME = getenv("USER");

	snprintf(
		ENGINE.USER_NAME, sizeof ENGINE.USER_NAME, "%s",
		USER_NAME && *USER_NAME ? USER_NAME : "friend"
	);
	ENGINE.GROUNDING_ON = 1;
	ENGINE.TEMPERATURE = (float)0.7;
	ENGINE.TOP_PROBABILITY = (float)0.9;
	ENGINE.LEARNING_RATE = (float)3e-5;
	ENGINE.MAXIMUM_REPLY_LENGTH = 60;
	ENGINE.LEARNING_ON = 1;
	ENGINE.CANDIDATE_COUNT = 4;
	ENGINE.OPTIMIZER_EPSILON = (float)1e-2;
	ENGINE.COPY_CONSTRAINT_ON = 1;
	ENGINE.PICK_TEMPERATURE = (float)0.15;
	ENGINE.NEIGHBORS_ON = 1;
	ENGINE.NEIGHBOR_THRESHOLD = (float)0.82;
	ENGINE.NEIGHBOR_MIX = (float)0.6;
	ENGINE.ACTION_GUARD_ON = 1;
	ENGINE.QUESTION_GATE = 1;
	ENGINE.RANDOM_STATE =
		(uint64_t)time(NULL) * (unsigned long long)2654435761 ^
		(uint64_t)clock();

	const char	*SCRIPT_PATH = NULL;
	int			RUN_SELF_TEST = 0;
	int			EVAL_SHOW = 0;
	int			MIND_SETTING = 0;
	int			AGENTS_SETTING = 0;
	int			NO_SENSE = 0;
	const char	*EVAL_PATH = NULL;
	int			INDEX;

	for (INDEX = 1; INDEX < ARGUMENT_COUNT; INDEX++)
	{
		const char	*ARGUMENT_VALUE =
			INDEX + 1 < ARGUMENT_COUNT ? ARGUMENTS[INDEX + 1] : NULL;

		if (!strcmp(ARGUMENTS[INDEX], "--chat") && ARGUMENT_VALUE)
		{
			snprintf(
				ENGINE.CHAT_NAME, sizeof ENGINE.CHAT_NAME, "%s", ARGUMENT_VALUE
			);
			INDEX++;
		}
		else if (!strcmp(ARGUMENTS[INDEX], "--name") && ARGUMENT_VALUE)
		{
			snprintf(
				ENGINE.USER_NAME, sizeof ENGINE.USER_NAME, "%s", ARGUMENT_VALUE
			);
			INDEX++;
		}
		else if (!strcmp(ARGUMENTS[INDEX], "--seed") && ARGUMENT_VALUE)
		{
			ENGINE.RANDOM_STATE = strtoull(ARGUMENT_VALUE, NULL, 10) *
					(unsigned long long)2654435761 +
				1;
			INDEX++;
		}
		else if (!strcmp(ARGUMENTS[INDEX], "--temp") && ARGUMENT_VALUE)
		{
			ENGINE.TEMPERATURE = (float)atof(ARGUMENT_VALUE);
			INDEX++;
		}
		else if (!strcmp(ARGUMENTS[INDEX], "--no-learn"))
			ENGINE.LEARNING_ON = 0;
		else if (!strcmp(ARGUMENTS[INDEX], "--verbose"))
			ENGINE.VERBOSE = 1;
		else if (!strcmp(ARGUMENTS[INDEX], "--selftest"))
			RUN_SELF_TEST = 1;
		else if (!strcmp(ARGUMENTS[INDEX], "--no-ground"))
			ENGINE.GROUNDING_ON = 0;
		else if (!strcmp(ARGUMENTS[INDEX], "--script") && ARGUMENT_VALUE)
		{
			SCRIPT_PATH = ARGUMENT_VALUE;
			INDEX++;
		}
		else if (!strcmp(ARGUMENTS[INDEX], "--eval") && ARGUMENT_VALUE)
		{
			EVAL_PATH = ARGUMENT_VALUE;
			INDEX++;
		}
		else if (!strcmp(ARGUMENTS[INDEX], "--score-file") && ARGUMENT_VALUE)
		{
			SCORE_FILE_PATH = ARGUMENT_VALUE;
			INDEX++;
		}
		else if (!strcmp(ARGUMENTS[INDEX], "--split-test") && ARGUMENT_VALUE)
		{
			FILE	*STREAM = fopen(ARGUMENT_VALUE, "rb");
			char	SPLIT_LINE[4096];
			char	LINE_PARTS[8][1024];

			while (STREAM && fgets(SPLIT_LINE, sizeof SPLIT_LINE, STREAM))
			{
				size_t	LINE_LENGTH = strlen(SPLIT_LINE);

				while (
					LINE_LENGTH &&
					(
						SPLIT_LINE[LINE_LENGTH - 1] == '\n' ||
						SPLIT_LINE[LINE_LENGTH - 1] == '\r'
					)
				)
					SPLIT_LINE[--LINE_LENGTH] = 0;

				int	PART_COUNT = SPLIT_PARTS(SPLIT_LINE, LINE_PARTS, 8);

				if (PART_COUNT <= 1)
					printf("%s\n", SPLIT_LINE);
				else
				{
					int	INNER_INDEX;

					for (
						INNER_INDEX = 0;
						INNER_INDEX < PART_COUNT;
						INNER_INDEX++
					)
						printf(
							"%s%s", LINE_PARTS[INNER_INDEX],
							INNER_INDEX < PART_COUNT - 1 ? " || " : "\n"
						);
				}
			}

			if (STREAM)
				fclose(STREAM);

			return (0);
		}
		else if (!strcmp(ARGUMENTS[INDEX], "--show"))
			EVAL_SHOW = 1;
		else if (!strcmp(ARGUMENTS[INDEX], "--cands") && ARGUMENT_VALUE)
		{
			ENGINE.CANDIDATE_COUNT = atoi(ARGUMENT_VALUE);
			INDEX++;
		}
		else if (!strcmp(ARGUMENTS[INDEX], "--oeps") && ARGUMENT_VALUE)
		{
			ENGINE.OPTIMIZER_EPSILON = (float)atof(ARGUMENT_VALUE);
			INDEX++;
		}
		else if (!strcmp(ARGUMENTS[INDEX], "--free-actions"))
			ENGINE.COPY_CONSTRAINT_ON = 0;
		else if (!strcmp(ARGUMENTS[INDEX], "--mind"))
			MIND_SETTING = 1;
		else if (!strcmp(ARGUMENTS[INDEX], "--pick") && ARGUMENT_VALUE)
		{
			ENGINE.PICK_TEMPERATURE = (float)atof(ARGUMENT_VALUE);
			INDEX++;
		}
		else if (!strcmp(ARGUMENTS[INDEX], "--no-mind"))
			MIND_SETTING = -1;
		else if (!strcmp(ARGUMENTS[INDEX], "--agents"))
			AGENTS_SETTING = 1;
		else if (!strcmp(ARGUMENTS[INDEX], "--free-voice"))
			ENGINE.FREE_VOICE = 1;
		else if (!strcmp(ARGUMENTS[INDEX], "--engine-voice"))
			ENGINE.ENGINE_VOICE = 1;
		else if (!strcmp(ARGUMENTS[INDEX], "--no-agents"))
			AGENTS_SETTING = -1;
		else if (!strcmp(ARGUMENTS[INDEX], "--mmi") && ARGUMENT_VALUE)
		{
			ENGINE.MUTUAL_INFO_WEIGHT = (float)atof(ARGUMENT_VALUE);
			INDEX++;
		}
		else if (!strcmp(ARGUMENTS[INDEX], "--no-reflex"))
			ENGINE.REFLEXES_ON = -1;
		else if (!strcmp(ARGUMENTS[INDEX], "--no-instant"))
			ENGINE.NEIGHBORS_ON = 0;
		else if (!strcmp(ARGUMENTS[INDEX], "--no-guard"))
			ENGINE.ACTION_GUARD_ON = 0;
		else if (!strcmp(ARGUMENTS[INDEX], "--no-qgate"))
			ENGINE.QUESTION_GATE = 0;
		else if (!strcmp(ARGUMENTS[INDEX], "--no-merge"))
			INTERJECTION_MERGE_ON = 0;
		else if (!strcmp(ARGUMENTS[INDEX], "--no-sense"))
			NO_SENSE = 1;
		else if (
			!strcmp(ARGUMENTS[INDEX], "--sense-filter") &&
			ARGUMENT_VALUE &&
			INDEX + 2 < ARGUMENT_COUNT
		)
			return (
				SENSE_FILTER_CHATS(
					ARGUMENT_VALUE, ARGUMENTS[INDEX + 2],
					INDEX + 3 < ARGUMENT_COUNT &&
						!strcmp(ARGUMENTS[INDEX + 3], "--show")
				)
			);
		else if (!strcmp(ARGUMENTS[INDEX], "--sense-eval") && ARGUMENT_VALUE)
		{
			int	SHOW_DETAILS = INDEX + 2 < ARGUMENT_COUNT &&
				!strcmp(ARGUMENTS[INDEX + 2], "--show");

			return (SENSE_RUN_SCRIPT_FILE(ARGUMENT_VALUE, SHOW_DETAILS));
		}
		else if (!strcmp(ARGUMENTS[INDEX], "--instant-eval"))
			ENGINE.NEIGHBOR_EVALUATION = 1;
		else if (!strcmp(ARGUMENTS[INDEX], "--instant-thr") && ARGUMENT_VALUE)
		{
			ENGINE.NEIGHBOR_THRESHOLD = (float)atof(ARGUMENT_VALUE);
			INDEX++;
		}
		else if (!strcmp(ARGUMENTS[INDEX], "--instant-mix") && ARGUMENT_VALUE)
		{
			ENGINE.NEIGHBOR_MIX = (float)atof(ARGUMENT_VALUE);
			INDEX++;
		}
		else if (!strcmp(ARGUMENTS[INDEX], "--lr") && ARGUMENT_VALUE)
		{
			ENGINE.LEARNING_RATE = (float)atof(ARGUMENT_VALUE);
			INDEX++;
		}
		else if (!strcmp(ARGUMENTS[INDEX], "--know"))
			return (KNOWLEDGE_LOOP());
		else if (!strcmp(ARGUMENTS[INDEX], "--know-eval") && ARGUMENT_VALUE)
		{
			int	SHOW_DETAILS = INDEX + 2 < ARGUMENT_COUNT &&
				!strcmp(ARGUMENTS[INDEX + 2], "--show");

			return (KNOWLEDGE_SCRIPT_FILE(ARGUMENT_VALUE, SHOW_DETAILS));
		}
	}

	char	*NAME_CURSOR;

	for (NAME_CURSOR = ENGINE.USER_NAME; *NAME_CURSOR; NAME_CURSOR++)
		*NAME_CURSOR =
			(char)(isalnum((uint8_t)*NAME_CURSOR) ? tolower(*NAME_CURSOR) : '_'
			);

	if (!ENGINE.RANDOM_STATE)
		ENGINE.RANDOM_STATE = 1;

	if (!CPU_SUPPORTED())
	{
		printf("This CPU lacks AVX2/FMA, which Code's JIT needs.\n");
		return (1);
	}

	int	REFLEXES_OFF = ENGINE.REFLEXES_ON < 0;

	ENGINE.REFLEXES_ON = 0;

	if (!NO_SENSE)
	{
		ENGINE.SENSE_STATE = SENSE_CREATE(SENSE_PATH);
		ENGINE.SENSE_ON =
			ENGINE.SENSE_STATE && SENSE_VERB_COUNT(ENGINE.SENSE_STATE) > 0;

		if (!ENGINE.SENSE_ON)
			printf("note: %s missing, the sense core is off\n", SENSE_PATH);
	}

	if (EVAL_PATH)
	{
		ENGINE.SENSE_EVALUATION = 1;
		snprintf(ENGINE.CHAT_NAME, sizeof ENGINE.CHAT_NAME, "eval");
		snprintf(ENGINE.USER_NAME, sizeof ENGINE.USER_NAME, "tester");
		ENGINE.LEARNING_ON = 0;

		if (OPEN_ENGINE(&ENGINE))
			return (1);

		LOAD_SAFE_WORDS(&ENGINE);

		if (ENGINE.SENSE_STATE && ENGINE.ASSISTANT_NAME[0])
			SENSE_SET_NAME(ENGINE.SENSE_STATE, ENGINE.ASSISTANT_NAME);

		NEAREST_NEIGHBOR_INITIALIZE(
			&ENGINE.NEIGHBOR_INDEX,
			ENGINE.LOADED_BRAIN.NEURAL_WEB->CONFIGURATION.DIMENSION, 2000
		);

		if (!ENGINE.NEIGHBOR_EVALUATION)
			ENGINE.NEIGHBORS_ON = 0;

		return (RUN_EVALUATION(&ENGINE, EVAL_PATH, EVAL_SHOW));
	}

	if (RUN_SELF_TEST)
	{
		snprintf(ENGINE.CHAT_NAME, sizeof ENGINE.CHAT_NAME, "selftest");
		snprintf(ENGINE.USER_NAME, sizeof ENGINE.USER_NAME, "tester");
	}

	if (OPEN_ENGINE(&ENGINE))
		return (1);

	LOAD_SAFE_WORDS(&ENGINE);
	OPEN_NEIGHBOR_INDEX(&ENGINE);

	if (RUN_SELF_TEST)
	{
		if (ENGINE.SENSE_STATE && ENGINE.ASSISTANT_NAME[0])
			SENSE_SET_NAME(ENGINE.SENSE_STATE, ENGINE.ASSISTANT_NAME);

		return (SELF_TEST(&ENGINE));
	}

	if (ENGINE.SENSE_STATE)
	{
		char	PROFILE_PATH[600];

		/* the person's own profile; an older Lucy kept it with the general
		 * memory */
		PERSON_PATH(
			ENGINE.USER_NAME, "profile.txt", PROFILE_PATH, sizeof PROFILE_PATH
		);

		if (!FILE_EXISTS(PROFILE_PATH))
			snprintf(
				PROFILE_PATH, sizeof PROFILE_PATH,
				GLOBAL_DIRECTORY "/profile_%s.txt", ENGINE.USER_NAME
			);

		SENSE_LOAD_PROFILE(ENGINE.SENSE_STATE, PROFILE_PATH);

		if (ENGINE.ASSISTANT_NAME[0])
			SENSE_SET_NAME(ENGINE.SENSE_STATE, ENGINE.ASSISTANT_NAME);
	}

	ENGINE.KNOWLEDGE_BASE = KNOWLEDGE_NEW();
	KNOWLEDGE_LOAD(ENGINE.KNOWLEDGE_BASE, KNOW_PATH);
	ENGINE.REFLEXES_ON = !REFLEXES_OFF;
	ENGINE.ENGINE_LOCK = THREAD_NEW_MUTEX();
	ENGINE.LAST_INPUT_TIME = THREAD_NOW_SECONDS();

	if (
		MIND_SETTING > 0 ||
		(MIND_SETTING == 0 && !SCRIPT_PATH && isatty(fileno(stdin)))
	)
	{
		ENGINE.MIND_ON = 1;
		THREAD_SPAWN(MIND_THREAD, &ENGINE);
	}

	FILE	*INPUT_STREAM = stdin;

	if (SCRIPT_PATH)
	{
		INPUT_STREAM = fopen(SCRIPT_PATH, "r");

		if (!INPUT_STREAM)
		{
			printf("cannot open %s\n", SCRIPT_PATH);
			return (1);
		}
	}

	/* the agents: an input agent reads while Lucy works, job agents study
	 * files; scripts and piped tests stay one line at a time unless asked */
	char	*INPUT_LINE = NULL;
	int		ECHO_INPUT = SCRIPT_PATH != NULL;
	int		JOIN_PASTES = 0;

	ENGINE.JOBS = JOB_BOARD_NEW();

	if (
		AGENTS_SETTING > 0 ||
		(AGENTS_SETTING == 0 && !SCRIPT_PATH && isatty(fileno(stdin)))
	)
	{
		ENGINE.INBOX = MAILBOX_NEW();
		ENGINE.AGENTS_ON = ENGINE.INBOX != NULL;

		if (ENGINE.AGENTS_ON)
			INPUT_AGENT_START(ENGINE.INBOX, INPUT_STREAM);

		ECHO_INPUT = ECHO_INPUT || !isatty(fileno(INPUT_STREAM));

		/* a text pasted at the keyboard arrives as one burst of lines: one
		 * message (a piped file arrives in one burst too, so not there) */
		JOIN_PASTES = isatty(fileno(INPUT_STREAM));
	}

	for (;;)
	{
		printf("$> ");
		fflush(stdout);
		free(INPUT_LINE);
		INPUT_LINE = NULL;

		if (!ENGINE.AGENTS_ON)
		{
			JOB	*FINISHED;

			/* a reminder that came due while the last message was read */
			while ((FINISHED = JOB_TAKE_FINISHED(ENGINE.JOBS)))
				if (REPORT_JOB(&ENGINE, FINISHED))
				{
					printf("\n$> ");
					fflush(stdout);
				}

			INPUT_LINE = READ_WHOLE_LINE(INPUT_STREAM);
		}
		else
			for (;;)
			{
				JOB	*FINISHED;

				if (JOIN_PASTES)
					INPUT_LINE = MAILBOX_WAIT_PASTE(ENGINE.INBOX, 100);
				else
					INPUT_LINE = MAILBOX_WAIT(ENGINE.INBOX, 100);

				if (INPUT_LINE)
					break ;

				/* a job finished while nobody was typing: it says so */
				FINISHED = JOB_TAKE_FINISHED(ENGINE.JOBS);

				if (FINISHED)
				{
					if (REPORT_JOB(&ENGINE, FINISHED))
					{
						printf("\n$> ");
						fflush(stdout);
					}

					continue ;
				}

				/* the input is over: wait for the jobs, then stop */
				if (
					MAILBOX_IS_DONE(ENGINE.INBOX) &&
					!JOB_RUNNING_COUNT(ENGINE.JOBS)
				)
					break ;
			}

		if (!INPUT_LINE)
			break ;

		if (ECHO_INPUT)
			printf("%s\n", INPUT_LINE);

		/* "/paste": every line up to "/end" is one message, line breaks and
		 * all (a long text with paragraphs) */
		if (!strcmp(INPUT_LINE, "/paste"))
		{
			char	*TEXT = calloc(1, 1);
			size_t	LENGTH = 0;

			printf("  [paste] send the text, then /end on its own line\n");
			fflush(stdout);

			for (;;)
			{
				char	*LINE;

				if (ENGINE.AGENTS_ON)
					LINE = MAILBOX_WAIT(ENGINE.INBOX, -1);
				else
					LINE = READ_WHOLE_LINE(INPUT_STREAM);

				char	*BIGGER;

				if (!LINE || !strcmp(LINE, "/end"))
				{
					free(LINE);
					break ;
				}

				if (TEXT)
					BIGGER = realloc(TEXT, LENGTH + strlen(LINE) + 2);
				else
					BIGGER = NULL;

				if (BIGGER)
				{
					TEXT = BIGGER;
					LENGTH += (size_t
					)sprintf(TEXT + LENGTH, "%s%s", LENGTH ? "\n" : "", LINE);
				}

				free(LINE);
			}

			free(INPUT_LINE);
			INPUT_LINE = TEXT;

			if (!INPUT_LINE)
				break ;
		}

		char	*INPUT_CURSOR = INPUT_LINE;

		while (*INPUT_CURSOR == ' ')
			INPUT_CURSOR++;

		if (!*INPUT_CURSOR)
			continue ;

		printf("\n");
		THREAD_LOCK(ENGINE.ENGINE_LOCK);
		ENGINE.LAST_INPUT_TIME = THREAD_NOW_SECONDS();
		ENGINE.QUIET_LOGGED = 0;

		/* "/wait 5": five seconds go by (for tests), and what comes due in
		 * them is said */
		if (!strncmp(INPUT_CURSOR, "/wait", 5))
		{
			double	SECONDS = atof(INPUT_CURSOR + 5);
			double	UNTIL;

			THREAD_UNLOCK(ENGINE.ENGINE_LOCK);
			UNTIL = THREAD_NOW_SECONDS() + (SECONDS > 0 ? SECONDS : 1);

			while (THREAD_NOW_SECONDS() < UNTIL)
			{
				JOB	*FINISHED = JOB_TAKE_FINISHED(ENGINE.JOBS);

				if (FINISHED)
				{
					if (REPORT_JOB(&ENGINE, FINISHED))
						printf("\n");

					continue ;
				}

				THREAD_SLEEP_MILLISECONDS(50);
			}

			continue ;
		}

		if (!strncmp(INPUT_CURSOR, "/rule ", 6))
		{
			RULE_COMMAND(&ENGINE, INPUT_CURSOR + 6);
			printf("\n");
			THREAD_UNLOCK(ENGINE.ENGINE_LOCK);
			continue ;
		}

		if (!strncmp(INPUT_CURSOR, "/reflexes", 9))
		{
			SHOW_REFLEXES(&ENGINE);
			printf("\n");
			THREAD_UNLOCK(ENGINE.ENGINE_LOCK);
			continue ;
		}

		if (!strncmp(INPUT_CURSOR, "/mind", 5))
		{
			SHOW_MIND(&ENGINE);
			printf("\n");
			THREAD_UNLOCK(ENGINE.ENGINE_LOCK);
			continue ;
		}

		if (!strncmp(INPUT_CURSOR, "/jobs", 5))
		{
			char	LIST[4096];

			JOB_LIST(ENGINE.JOBS, LIST, sizeof LIST);
			printf("%s\n", LIST);
			THREAD_UNLOCK(ENGINE.ENGINE_LOCK);
			continue ;
		}

		/* the skills in mind/skills and the packages in mind/memory */
		if (
			!strncmp(INPUT_CURSOR, "/skills", 7) ||
			!strncmp(INPUT_CURSOR, "/packages", 9)
		)
		{
			char	LIST[8192];

			if (INPUT_CURSOR[1] == 's')
			{
				if (!ENGINE.SKILLS_OPENED)
					OPEN_SKILLS(&ENGINE);

				SKILLS_REFRESH(&ENGINE.SKILLS, LIST, sizeof LIST);
				SKILLS_LIST(&ENGINE.SKILLS, LIST, sizeof LIST);
				printf(
					"  [skills] %s\n",
					LIST[0] ? LIST : "none: put skill libraries in mind/skills"
				);
			}
			else
			{
				if (
					ENGINE.PACKAGES_OPENED &&
					PACKAGES_REFRESH(&ENGINE.PACKAGES, LIST, sizeof LIST)
				)
					REBUILD_PACKAGE_TOPICS(&ENGINE);

				PACKAGES_LIST(&ENGINE.PACKAGES, LIST, sizeof LIST);
				printf(
					"  [packages] %s\n",
					LIST[0] ? LIST : "none: put .mem packages in mind/memory"
				);
			}

			THREAD_UNLOCK(ENGINE.ENGINE_LOCK);
			continue ;
		}

		/* "stop" while a job works stops the job (a change kept for later
		 * is called off by the work itself, which says which one) */
		if (
			(
				!strncmp(INPUT_CURSOR, "/stop", 5) ||
				IS_STOP_MESSAGE(INPUT_CURSOR)
			) &&
			JOB_RUNNING_COUNT(ENGINE.JOBS) &&
			JOB_RUNNING_COUNT(ENGINE.JOBS) >
				JOB_KIND_COUNT(ENGINE.JOBS, "later")
		)
		{
			JOB_STOP_ALL(ENGINE.JOBS);
			SAY_LINE(&ENGINE, INPUT_CURSOR, "Okay, I'm stopping.");
			printf("\n");
			THREAD_UNLOCK(ENGINE.ENGINE_LOCK);
			continue ;
		}

		if (KNOWLEDGE_COMMAND(ENGINE.KNOWLEDGE_BASE, INPUT_CURSOR))
		{
			printf("\n");
			THREAD_UNLOCK(ENGINE.ENGINE_LOCK);
			continue ;
		}

		if (!strncmp(INPUT_CURSOR, "/sleep", 6))
		{
			SLEEP_COMMAND(&ENGINE);
			printf("\n");
			THREAD_UNLOCK(ENGINE.ENGINE_LOCK);
			continue ;
		}

		if (
			!strncmp(INPUT_CURSOR, "/quit", 5) ||
			!strncmp(INPUT_CURSOR, "/exit", 5)
		)
		{
			THREAD_UNLOCK(ENGINE.ENGINE_LOCK);
			break ;
		}

		if (*INPUT_CURSOR == '/')
		{
			if (
				!strncmp(INPUT_CURSOR, "/quit", 5) ||
				!strncmp(INPUT_CURSOR, "/exit", 5)
			)
				break ;
			else if (!strncmp(INPUT_CURSOR, "/teachself ", 11))
				TEACH(&ENGINE, INPUT_CURSOR + 11, 1);
			else if (!strncmp(INPUT_CURSOR, "/teach ", 7))
				TEACH(&ENGINE, INPUT_CURSOR + 7, 0);
			else if (!strncmp(INPUT_CURSOR, "/learn ", 7))
			{
				if (ENGINE.LEARNING_ON)
					LEARN_FILE(&ENGINE, INPUT_CURSOR + 7);
				else
					printf("  [play mode (--no-learn): the brain does not "
						"change]\n");
			}
			else if (!strncmp(INPUT_CURSOR, "/thought", 8))
				SHOW_THOUGHT(&ENGINE);
			else if (!strncmp(INPUT_CURSOR, "/history", 8))
				SHOW_HISTORY(
					&ENGINE,
					INPUT_CURSOR[8] ? atoi(INPUT_CURSOR + 8) > 0
							? atoi(INPUT_CURSOR + 8)
							: 30
									: 30
				);
			else if (!strncmp(INPUT_CURSOR, "/status", 7))
				SHOW_STATUS(&ENGINE);
			else if (!strncmp(INPUT_CURSOR, "/brain", 6))
				SHOW_BRAIN(&ENGINE);
			else if (!strncmp(INPUT_CURSOR, "/reset-learning", 15))
			{
				if (!ENGINE.LEARNING_ON)
					printf("  [play mode (--no-learn): nothing to reset]\n");
				else
				{
					int	PART_COUNT =
						LEARN_PERSONAL(ENGINE.LOADED_BRAIN.NEURAL_WEB, 64, 1);

					ENGINE.BRAIN_DIRTY = 1;
					ENGINE.PREFIX_CACHE_VALID = 0;
					SAVE_ENGINE(&ENGINE, 1);
					printf(
						"  [learning] %d personal neurons reset to silent; the "
						"main brain was never changed by chat\n",
						PART_COUNT
					);
				}
			}
			else if (!strncmp(INPUT_CURSOR, "/context", 8))
				SHOW_CONTEXT(&ENGINE);
			else if (!strncmp(INPUT_CURSOR, "/neuron ", 8))
				SHOW_NEURON(&ENGINE, atoi(INPUT_CURSOR + 8));
			else if (!strncmp(INPUT_CURSOR, "/do ", 4))
			{
				int32_t	INPUT_IDS[WORKING_MEMORY_IDS];
				int32_t	RESULT_IDS[WORKING_MEMORY_IDS];
				char	RESULT_TEXT[4096];
				int		COUNT = TEXT_TO_WORD_IDS(
					&ENGINE, INPUT_CURSOR + 4, INPUT_IDS, WORKING_MEMORY_IDS, 1
				);
				int		RESULT_COUNT = RUN_ACTION(
					&ENGINE, INPUT_IDS, COUNT, RESULT_IDS, WORKING_MEMORY_IDS
				);

				WORD_IDS_TO_TEXT(
					&ENGINE, RESULT_IDS, RESULT_COUNT, RESULT_TEXT,
					sizeof RESULT_TEXT
				);
				printf("  [%s]\n", RESULT_TEXT);
				SAVE_ENGINE(&ENGINE, 0);
			}
			else if (!strncmp(INPUT_CURSOR, "/save", 5))
			{
				ENGINE.BRAIN_DIRTY = 1;
				SAVE_ENGINE(&ENGINE, 1);
				printf("  [saved]\n");
			}
			else
				SHOW_HELP();

			printf("\n");
			THREAD_UNLOCK(ENGINE.ENGINE_LOCK);
			continue ;
		}

		/* "also ..." typed while Lucy works joins this message between its
		 * parts (CHECK_MAIL_DURING_TURN); otherwise it is the next message */
		RESPOND(&ENGINE, INPUT_CURSOR, NULL, 0);

		printf("\n");
		THREAD_UNLOCK(ENGINE.ENGINE_LOCK);
	}

	free(INPUT_LINE);

	/* reminders still waiting end with the program; jobs still working are
	 * asked to stop, and get a moment to do it */
	JOB_STOP_KIND(ENGINE.JOBS, "reminder");

	if (JOB_STOP_ALL(ENGINE.JOBS))
	{
		int	WAITED;

		for (
			WAITED = 0;
			WAITED < 300 && JOB_RUNNING_COUNT(ENGINE.JOBS);
			WAITED++
		)
			THREAD_SLEEP_MILLISECONDS(10);
	}

	ENGINE.QUIT_REQUESTED = 1;
	THREAD_LOCK(ENGINE.ENGINE_LOCK);
	SAVE_ENGINE(&ENGINE, 1);
	THREAD_UNLOCK(ENGINE.ENGINE_LOCK);

	if (SCRIPT_PATH)
		fclose(INPUT_STREAM);

	return (0);
}
